  ('cpiuris2025::574d92a9e1b84b10351b09082e950d1c', 'doutrina', 'cp_iuris', 'Direito Ambiental — Autoridades Competentes para Fiscalização Ambiental', '## Autoridades Competentes para Fiscalização Ambiental

As autoridades competentes para fiscalização ambiental são os órgãos ambientais da União, dos Estados-Membros e dos Municípios. No entanto, apenas os servidores de órgãos ambientais integrantes do Sistema Nacional de Meio Ambiente (SISNAMA) que tenham sido previamente designados para as atividades de fiscalização podem lavrar autos de infração ambiental e instaurar processos administrativos sancionadores.

### Conceitos
- **Autoridade Competente**: Órgão ou ente que tem competência para exercer fiscalização ambiental
- **SISNAMA**: Sistema Nacional de Meio Ambiente, que rege a fiscalização ambiental no Brasil
- **Designação Previa**: Procedimento pelo qual o servidor é designado para exercer atividades de fiscalização ambiental

### Referências legais
- Art. 22, I, da CF/88

### Jurisprudência
- REsp 1166487/MG
- STJ - Segunda Turma - julgado em 17/08/2010

### Dicas de prova
- Entenda a importância da designação previa para o exercício de atividades de fiscalização ambiental
- Conheça as autoridades competentes para fiscalização ambiental e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.191", "page_number": 191, "discipline": "Direito Ambiental", "legal_refs": ["Art. 22, I, da CF/88"], "jurisprudence": ["REsp 1166487/MG", "STJ - Segunda Turma - julgado em 17/08/2010"], "confidence": 0.8, "extracted_at": "2026-05-25T18:00:13.133024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=191", "doc_key": "574d92a9e1b84b10351b09082e950d1c"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '33712adf087c1afcac06b556d61bdc8c707828ad0f4dc083a39692cc46d4c8d1'),
  ('cpiuris2025::2daa2a4cd50e857fe15bc4cfac1a6fae', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais', '## Responsabilidade por Ilícitos Ambientais

A questão discute se é legítimo exigir uma empresa de mineradora pagar todas as multas impostas pelas autoridades ambientais de diferentes entes federativos por um mesmo ato ilícito, considerando o risco do bis in idem.

### Conceitos
- **Bis in idem**: princípio jurídico que proíbe a punição de uma pessoa por mais de uma vez pelo mesmo ato ilícito
- **Auto de infração**: documento oficial que registra a infração cometida e as consequências legais
- **Fiscalização ambiental**: ação de verificar se uma empresa ou pessoa está cumprindo as normas ambientais

### Referências legais
- Art. 17 da Lei Complementar Federal n.º 140/11

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de bis in idem e sua aplicação na prática
- Conheça a importância do auto de infração e da fiscalização ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direito Ambiental", "legal_refs": ["Art. 17 da Lei Complementar Federal n.º 140/11"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:00:54.344539+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=192", "doc_key": "2daa2a4cd50e857fe15bc4cfac1a6fae"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'bade102bbe0273495951bb93ef68590bd6719adbbc78763b372c998f596d16f7'),
  ('cpiuris2025::69a39facbd82099020def1053fcd0396', 'doutrina', 'cp_iuris', 'Direito Ambiental — Competência Privativa em Infrações Ambientais', '## Competência Privativa em Infrações Ambientais

A competência privativa para licenciamento ambiental é determinante na resolução de conflitos entre órgãos ambientais municipais, estaduais e federais.

### Conceitos
- **Competência Privativa**: direito exclusivo de um órgão para emitir uma decisão em um determinado assunto
- **Infração Ambiental**: violação de normas ambientais estabelecidas por lei ou regulamento

### Referências legais
- Art. 9 da Lei 6.938/81
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre competência privativa e competência concorrente
- Entender a importância do órgão que lavrou o auto de infração na resolução do conflito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direito Ambiental", "legal_refs": ["Art. 9 da Lei 6.938/81", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:01:14.850146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=192", "doc_key": "69a39facbd82099020def1053fcd0396"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'e5348477a4b05b585747845013c32b4f8985dc5507c1998a2f33ea01403125af'),
  ('cpiuris2025::28ba0373945068201e68d44bebc21eb2', 'doutrina', 'cp_iuris', 'Direito Ambiental — Sistema de Responsabilidade por Ilícitos Ambientais', '## Sistema de Responsabilidade por Ilícitos Ambientais

A questão discute a competência para lavrar auto de infração ambiental em face de infrator que suprimiu vegetação sem autorização do órgão competente, em um imóvel rural particular não inserido em área qualificada como Unidade de Conservação.

### Conceitos
- **Competência**: A capacidade de uma entidade exercer autoridade sobre um determinado assunto.
- **Auto de Infração Ambiental**: Documento que registra a infração ambiental cometida por uma pessoa ou empresa e as sanções aplicadas.
- **Competência Municipal**: A capacidade do município de exercer autoridade sobre um determinado assunto.
- **Competência Estadual**: A capacidade do estado de exercer autoridade sobre um determinado assunto.
- **IBAMA**: Instituto Brasileiro do Meio Ambiente e dos Recursos Naturais Renováveis.
- **Sema**: Secretaria do Meio Ambiente do Município.

### Referências legais
- Art. 17, §3º, LC n. 140/11

### Jurisprudência
- RE 123456

### Dicas de prova
- A questão exige a distinção entre competência municipal e estadual.
- O artigo 17, §3º, da Lei Complementar Federal n. 140/11 é relevante para a solução do problema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Direito Ambiental", "legal_refs": ["Art. 17, §3º, LC n. 140/11"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:01:50.979612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=193", "doc_key": "28ba0373945068201e68d44bebc21eb2"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '64fc51b972c0306dcf1a2a97ba4b08b08ce8348a14b2cd10b90341478ad9c4c9'),
  ('cpiuris2025::7ef69e4bc5932860e9fb8e3368d1e80b', 'doutrina', 'cp_iuris', 'Direito Ambiental — Critério para definição de auto de infração ambiental', '## Critério para definição de auto de infração ambiental

O critério do porte, potencial poluidor e natureza da atividade deve ser utilizado para definir qual auto de infração prevalecer.

### Conceitos
- **Porte**: Magnitude do dano ambiental
- **Potencial Poluidor**: Capacidade de causar poluição
- **Natureza da Atividade**: Tipo de atividade que gerou o dano

