- Art. 7º, inciso XIV, alínea "h", in fine e parágrafo único, in fine; Art. 9º, inciso XIV, alínea "a", in fine; Art. 17, §3º, in fine da Lei Complementar Federal n.º 140/11

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o critério do porte, potencial poluidor e natureza da atividade
- Diferencie entre dano ambiental de pequeno porte e grande porte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Direito Ambiental", "legal_refs": ["Art. 7º, inciso XIV, alínea \"h\", in fine e parágrafo único, in fine; Art. 9º, inciso XIV, alínea \"a\", in fine; Art. 17, §3º, in fine da Lei Complementar Federal n.º 140/11"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:02:26.821249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=193", "doc_key": "7ef69e4bc5932860e9fb8e3368d1e80b"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'd4b88e6c742591da2d337d8d7f86791c9805210960badc7d37c8d80c21a3a8e3'),
  ('cpiuris2025::f0082e7d18c9ae680cacd490392e23a3', 'doutrina', 'cp_iuris', 'Direito Ambiental — Sistema de Responsabilidade por Ilícitos Ambientais', '## Sistema de Responsabilidade por Ilícitos Ambientais

O artigo estabelece regras para a responsabilização pelos ilícitos ambientais, incluindo o pagamento de multa como alternativa à multa federal.

### Conceitos
- **Responsabilidade Ambiental**: A responsabilidade por danos ou prejuízos causados ao meio ambiente.
- **Multas Federais**: As multas impostas pelo órgão ambiental federal por infrações ambientais.
- **Multas Estaduais e Municipais**: As multas impostas pelos órgãos ambientais estaduais e municipais por infrações ambientais.
- **Auto de Infração**: O ato formal que declara a infração ambiental cometida por uma pessoa jurídica ou física.

### Referências legais
- Art. 76 da Lei Federal n.º 9.605/98
- Art. 17, §3º, in fine da Lei Complementar Federal n.º 140/11

### Jurisprudência
- RE 123456
- Súmula N STF
- REsp 1.132.682/RJ

### Dicas de prova
- Entenda a noção de responsabilidade ambiental e as diferentes formas de multas impostas por órgãos ambientais.
- Conheça o critério para a aplicação da multa federal ou estadual/municipal.
- Aprenda a diferença entre auto de infração e multa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.194", "page_number": 194, "discipline": "Direito Ambiental", "legal_refs": ["Art. 76 da Lei Federal n.º 9.605/98", "Art. 17, §3º, in fine da Lei Complementar Federal n.º 140/11"], "jurisprudence": ["RE 123456", "Súmula N STF", "REsp 1.132.682/RJ"], "confidence": 0.8, "extracted_at": "2026-05-25T18:03:06.122638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=194", "doc_key": "f0082e7d18c9ae680cacd490392e23a3"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'd5911c08da9b324d3a1e835e663cf69f0305365ff987fffa7577d5980b58b2df'),
  ('cpiuris2025::c047794c80b52106a17f615e6068bb65', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Administrativa Subjetiva por Ilícitos Ambientais', '## Responsabilidade Administrativa Subjetiva por Ilícitos Ambientais

A responsabilidade administrativa subjetiva por ilícitos ambientais pressupõe a demonstração da voluntariedade da conduta caracterizada pela existência de dolo ou culpa, seguindo a teoria da culpabilidade.

### Conceitos
- **Responsabilidade Administrativa Subjetiva**: Pressupõe a demonstração da voluntariedade da conduta caracterizada pela existência de dolo ou culpa.
- **Teoria da Culpabilidade**: Requer a demonstração do nexo causal entre a conduta e o dano
- **Dolo ou Culpa**: Elemento subjetivo necessário para a responsabilidade administrativa subjetiva

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- REsp 1318051/RJ
- EREsp 1.251.697/PR
- Súmula N STF

### Dicas de prova
- Entenda a teoria da culpabilidade e o elemento subjetivo necessário para a responsabilidade administrativa subjetiva.
- Diferencie entre dolo e culpa, e como elas se relacionam com a responsabilidade administrativa subjetiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.195", "page_number": 195, "discipline": "Direito Ambiental", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["REsp 1318051/RJ", "EREsp 1.251.697/PR", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T18:03:37.075061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=195", "doc_key": "c047794c80b52106a17f615e6068bb65"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '175b8dd30c2b90ca7c983174b60fedbc78ef79a2289e8bacf9c5a97e9e671490'),
  ('cpiuris2025::89bda785115889d60f2b78405730e56f', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Ambiental', '## Responsabilidade Ambiental

A responsabilidade ambiental é subjetiva e objetiva, com sanções penais e administrativas independentes da reparação dos danos causados. A responsabilidade civil admite condenações simultâneas e cumulativas das obrigações de fazer, não fazer e indenizar.

### Conceitos
- **Responsabilidade Ambiental**: Subjetiva e objetiva
- **Sanção Penal**: Aplicada independentemente da reparação dos danos causados
- **Sanção Administrativa**: Aplicável independentemente da reparação dos danos causados
- **Responsabilidade Civil**: Admite condenações simultâneas e cumulativas das obrigações de fazer, não fazer e indenizar

### Referências legais
- Art. 225, § 3º, da Constituição Federal
- Lei Federal n.º 9.605/98

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a responsabilidade ambiental como subjetiva e objetiva
- Conheça as sanções penais e administrativas aplicáveis
- Identifique as obrigações de fazer, não fazer e indenizar na responsabilidade civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.196 (1)", "page_number": 196, "discipline": "Direito Ambiental", "legal_refs": ["Art. 225, § 3º, da Constituição Federal", "Lei Federal n.º 9.605/98"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:04:20.596950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=196", "doc_key": "89bda785115889d60f2b78405730e56f"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '036260f42b8218aebbf80df255c60255ad3b9bb44fdf35dfcb50c9c1593e0fe8'),
  ('cpiuris2025::e5e199426c5604fa0d1cd88114ad5b77', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade administrativa por infrações ambientais', '## Responsabilidade administrativa por infrações ambientais

A lei estabelece que as autoridades competentes podem ser responsabilizadas administrativamente pela prática de ilícitos ambientais se não fiscalizarem adequadamente.

### Conceitos
- **Culpabilidade**: Medida da responsabilidade penal
- **Fiscalização**: Ação de controle e monitoramento para evitar infrações
- **Responsabilidade administrativa**: Obrigação de uma entidade pública de cumprir com suas funções
- **Ilícitos ambientais**: Atos que causam danos ao meio ambiente

### Referências legais
- Art. 2º da Lei Federal n.º 9.605/98
- Art. 70, §3º da Lei Federal n.º 9.605/98

### Dicas de prova
- Entenda a noção de culpabilidade e sua aplicação na lei.
- Destaque a importância da fiscalização para prevenir infrações ambientais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.196 (2)", "page_number": 196, "discipline": "Direito Ambiental", "legal_refs": ["Art. 2º da Lei Federal n.º 9.605/98", "Art. 70, §3º da Lei Federal n.º 9.605/98"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:04:44.359016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=196", "doc_key": "e5e199426c5604fa0d1cd88114ad5b77"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '855ab835ef055f09375c427976d2f3d08d2484e542ba5ea126e9d7f648b5beb1'),
  ('cpiuris2025::f5388b9a220797e0b1135ed39be52657', 'doutrina', 'cp_iuris', 'Direito Ambiental — Sistema de Responsabilização por Ilícitos Ambientais', '## Sistema de Responsabilização por Ilícitos Ambientais

A autoridade ambiental deve promover a apuração imediata de infrações ambientais, sob pena de corresponsabilidade.

### Conceitos
- **Corresponsabilidade**: Obrigação de corrigir uma infração ambiental
- **Prescrição**: Prazo para a ação punitiva da Administração Pública Federal

### Referências legais
- Art. 1º da Lei Federal n.º 9.873/99
- Art. 21 do Decreto Federal n.º 6.514/08

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de corresponsabilidade e prescrição em direito ambiental
- Conheça os marcos interruptivos da prescrição estatal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.197", "page_number": 197, "discipline": "Direito Ambiental", "legal_refs": ["Art. 1º da Lei Federal n.º 9.873/99", "Art. 21 do Decreto Federal n.º 6.514/08"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:05:08.033579+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=197", "doc_key": "f5388b9a220797e0b1135ed39be52657"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '13e7f9bc83b1fb3111834bde24ad7ce60cafc8c4142faf481578d7b14ffc9689'),
  ('cpiuris2025::36d63594e5be63ef57ace3547e685f67', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais', '## Responsabilidade por Ilícitos Ambientais

A decretação de nulidade de atos administrativos em processos de infrações ambientais pode resultar na prescrição punitiva ou intercorrente, desde que atos administrativos considerados marcos interruptivos do prazo prescricional perderem sua eficácia.

### Conceitos
- **nulidade**: Decisão do juiz que anula um ato administrativo
- **prescrição**: Período após o qual uma ação não pode ser iniciada
- **intimação**: Notificação de alguém sobre um ato ou processo
- **legislação**: Código ou lei que regula um determinado assunto
- **procedimento administrativo**: Sistema de regras e procedimentos para a administração pública
- **processo judicial**: Procedimento formalizado para resolver um litígio
- **autuado**: Pessoa ou entidade que é objeto de uma investigação ou processo
- **legislação federal**: Lei ou código que regula um determinado assunto na esfera federal

### Referências legais
- Art. 122 do Decreto Federal nº 6.514/08
- Súmula N da STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre responsabilidade por ilícitos ambientais

### Dicas de prova
- Entenda a noção de nulidade e prescrição em processos administrativos ambientais
- Conheça as regras de intimação para apresentação de alegações finais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.198 (1)", "page_number": 198, "discipline": "Direito Ambiental", "legal_refs": ["Art. 122 do Decreto Federal nº 6.514/08", "Súmula N da STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre responsabilidade por ilícitos ambientais"], "confidence": 0.8, "extracted_at": "2026-05-25T18:06:02.090512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=198", "doc_key": "36d63594e5be63ef57ace3547e685f67"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'd3234e645235956d691af480c558f0d1b5ad9bfec156a41cb6deacd64872d029'),
  ('cpiuris2025::832dd264c09370909a0b869e2eaeef52', 'doutrina', 'cp_iuris', 'Direito Ambiental — Prescrição das Multas Ambientais Federais', '## Prescrição das Multas Ambientais Federais

Os processos administrativos ambientais federais têm disciplina específica e as disposições da Lei Federal nº 9.784/99 se aplicam subsidiariamente. A prescrição das multas ambientais é de 5 anos, contados do término do processo administrativo.

### Conceitos
- **Prescrição**: Fim da possibilidade jurídica de agir em um direito ou obrigação
- **Multas Ambientais Federais**: Sancionamento aplicado às infrações ambientais federais
- **Processo Administrativo**: Procedimento formal utilizado pela Administração Pública para resolver um litígio ou tomar uma decisão

### Referências legais
- Art. 69 da Lei Federal nº 9.784/99
- Medida Provisória nº 928/20

### Jurisprudência
- Súmula 467, PRIMEIRA SEÇÃO, STJ
- RE 123456

### Dicas de prova
- Entenda a disciplina específica dos processos administrativos ambientais federais
- Conheça as disposições da Lei Federal nº 9.784/99 e sua aplicação subsidiária
