  ('cpiuris2025::a1c64c6d82b2e96490da2cff922a4b69', 'doutrina', 'cp_iuris', 'Direito Ambiental — Prescrição da pretensão da Administração Pública em promover a execução de multa por infração administrativa', '## Prescrição da pretensão da Administração Pública em promover a execução de multa por infração administrativa

Resumo objetivo: Determinar o prazo para a Administração Pública promover a execução de multa por infração administrativa no Direito Ambiental.

### Conceitos
- **Prescrição**: O período durante o qual uma ação pode ser iniciada
- **Prazo**: Período determinado para realizar uma ação ou cumprir um dever
- **Administração Pública**: Entidade pública responsável pela gestão de serviços e políticas públicas
- **Multa Ambiental**: Sancionamento imposto à entidade ou pessoa física que cometeu uma infração ambiental
- **Processo Administrativo**: Procedimento formal utilizado pela Administração Pública para resolver um problema ou tomar uma decisão
- **Notificação**: Ação de informar alguém sobre algo
- **Execução de Multa**: Ação da Administração Pública para cobrar a multa imposto

### Referências legais
- Art. 29, § 3º da Lei nº 6.938/1997 - Leis Básicas do Meio Ambiente
- Súmula 373 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunta difícil, mas com resposta clara no texto.
- A importância de entender a prescrição e o prazo para a Administração Pública promover a execução de multa por infração administrativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.199", "page_number": 199, "discipline": "Direito Ambiental", "legal_refs": ["Art. 29, § 3º da Lei nº 6.938/1997 - Leis Básicas do Meio Ambiente", "Súmula 373 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:07:08.779170+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=199", "doc_key": "a1c64c6d82b2e96490da2cff922a4b69"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '81b4359f5e695e47e721ca99f1d9fdcd033777b65414002bf12ad8aad7297da1'),
  ('cpiuris2025::b10939f4d203c9e00f0b320d72f163d2', 'doutrina', 'cp_iuris', 'Direito Ambiental — Sistema de Responsabilização por Ilícitos Ambientais', '## Sistema de Responsabilização por Ilícitos Ambientais

O Decreto Federal n.º 6.514/08 instituiu um Código Federal de infrações administrativo-ambientais, classificando as infrações em seis grupos.

### Conceitos
- **Código Federal de Infrações Administrativo-Ambientais**: Lei que institui uma classificação única de infrações ambientais
- **Infrações contra a Fauna**: Grupos de infrações relacionadas à proteção da fauna
- **Infrações contra a Flora**: Grupos de infrações relacionadas à proteção da flora
- **Poluição e Outras Infrações Ambientais**: Grupo de infrações relacionadas à poluição e outros impactos ambientais
- **Ordenamento Urbano e Patrimônio Cultural**: Grupos de infrações relacionadas ao ordenamento urbano e patrimônio cultural
- **Administração Ambiental**: Infrações cometidas contra a administração ambiental em si
- **Unidades de Conservação da Natureza**: Grupos de infrações relacionadas às unidades de conservação

### Referências legais
- Art. 6.514/08
- Lei Federal n.º 9.433/97
- Lei Federal n.º 11.105/05

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a classificação das infrações ambientais e suas categorias
- Conheça as leis federais que instituem outras infrações administrativo-ambientais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.200", "page_number": 200, "discipline": "Direito Ambiental", "legal_refs": ["Art. 6.514/08", "Lei Federal n.º 9.433/97", "Lei Federal n.º 11.105/05"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:07:55.565852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=200", "doc_key": "b10939f4d203c9e00f0b320d72f163d2"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '7ade1c9fba76cb5b811b3a8b394a10101fdd7595ce43f0fc72b5851abc36bd28'),
  ('cpiuris2025::c751d0da3e727007bd1d8c0590edbc7c', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Civil e Tutela Processual no Sistema de Responsabilização por Ilícitos Ambientais', '## Responsabilidade Civil e Tutela Processual no Sistema de Responsabilização por Ilícitos Ambientais

A Lei Federal n.º 6.938/81 instituiu um sistema de responsabilização por ilícitos ambientais, com tríplice responsabilização administrativa, civil e criminal para aqueles que descumpram as medidas necessárias à preservação ambiental.

### Conceitos
- **Política Nacional do Meio Ambiente**: Lei que instituiu o sistema de responsabilização por ilícitos ambientais
- **Sistema de Responsabilização por Ilícitos Ambientais**: Estrutura que regula a responsabilidade dos poluidores e predadores ambientais
- **Responsabilidade Civil**: O dever de indenizar ou reparar os danos causados ao meio ambiente e a terceiros
- **Legitimidade do Ministério Público**: A capacidade do Ministério Público para propor ações de responsabilidade civil e criminal

### Referências legais
- Art. 4º, inciso VII da Lei Federal n.º 6.938/81
- Art. 14, §1º da Lei Federal n.º 6.938/81
- Súmula N do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: dano ambiental in re ipsa

### Dicas de prova
- Destacar a legitimidade do Ministério Público para propor ações de responsabilidade civil e criminal
- Entender que a ausência de prova técnica não inviabiliza o reconhecimento do dever de reparação ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.201 (1)", "page_number": 201, "discipline": "Direito Ambiental", "legal_refs": ["Art. 4º, inciso VII da Lei Federal n.º 6.938/81", "Art. 14, §1º da Lei Federal n.º 6.938/81", "Súmula N do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: dano ambiental in re ipsa"], "confidence": 0.8, "extracted_at": "2026-05-25T18:08:36.475595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=201", "doc_key": "c751d0da3e727007bd1d8c0590edbc7c"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '5ff833e57e8f0dd812fca1a177f2b48a2596a5dcd2ed8b447c93c743a469b28f'),
  ('cpiuris2025::62ff32102d981b720b7f3d2a4f7247fa', 'doutrina', 'cp_iuris', 'Direito Ambiental — Desnecessidade de perícia em processos ambientais', '## Desnecessidade de perícia em processos ambientais

O Código de Processo Civil estabelece que, em casos de dano ambiental notório ou de modalidade dissolvível, não é necessário realizar perícia para sua constatação, pois seria uma diligência inútil e protelatória.

### Conceitos
- **Perícia**: Exame técnico detalhado de um fato
- **Dano ambiental**: Prejuízo causado ao meio ambiente
- **Código de Processo Civil**: Lei que regula o processo civil no Brasil

### Referências legais
- Art. 370, Parágrafo Único do Código de Processo Civil

### Dicas de prova
- Entenda a distinção entre dano ambiental notório e modalidade dissolvível
- Conheça o princípio poluidor-pagador e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.201 (2)", "page_number": 201, "discipline": "Direito Ambiental", "legal_refs": ["Art. 370, Parágrafo Único do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:08:58.497355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=201", "doc_key": "62ff32102d981b720b7f3d2a4f7247fa"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '3dc429bc18bd8ae73c32959876c42847257831ec6bef25542cd9e8d4530b6aed'),
  ('cpiuris2025::1e04ba8da040ffa039e89e367e02338e', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Civil Ambiental', '## Responsabilidade Civil Ambiental

O instituto da responsabilidade civil ambiental foi constitucionalizado e ampliado para incluir a legitimidade do Ministério Público, União, Estados-Membros, Municípios e outras entidades. A Constituição estabeleceu um dever constitucional de reparação ambiental aos poluidores, independentemente de sanções penais e administrativas.

### Conceitos
- **Responsabilidade Civil Ambiental**: Instituto que obriga os poluidores a reparar os danos causados ao meio ambiente
- **Legitidade do Ministério Público**: O Ministério Público tem legitimidade para propor ações civis públicas, incluindo aquelas relacionadas à responsabilidade ambiental
- **Constitucionalização**: A responsabilidade civil ambiental foi constitucionalizada, tornando-se um direito fundamental
- **Dever Constitucional de Reparação Ambiental**: Os poluidores têm o dever de reparar os danos causados ao meio ambiente, independentemente de sanções penais e administrativas
- **Ação Popular**: O instrumento jurídico que permite a propositura de ações civis públicas para anular atos lesivos ao meio ambiente
- **Isenção de Custas e Ónus de Sucumbência**: Os autores de ações populares são isentos de custas judiciais e do ônus da sucumbência, salvo comprovada má-fé

### Referências legais
- Art. 5º da Constituição Federal
- Art. 225 da Constituição Federal
- Lei Federal n.º 7.347/85 (LACP)
- Lei Federal n.º 4.717/65

### Jurisprudência
- REsp n. 2.065.347/PE
- Súmula N da STJ

### Dicas de prova
- Entenda a evolução histórica do instituto da responsabilidade civil ambiental
- Conheça os fundamentos constitucionais e legais que regem a responsabilidade civil ambiental
- Aprenda com as características da responsabilidade civil por danos ambientais moldadas pela jurisprudência do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.202", "page_number": 202, "discipline": "Direito Ambiental", "legal_refs": ["Art. 5º da Constituição Federal", "Art. 225 da Constituição Federal", "Lei Federal n.º 7.347/85 (LACP)", "Lei Federal n.º 4.717/65"], "jurisprudence": ["REsp n. 2.065.347/PE", "Súmula N da STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T18:09:59.126650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=202", "doc_key": "1e04ba8da040ffa039e89e367e02338e"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '19da34deb1da8b4e512df45f4bd7976ab92d5366d874e291d98d5fdfa177ccb1'),
  ('cpiuris2025::9f864909b15c1da0c17174fbff734c05', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Objetiva e Ilicitude', '## Responsabilidade Objetiva e Ilicitude

A responsabilidade civil objetiva pressupõe a existência de ato ilícito, independentemente da culpa ou não. A Lei Federal nº 6.938/98 estabelece uma responsabilidade civil objetiva do poluidor ambiental.

### Conceitos
- **Responsabilidade Civil Objetiva**: Pressupõe a existência de ato ilícito, independentemente da culpa ou não.
- **Ato Ilícito**: Conduta de alguém que viola direito e causa dano a outrem.
- **Culpa**: Omissão ou negligência que pode ser considerada como ato ilícito.
- **Dolo**: Ação consciente e deliberada que caracteriza o ato ilícito.
- **Bom Costume**: Conhecimento tácito de regras morais e legais que se tornam norma jurídica.
- **Legítima Defesa**: Ação necessária para evitar dano ou perigo à pessoa ou à coisa alheia.
- **Excludentes da Ilicitude**: Hipóteses que excluem a responsabilidade civil objetiva, como legítima defesa ou caso fortuito.

### Referências legais
- Art. 927 do Código Civil
- Art. 186 do Código Civil
- Art. 187 do Código Civil
- Art. 188 do Código Civil
- Art. 14, §1º da Lei Federal nº 6.938/98

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre responsabilidade civil objetiva e subjetiva.
- Conheça as hipóteses de excludentes da ilicitude previstas no Código Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.203", "page_number": 203, "discipline": "Direito Ambiental", "legal_refs": ["Art. 927 do Código Civil", "Art. 186 do Código Civil", "Art. 187 do Código Civil", "Art. 188 do Código Civil", "Art. 14, §1º da Lei Federal nº 6.938/98"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:10:40.738890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=203", "doc_key": "9f864909b15c1da0c17174fbff734c05"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '5a87f5533c2da7214b65f9c05bbf4b306e958727ac6e6c938b916d8a52ccfcf2'),
  ('cpiuris2025::842c4000ca5694f7160338b79d6932a4', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade do Poluidor', '## Responsabilidade do Poluidor

O poluidor é obrigado a reparar e/ou indenizar os danos ambientais decorrentes de suas atividades, independentemente da existência de culpa.

### Conceitos
- **Princípio do Poluidor-Pagador**: Princípio que estabelece a responsabilidade do poluidor por danos ambientais
- **Responsabilidade Civil Objettiva**: Responsabilidade civil que não depende da existência de culpa
- **Nexo de Causalidade**: Conexão necessária entre a conduta do poluidor e o dano ambiental
- **Dolo ou Culpa**: Presença ou ausência de intenção ou negligência na conduta do poluidor
- **Responsabilidade Independentemente da Existência de Culpa**: Obrigação de reparar o dano independentemente de culpa
- **Risco para os Direitos de Outrem**: Natureza da atividade que implica risco para os direitos de outrem
- **Demonstração do Dano Ambiental**: Prova necessária para a incidência da responsabilidade civil

### Referências legais
- Art. 14, §1º da Lei Federal n.º 6.938/81

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda o princípio do poluidor-pagador e sua aplicação na responsabilidade civil ambiental
- Identifique a importância da demonstração de nexo de causalidade para a configuração do dever de reparação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.204 (1)", "page_number": 204, "discipline": "Direito Ambiental", "legal_refs": ["Art. 14, §1º da Lei Federal n.º 6.938/81"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:11:19.273379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=204", "doc_key": "842c4000ca5694f7160338b79d6932a4"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '04e86931b2b581af5c6f3c37490fde0e99582cc4405e2c4e01230466eeb5fb59'),
  ('cpiuris2025::8ce893428cf24dcbcf8bd74b4f9b69fe', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Civil do Poluidor Ambiental', '## Responsabilidade Civil do Poluidor Ambiental

O poluidor ambiental é responsável civil e objetivamente pelos prejuízos causados ao meio ambiente e a terceiros, independentemente da existência de culpa.

### Conceitos
- **Poluidor Ambiental**: Pessoa física ou jurídica que causa danos ambientais
- **Responsabilidade Civil**: Obrigação de reparar os danos causados ao meio ambiente e a terceiros
- **Objetividade**: A responsabilidade é objetiva, independentemente da existência de culpa
- **Indenização**: Reparação dos danos causados ao meio ambiente e a terceiros
- **Meio Ambiente**: O ambiente natural que é afetado pelos danos ambientais
- **Terceiros**: Pessoas ou entidades diferentes do poluidor ambiental que são afetadas pelos danos ambientais
- **Culpa**: Ação ou omissão que causa danos ambientais
- **Penalidades**: Sancionamentos aplicados ao poluidor ambiental

### Referências legais
- Art. 14, §1º da Lei Federal n.º 6.938/81

### Jurisprudência
- REsp 1596081/PR
- REsp 1.454.281/MG
- AgInt no REsp 1545177/PR

### Dicas de prova
- Distinção entre responsabilidade civil e objetiva
- Importância da indenização nos danos ambientais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Direito Ambiental", "legal_refs": ["Art. 14, §1º da Lei Federal n.º 6.938/81"], "jurisprudence": ["REsp 1596081/PR", "REsp 1.454.281/MG", "AgInt no REsp 1545177/PR"], "confidence": 0.8, "extracted_at": "2026-05-25T18:12:05.054488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=204", "doc_key": "8ce893428cf24dcbcf8bd74b4f9b69fe"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '753b4aac3301e21ac596b2304bfbf99ea86409643d0a2b0a2d1c627657226e55'),
  ('cpiuris2025::1d822f2fbbd578d0e131555c26974e87', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Civil Ambiental', '## Responsabilidade Civil Ambiental

A responsabilidade civil ambiental é objetiva e se baseia na Teoria do Risco Integral, onde o poluidor assume todos os riscos decorrentes de suas atividades. Não há excludentes de nexo causal, nem mesmo caso fortuito ou força maior.

### Conceitos
- **Responsabilidade Civil Ambiental**: Objetiva e se baseia na Teoria do Risco Integral
- **Teoria do Risco Integral**: O poluidor assume todos os riscos decorrentes de suas atividades
- **Nexo Causal**: Não há excludentes, nem mesmo caso fortuito ou força maior

### Referências legais
- Art. 225, § 3º, da CF
- Art. 14, § 1º, da Lei n. 6.938/1981

### Jurisprudência
- AgInt no AREsp 1515490/RJ
- Súmula N STF

### Dicas de prova
- Distinção entre responsabilidade objetiva e subjetiva
- Importância da Teoria do Risco Integral na responsabilidade civil ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direito Ambiental", "legal_refs": ["Art. 225, § 3º, da CF", "Art. 14, § 1º, da Lei n. 6.938/1981"], "jurisprudence": ["AgInt no AREsp 1515490/RJ", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T18:12:37.186563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=205", "doc_key": "1d822f2fbbd578d0e131555c26974e87"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '7c8d713e21b8d735f000839acb032024570fb6a1a029c33fccd2f009d4120e0a'),
  ('cpiuris2025::bc63c19ace497b51014ae99a8a3d39ee', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Civil Ambiental', '## Responsabilidade Civil Ambiental

A responsabilidade civil ambiental é objetiva e pautada na teoria do risco administrativo, não admitindo a responsabilização do empregado por dano. A Constituição define a responsabilidade dos mineradores.

### Conceitos
- **Responsabilidade Civil Ambiental**: Objetiva e pautada na teoria do risco administrativo
- **Teoria do Risco Administrativo**: Não admite a responsabilização do empregado por dano
- **Mineração**: Fica obrigado a recuperar o meio ambiente degradado, de acordo com solução técnica exigida

### Referências legais
- Art. 225 da Constituição da República

### Dicas de prova
- Distinção entre responsabilidade civil ambiental objetiva e teoria do risco administrativo
