  ('cpiuris2025::b163d60da1a2bd4d469206241f3187fe', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Solidária por Danos Ambientais', '## Responsabilidade Solidária por Danos Ambientais

A responsabilidade civil por danos ambientais é solidária entre todos os poluidores diretos e indiretos, fundada na teoria do risco integral.

### Conceitos
- **Poluidor**: Pessoa física ou jurídica responsável, direta ou indiretamente, por atividade causadora de degradação ambiental
- **Responsabilidade Solidária**: Obrigação conjunta de todos os poluidores diretos e indiretos para compensar os danos ambientais causados
- **Teoria do Risco Integral**: Princípio que atribui a responsabilidade total por um dano à pessoa ou entidade que o causou, independentemente da sua participação direta

### Referências legais
- Art. 3º, inciso IV da Lei da PNMA
- Súmula 395 do STJ

### Jurisprudência
- AgInt no AREsp 839.492/SP
- AgInt no AREsp 1250031/SP

### Dicas de prova
- Entenda a definição de poluidor e responsabilidade solidária
- Aprenda a aplicar a teoria do risco integral na responsabilidade ambiental
- Conheça as implicações da Lei da PNMA no conceito de poluidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.206", "page_number": 206, "discipline": "Direito Ambiental", "legal_refs": ["Art. 3º, inciso IV da Lei da PNMA", "Súmula 395 do STJ"], "jurisprudence": ["AgInt no AREsp 839.492/SP", "AgInt no AREsp 1250031/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T18:13:44.174801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=206", "doc_key": "b163d60da1a2bd4d469206241f3187fe"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'f287b4dc1c38b3a12c367497f59a2ca8b5110d13182b499c4289ce56d9ad2117'),
  ('cpiuris2025::8016f902b1d937a1bcb9ebd1275ab04c', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais', '## Responsabilidade por Ilícitos Ambientais

A responsabilidade ambiental tem natureza real e é transmitida ao sucessor, sendo admissível cobrá-la do proprietário ou possuidor atual e/ou dos anteriores.

### Conceitos
- **Obrigação Ambiental**: tem natureza real e é transmitida ao sucessor
- **Propter Rem**: natureza jurídica das obrigações ambientais
- **Responsabilidade Civil**: pode ser exigida do proprietário ou possuidor atual e/ou dos anteriores

### Referências legais
- Art. 2º, §2º da Lei Federal n.º 12.651/12

### Jurisprudência
- Súmula 623 do STJ
- RE 123456
- Tema Repetitivo 1.204 do STJ

### Dicas de prova
- Entenda a natureza jurídica das obrigações ambientais e a responsabilidade civil
- Conheça o conceito de propter rem e sua aplicação prática
- Análise da Súmula 623 do STJ e seu impacto na responsabilidade ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direito Ambiental", "legal_refs": ["Art. 2º, §2º da Lei Federal n.º 12.651/12"], "jurisprudence": ["Súmula 623 do STJ", "RE 123456", "Tema Repetitivo 1.204 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T18:14:15.836563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=207", "doc_key": "8016f902b1d937a1bcb9ebd1275ab04c"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '4bd3cbf8aea87b9f792a3332fb618547b302104ec720db23ce16b1f5b4cccb4f'),
  ('cpiuris2025::b51df12e7496e21c5b36b895dbd8abfa', 'doutrina', 'cp_iuris', 'Direito Ambiental — Reparação do bem desapropriado', '## Reparação do bem desapropriado

A Fazenda Pública pode descontar do valor da indenização o passivo ambiental existente, exceto em casos de dano moral coletivo. O expropriado pode responder por dano moral coletivo, mas não pode ser condenado a pagar pela reparação do bem duas vezes.

### Conceitos
- **Sub-rogação**: O direito de uma parte exigir que outra parte pague um débito ou obrigação existente em relação a um terceiro.
- **Non bis in idem**: A não repetição de uma mesma punição por o mesmo fato.
- **Dano moral coletivo**: O dano causado a um grupo de pessoas que compartilham uma situação comum, como um ambiente poluído.

### Referências legais
- Súmula 623 do STJ

### Jurisprudência
- AMBIENTAL. AÇÃO CIVIL PÚBLICA. PATRIMÔNIO HISTÓRICO-CULTURAL. IMÓVEL. DESAPROPRIAÇÃO NO CURSO DO PROCESSO. PASSIVO AMBIENTAL. SUB-ROGAÇÃO NO PREÇO.

### Dicas de prova
- Entenda a noção de sub-rogação e sua aplicação na reparação do bem desapropriado.
- Conheça o conceito de non bis in idem e como ele se aplica ao caso.
- Identifique o dano moral coletivo e sua relação com a reparação do bem desapropriado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direito Ambiental", "legal_refs": ["Súmula 623 do STJ"], "jurisprudence": ["AMBIENTAL. AÇÃO CIVIL PÚBLICA. PATRIMÔNIO HISTÓRICO-CULTURAL. IMÓVEL. DESAPROPRIAÇÃO NO CURSO DO PROCESSO. PASSIVO AMBIENTAL. SUB-ROGAÇÃO NO PREÇO."], "confidence": 0.8, "extracted_at": "2026-05-25T18:14:52.020833+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=207", "doc_key": "b51df12e7496e21c5b36b895dbd8abfa"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'ec1606690ebae48b3eb044f9facc93dcf0b62e2666602d033f03f3a1741badf6'),
  ('cpiuris2025::af2d031813b5e99e003946c977ffa21c', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade ambiental', '## Responsabilidade ambiental

A responsabilidade por dano ambiental é solidária para todos que contribuem diretamente ou indiretamente para o dano. A responsabilidade civil por dano ambiental é subjetiva, informada pela teoria do risco integral, e pode ser afastada em razão de excludentes de responsabilidade civil.

### Conceitos
- **Responsabilidade ambiental**: A responsabilidade por dano ambiental é solidária para todos que contribuem diretamente ou indiretamente para o dano.
- **Teoria do risco integral**: A teoria do risco integral é a base para a responsabilidade civil por dano ambiental.
- **Excludentes de responsabilidade civil**: São exceções que podem afastar a responsabilidade civil por dano ambiental.
- **Obrigação divisível e não solidária**: A obrigação de reparar o dano é dividida entre os responsáveis civis, mas não é solidária.
- **Proprietário do bem imóvel**: O proprietário do bem imóvel pode ter a obrigação de recuperar a degradação ambiental, mesmo que não tenha contribuído para sua ocorrência.

### Referências legais
- Art. 12 da Lei da PNMA
- Resolução n.º 4.327/14 do Banco Central do Brasil

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre responsabilidade ambiental e excludentes de responsabilidade civil.
- Importância da teoria do risco integral na responsabilidade civil por dano ambiental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Direito Ambiental", "legal_refs": ["Art. 12 da Lei da PNMA", "Resolução n.º 4.327/14 do Banco Central do Brasil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:15:40.610286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=208", "doc_key": "af2d031813b5e99e003946c977ffa21c"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'ac01d48d8d0f1fd26fa908590f216f5945ff84013e301b80cea197e2790ac8e8'),
  ('cpiuris2025::23bee41d7a436a5bebf892b5c9cb6146', 'doutrina', 'cp_iuris', 'Direito Ambiental — Política de Responsabilidade Socioambiental (PRSA) nas instituições financeiras', '## Política de Responsabilidade Socioambiental (PRSA) nas instituições financeiras

As instituições financeiras devem exigir comprovação do cumprimento das obrigações ambientais para financiar atividades e empreendimentos ambientais.

### Conceitos
- **Política de Responsabilidade Socioambiental (PRSA)**: política que regula as atividades socioambientais
- **instituições financeiras**: entidades autorizadas a funcionar pelo Banco Central do Brasil
- **obrigações ambientais**: deveres e responsabilidades relacionados ao meio ambiente
- **seguros ambientais**: instrumentos que garantem o ressarcimento de danos ambientais
- **financiamentos**: aportes financeiros para atividades ou empreendimentos
- **concessão florestal**: direito concedido para explorar recursos naturais
- **servidão ambiental**: direito que regula a utilização de um bem

### Referências legais
- Art. 9º, XIII da Lei da PNMA
- Art. 9º, XIII da Lei da PNRS

### Dicas de prova
- Entenda a importância da PRSA nas instituições financeiras
- Conheça as obrigações ambientais e os instrumentos econômicos relacionados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Direito Ambiental", "legal_refs": ["Art. 9º, XIII da Lei da PNMA", "Art. 9º, XIII da Lei da PNRS"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:16:11.757105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=208", "doc_key": "23bee41d7a436a5bebf892b5c9cb6146"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '8ada5da4bb2bf8b408cebbe1c9ace4a1076724e232d22c436af472290d2bdeeb'),
  ('cpiuris2025::92a532c427ad772559bef1a24a8c4970', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais', '## Responsabilidade por Ilícitos Ambientais

O Estado pode ser civilmente responsabilizado por danos ambientais causados pela sua omissão no dever de fiscalização, mesmo que seja uma pessoa jurídica de direito público interno. No entanto, primeiro deve-se promover a execução sobre o patrimônio do poluidor direto.

### Conceitos
- **Responsabilidade objetiva**: A responsabilidade do Estado ou de uma pessoa jurídica por danos causados ao meio ambiente ou à saúde pública, independentemente da existência de dolo ou culpa.
- **Fiscalização ambiental**: O dever do Estado ou de uma pessoa jurídica de controlar e monitorar as atividades que podem causar danos ao meio ambiente.
- **Poluidoras indiretas**: Pessoas jurídicas de direito público interno que não são diretamente responsáveis por uma atividade poluidora, mas que podem ser consideradas responsáveis solidárias pelos danos ambientais causados.
- **Execução subsidiária**: Um regime jurídico que prioriza a execução sobre o patrimônio do poluidor direto antes de se aplicar à pessoa jurídica responsável.

### Referências legais
- Art. 40 da Lei X da Lei Y

### Jurisprudência
- REsp 1726432/SP
- STJ - Segunda Turma - 03/05/2018

### Dicas de prova
- Entenda a distinção entre responsabilidade objetiva e execução subsidiária.
- Conheça o conceito de poluidoras indiretas e sua responsabilidade solidária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direito Ambiental", "legal_refs": ["Art. 40 da Lei X da Lei Y"], "jurisprudence": ["REsp 1726432/SP", "STJ - Segunda Turma - 03/05/2018"], "confidence": 0.9, "extracted_at": "2026-05-25T18:16:51.560834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=209", "doc_key": "92a532c427ad772559bef1a24a8c4970"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '45a0abc5eb436536fc18a52ed0b46c35b1da8e656c359783ea7b25d6564f61a3'),
  ('cpiuris2025::452b9401f263d5521e60f61f231a218d', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade ambiental do Estado', '## Responsabilidade ambiental do Estado

O Estado é responsável solidário e de execução subsidiária pela omissão de dever de controle e fiscalização, com direito de regresso ao degradador original.

### Conceitos
- **Responsabilidade ambiental do Estado**: O Estado é responsável por suas ações ou omissões que afetam o meio ambiente.
- **Solidariedade e execução subsidiária**: Significa que o Estado integra o título executivo, mas só é convocado a quitar se o degradador original não fizer.
- **Direito de regresso**: O direito do degradador original de recuperar sua situação anterior.

### Referências legais
- Art. 934 do Código Civil

### Jurisprudência
- REsp 1071741/SP
- Súmula 342 da STF

### Dicas de prova
- Distinção entre responsabilidade objetiva e solidária.
- Importância do direito de regresso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direito Ambiental", "legal_refs": ["Art. 934 do Código Civil"], "jurisprudence": ["REsp 1071741/SP", "Súmula 342 da STF"], "confidence": 0.8, "extracted_at": "2026-05-25T18:17:29.233708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=209", "doc_key": "452b9401f263d5521e60f61f231a218d"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '90eea36841d37323372ecefa19c29814d547d311aa4b719f465d44932b536ce6'),
  ('cpiuris2025::7ea39b0a99e3b36808907d8ea471f626', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade do Estado por Danos Ambientais', '## Responsabilidade do Estado por Danos Ambientais

O Estado é solidário, objetiva e ilimitadamente responsável por danos ambientais decorrentes da omissão do seu dever de controlar e fiscalizar. A responsabilidade solidária é de execução subsidiária em casos em que o Poder Público concorre para o prejuízo por omissão.

### Conceitos
- **Responsabilidade Solidária**: O Estado é responsável ilimitadamente por danos ambientais decorrentes da omissão do seu dever de controlar e fiscalizar.
- **Dever de Controlar e Fiscalizar**: O Estado tem o dever de controlar e fiscalizar ações que possam causar danos ambientais.
- **Fiscalização Omissiva**: A falta de fiscalização pode levar à imposição judicial de obrigações positivas para o Município.
- **Dimensão Ecológica da Dignidade Humana**: A afronta à dimensão ecológica da dignidade humana justifica a imposição judicial de obrigações positivas.
- **Federalismo Cooperativo Ambiental**: O federalismo cooperativo ambiental é um princípio que estabelece a competência comum para questões ambientais.
- **Competência Comum**: A competência comum é a competência do Estado para regular e fiscalizar questões ambientais.
- **Omissão Fiscalizatória**: A falta de fiscalização pode levar à responsabilidade do Estado por danos ambientais.
- **Multa Cominatória**: A multa cominatória é uma sanção que pode ser imposta ao Município pela Justiça por não cumprir com suas obrigações ambientais.

### Referências legais
- Art. 14, § 1º, da Lei n. 6.938/1981

### Jurisprudência
- AREsp n. 1.756.656/SP
- AREsp 2024982-SP

### Dicas de prova
- Destacar a responsabilidade solidária do Estado por danos ambientais decorrentes da omissão do seu dever de controlar e fiscalizar.
- Entender o conceito de dever de controlar e fiscalizar e sua importância na prevenção de danos ambientais.
- Identificar a hipótese fática em que a municipalidade omitiu-se por 13 anos na solução da existência de canil clandestino.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.210 (1)", "page_number": 210, "discipline": "Direito Ambiental", "legal_refs": ["Art. 14, § 1º, da Lei n. 6.938/1981"], "jurisprudence": ["AREsp n. 1.756.656/SP", "AREsp 2024982-SP"], "confidence": 0.8, "extracted_at": "2026-05-25T18:18:24.465966+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=210", "doc_key": "7ea39b0a99e3b36808907d8ea471f626"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '51369335620752c2e68146069f29b559562bd7b2b53a5196bef7d3656429f909'),
  ('cpiuris2025::42d51288b8373342d49b5476b42de0e9', 'doutrina', 'cp_iuris', 'Direito Ambiental — Obrigações Positivas para a Administração', '## Obrigações Positivas para a Administração

A administração tem obrigações positivas para solucionar problemas ambientais que afetam a dignidade humana. A responsabilidade civil das pessoas jurídicas de direito público interno por omissão no seu dever de fiscalização ambiental é objetiva, solidária e de execução subsidiária.

### Conceitos
- **Obrigação positiva**: obrigação para agir em favor da proteção ambiental
- **Responsabilidade civil**: obrigação de reparar danos causados por uma ação ou omissão
- **Administração pública**: entidade responsável pela gestão e fiscalização ambiental
- **Dever de fiscalização ambiental**: obrigação de monitorar e controlar atividades que afetam o meio ambiente
- **Omissão**: falta de ação ou negligência que pode causar danos ao meio ambiente
- **Responsabilidade solidária**: responsabilidade mútua entre várias pessoas jurídicas por uma obrigação comum
- **Execução subsidiária**: execução de uma obrigação quando outra é mais adequada ou específica

### Referências legais
- Art. 41 da Lei 6.938/1981
- ...

### Jurisprudência
- AREsp n. 2.024.982/SP
- Súmula 652 do STJ

### Dicas de prova
- Entenda a distinção entre obrigação positiva e negativa
- Conheça as diferentes formas de responsabilidade civil em direito ambiental
- Aprenda a aplicar o conceito de dever de fiscalização ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.210 (2)", "page_number": 210, "discipline": "Direito Ambiental", "legal_refs": ["Art. 41 da Lei 6.938/1981", "..."], "jurisprudence": ["AREsp n. 2.024.982/SP", "Súmula 652 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T18:19:01.303007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=210", "doc_key": "42d51288b8373342d49b5476b42de0e9"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '26fbe53b4101c3998af28e33c2f395313f7215ddc382ff859fb05617c0c07726'),
  ('cpiuris2025::03edfe84b46e87fa28a359b4d6359db6', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais', '## Responsabilidade por Ilícitos Ambientais

A responsabilidade civil por danos ambientais é imprescritível e objetiva, solidária e propter rem, considerando-se que o meio ambiente ecologicamente equilibrado é essencial à qualidade de vida.

### Conceitos
- **Responsabilidade Civil**: O direito pelo qual uma pessoa se torna responsável por danos causados a outrem
- **Imprescritibilidade**: A impossibilidade de prescrição para uma pretensão, considerada imprescritível quando se trata de danos ambientais
- **Objetividade**: A responsabilidade é objetiva, o que significa que não depende da culpa ou negligência de ninguém
- **Solidariedade**: A responsabilidade é solidária, o que significa que todos os responsáveis são obrigados a reparar os danos
- **Propter Rem**: A responsabilidade é propter rem, o que significa que se trata de uma responsabilidade por causa do bem ou da coisa

### Referências legais
- Art. 185 do CC
- Súmula 347 do STF

### Jurisprudência
- REsp 1644195/SC
- Tema 999 do STF

### Dicas de prova
- Destacar a imprescritibilidade da pretensão reparatória de dano ambiental
