  ('cpiuris2025::f531b2ac50660aaccc14fccdeb9bbdfd', 'doutrina', 'cp_iuris', 'Direito Ambiental — Imprescritibilidade da pretensão de reparação de danos ambientais individuais', '## Imprescritibilidade da pretensão de reparação de danos ambientais individuais

A pretensão de reparação de dano causado ao meio ambiente é protegida pelo manto da imprescritibilidade, exceto em casos de danos ambientais individuais que estão sujeitos à prescrição.

### Conceitos
- **Imprescritibilidade**: Conceito jurídico que afirma que uma pretensão não tem prazo para ser ajuizada
- **Pretensão de reparação de danos ambientais individuais**: Direito difuso e indisponível que protege os direitos individuais dos meios ambientais
- **Prescrição**: Processo pelo qual uma pretensão perde sua validade com o passar do tempo

### Referências legais
- Art. 5º, da Lei nº 7.347/1985
- Súmula 279 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Imprescritibilidade de pretensões de reparação de danos ambientais individuais

### Dicas de prova
- Entenda a diferença entre imprescritibilidade e prescrição em relação às pretensões de reparação de danos ambientais
- Conheça o conceito de direito difuso e indisponível e sua aplicação no Direito Ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.212 (1)", "page_number": 212, "discipline": "Direito Ambiental", "legal_refs": ["Art. 5º, da Lei nº 7.347/1985", "Súmula 279 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Imprescritibilidade de pretensões de reparação de danos ambientais individuais"], "confidence": 0.8, "extracted_at": "2026-05-25T18:20:22.365438+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=212", "doc_key": "f531b2ac50660aaccc14fccdeb9bbdfd"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '8968273722c79d69fe65acaeaae21a3c3fec98b10da421a547aaa25cab7f9be1'),
  ('cpiuris2025::1650e7cd9095c120a1a53ddbd53a3e01', 'doutrina', 'cp_iuris', 'Direito Ambiental — Direito Adquirido à Poluição ou Degradação do Meio Ambiente', '## Direito Adquirido à Poluição ou Degradação do Meio Ambiente

Não existe direito adquirido à poluição ou degradação do meio ambiente, pois a legislação ambiental pode ser alterada ou não é imutável. O particular que construiu em área de preservação permanente sem licenciamento deve demoler e recompor a área.

### Conceitos
- **Direito Adquirido**: direito que se adquire por meio de atos ou omissões jurídicas
- **Poluição**: alteração ou deterioração do meio ambiente causada por atividades humanas
- **Degradação do Meio Ambiente**: perda ou deterioração da qualidade ambiental
- **Legislação Ambiental**: regras e normas que regem a proteção do meio ambiente
- **Licenciamento Ambiental**: processo de autorização para realizar atividades que podem afetar o meio ambiente

### Referências legais
- Art. 42 da Lei 6.938/78
- ...

### Jurisprudência
- Súmula 613-STJ
- REsp 1676609/SP

### Dicas de prova
- Entenda a diferença entre direito adquirido e direitos imutáveis.
- Conheça as regras de licenciamento ambiental e suas exceções.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.212 (2)", "page_number": 212, "discipline": "Direito Ambiental", "legal_refs": ["Art. 42 da Lei 6.938/78", "..."], "jurisprudence": ["Súmula 613-STJ", "REsp 1676609/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T18:20:54.149627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=212", "doc_key": "1650e7cd9095c120a1a53ddbd53a3e01"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'f8aa192a37df3b2a96434b61e5722bd926a3c907b03228568e28f86223c8e5c8'),
  ('cpiuris2025::125dd5258920dc7b93180e0e89eccd84', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais e Inversão do Ónus da Prova', '## Responsabilidade por Ilícitos Ambientais e Inversão do Ónus da Prova

A responsabilidade civil por danos ambientais é objetiva, solidária e imprescritível, com a garantia processual da inversão do ônus da prova pela qual o empreendedor potencialmente poluidor deve demonstrar a segurança do seu empreendimento.

### Conceitos
- **Responsabilidade Civil Ambiental**: Objetiva, solidária e imprescritível
- **Inversão do Ónus da Prova**: Garantia processual que transfere ao empreendedor o ônus de demonstrar a segurança do seu empreendimento
- **Art. 6º, VIII da Lei Federal n.º 8.078/1990 (CDC)**: Dispositivo legal que reconhece a inversão do ônus da prova no processo civil
- **Art. 21 da Lei Federal n.º 7.347/1985 (LACP)**: Dispositivo legal que aplica os dispositivos do Título III do Código de Defesa do Consumidor à defesa dos direitos e interesses difusos, coletivos e individuais
- **Súmula 618-STJ**: Aprovada em 24/10/2018, DJe 30/10/2018, que impõe a inversão do ônus da prova nas ações civis ambientais

### Referências legais
- Art. 6º, VIII da Lei Federal n.º 8.078/1990
- Art. 21 da Lei Federal n.º 7.347/1985

### Jurisprudência
- Súmula 618-STJ

### Dicas de prova
- Entenda a responsabilidade civil ambiental e a inversão do ônus da prova
- Conheça as regras de experiências para a inversão do ônus da prova
- Aprenda com a Súmula 618-STJ e sua aplicação nas ações civis ambientais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.213", "page_number": 213, "discipline": "Direito Ambiental", "legal_refs": ["Art. 6º, VIII da Lei Federal n.º 8.078/1990", "Art. 21 da Lei Federal n.º 7.347/1985"], "jurisprudence": ["Súmula 618-STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T18:21:51.112483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=213", "doc_key": "125dd5258920dc7b93180e0e89eccd84"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '69a056a8afafc7e791031685b468383d67bfe47904f6712e98d826dee3b31f61'),
  ('cpiuris2025::ebe4df7bc019bd6f08076bfeecf7fcf8', 'doutrina', 'cp_iuris', 'Direito Ambiental — Desconsideração da Personalidade Jurídica e Responsabilidade por Ilícitos Ambientais', '## Desconsideração da Personalidade Jurídica e Responsabilidade por Ilícitos Ambientais

A desconsideração da personalidade jurídica pode ser aplicada se a pessoa jurídica for obstáculo ao ressarcimento de prejuízos causados à qualidade do meio ambiente.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Ação que visa responsabilizar uma pessoa jurídica por ilícitos ambientais, mesmo se ela não é diretamente envolvida no dano.
- **Responsabilidade por Ilícitos Ambientais**: O dever de reparar os danos causados ao meio ambiente.
- **Princípio Ambiental do In Dubio pro Natura**: A interpretação favorável à natureza em caso de dúvida
- **Princípio Ambiental da Precaução**: A necessidade de agir com cautela para evitar danos ao meio ambiente.
- **Dano Ambiental Notório**: Danos ambientais que são conhecidos e amplamente reconhecidos.
- **Ônus da Prova**: A responsabilidade de provar a causalidade e o prejuízo causados ao meio ambiente.
- **Transgressor**: Pessoa ou entidade que cometeu um ilícito ambiental.

### Referências legais
- Art. 4º da Lei Federal n.º 9.605/98

### Dicas de prova
- Entenda a teoria menor da desconsideração e sua aplicação em casos de responsabilidade por ilícitos ambientais.
- Conheça os princípios ambientais do in dubio pro natura e da precaução e como eles influenciam a responsabilidade por danos ao meio ambiente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.214", "page_number": 214, "discipline": "Direito Ambiental", "legal_refs": ["Art. 4º da Lei Federal n.º 9.605/98"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:22:31.321422+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=214", "doc_key": "ebe4df7bc019bd6f08076bfeecf7fcf8"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '57fe9ea6a209926559fb3744ae39cad73a4ebd897bba3d54cfdc056932ce9fce'),
  ('cpiuris2025::479ee42230de488c212e07ba188f3813', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais', '## Responsabilidade por Ilícitos Ambientais

A responsabilidade civil por danos ambientais é objetiva, solidária e imprescritível, determinando ao poluidor a obrigação de reparar e indenizar os danos causados ao meio ambiente.

### Conceitos
- **Responsabilidade Civil**: Obrigação de reparar danos ambientais
- **Poluidor-Pagador**: Parte responsável por poluir e deve pagar as consequências
- **Reparação In Integrum**: Obrigação de reparar todos os danos causados ao meio ambiente
- **Desconsideração da Personalidade Jurídica**: Instituto que afasta a responsabilidade da empresa por ilícitos ambientais
- **Intervenção de Terceiros**: Mecanismo que permite a intervenção do Estado em empresas insolventes

### Referências legais
- Art. 1º, caput e inciso I da Lei Federal n.º 7.347/85
- Lei Federal n.º 8.884/94
- Súmula 7/STJ

### Jurisprudência
- AgRg no AREsp 324.781/ES
- RE 123456

### Dicas de prova
- Entenda a responsabilidade civil por danos ambientais e o papel do poluidor-pagador
- Conheça o instituto da desconsideração da personalidade jurídica e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.215", "page_number": 215, "discipline": "Direito Ambiental", "legal_refs": ["Art. 1º, caput e inciso I da Lei Federal n.º 7.347/85", "Lei Federal n.º 8.884/94", "Súmula 7/STJ"], "jurisprudence": ["AgRg no AREsp 324.781/ES", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:23:08.568939+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=215", "doc_key": "479ee42230de488c212e07ba188f3813"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'c605a315d1596912ee896de0e03eb3061e8add2e93fc5daeab6aff3cfc973890'),
  ('cpiuris2025::12091488d0f1842e00d5f4e133dbf49e', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais', '## Responsabilidade por Ilícitos Ambientais

A legislação brasileira prevê a figura do dano moral ambiental desde 1994, reconhecendo a ofensa ao direito fundamental difuso ao meio ambiente e à qualidade de vida. O dano moral coletivo é reconhecido sem necessidade de avaliação individual ou coletiva de sofrimento.

### Conceitos
- **Dano Moral Ambiental**: Ofensa ao direito fundamental difuso ao meio ambiente e à qualidade de vida
- **Dano Moral Coletivo**: Danos morais causados a um grupo massificado, sem necessidade de avaliação individual ou coletiva de sofrimento
- **Responsabilidade Ambiental**: Obrigação de indenização pelo dano ambiental causado a terceiros

### Referências legais
- Art. 8.884/94
- Súmula 455 STJ

### Jurisprudência
- REsp 1269494/MG
- REsp 1555220/MT

### Dicas de prova
- Distinção entre dano moral individual e coletivo
- Critério de metro quadrado ou hectare degradado para arbitramento do dano moral coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.216 (1)", "page_number": 216, "discipline": "Direito Ambiental", "legal_refs": ["Art. 8.884/94", "Súmula 455 STJ"], "jurisprudence": ["REsp 1269494/MG", "REsp 1555220/MT"], "confidence": 0.8, "extracted_at": "2026-05-25T18:23:51.264559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=216", "doc_key": "12091488d0f1842e00d5f4e133dbf49e"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '60c8256ed664c3197ba282fc5ec0c57d237ed9da3bf69e440d5d19cce34eac28'),
  ('cpiuris2025::a3799ab0f3e30a06b99963a19b1990da', 'doutrina', 'cp_iuris', 'Direito Ambiental — Dano Ambiental Notório e Inversão do Ónus da Prova', '## Dano Ambiental Notório e Inversão do Ónus da Prova

O dano ambiental notório inverte o ônus da prova da causalidade e do prejuízo, cabendo ao transgressor demonstrar que não resultaram os impactos negativos normalmente associados.

### Conceitos
- **Dano Ambiental Notório**: dano ambiental que se dissipa rapidamente no ambiente e não requer prova técnica para sua constatação
- **Inversão do Ónus da Prova**: inverte o ônus da prova da causalidade e do prejuízo, cabendo ao transgressor demonstrar que não resultaram os impactos negativos normalmente associados
- **Prova da Conduta Imputada**: basta a prova da conduta imputada ao agente em casos de dano ambiental notório

### Referências legais
- Art. 374, I, do Código de Processo Civil
- Art. 370, Parágrafo Único, do Código de Processo Civil
- Súmula 629/STJ

### Jurisprudência
- REsp n. 2.065.347/PE
- RESP nº 1.989.778

### Dicas de prova
- Frise-se, em se tratando de dano ambiental notório, basta a prova da conduta imputada ao agente
- O dano ambiental notório inverte o ônus da prova da causalidade e do prejuízo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.216 (2)", "page_number": 216, "discipline": "Direito Ambiental", "legal_refs": ["Art. 374, I, do Código de Processo Civil", "Art. 370, Parágrafo Único, do Código de Processo Civil", "Súmula 629/STJ"], "jurisprudence": ["REsp n. 2.065.347/PE", "RESP nº 1.989.778"], "confidence": 0.8, "extracted_at": "2026-05-25T18:24:29.515567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=216", "doc_key": "a3799ab0f3e30a06b99963a19b1990da"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '508679f8c30e1610c20f46a6be0d113ec422998e31504ebb1a079b6cb300bdad'),
  ('cpiuris2025::f0527d875b2b4ecdebaa7931e8c58c96', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais', '## Responsabilidade por Ilícitos Ambientais

O sistema de responsabilização por ilícitos ambientais exige causalidade e demonstração de prejuízo, além de reparação integral do dano ambiental.

### Conceitos
- **Causalidade**: necessidade de estabelecer uma relação de causa e efeito entre a conduta e o dano
- **Dano Moral Coletivo**: lesão à esfera extrapatrimonial de determinada comunidade, provocando repulsa e indignação na consciência coletiva
- **Reparação Integral do Dano Ambiental**: obrigação de reparar todos os efeitos negativos decorrentes dos danos causados ao meio ambiente

### Referências legais
- Art. 43 da Lei nº 6.938/81

### Jurisprudência
- Súmula 629 do STJ
- REsp 1862873/SP (2020)
- AgInt no REsp 1770219/MG (2019)

### Dicas de prova
- Distinção entre dano moral coletivo e reparação integral do dano ambiental
- Importância da causalidade na responsabilização por ilícitos ambientais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.217", "page_number": 217, "discipline": "Direito Ambiental", "legal_refs": ["Art. 43 da Lei nº 6.938/81"], "jurisprudence": ["Súmula 629 do STJ", "REsp 1862873/SP (2020)", "AgInt no REsp 1770219/MG (2019)"], "confidence": 0.8, "extracted_at": "2026-05-25T18:25:02.700315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=217", "doc_key": "f0527d875b2b4ecdebaa7931e8c58c96"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'da9b8e5b1bc9026f347c0fb99723886048506be32fb21425053f44e815ab3837'),
  ('cpiuris2025::4b4e1fbc4db92f2120032bdb7e376b25', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por danos ambientais', '## Responsabilidade por danos ambientais

A responsabilidade civil por danos ambientais permite condenar o poluidor à obrigação de fazer (reparar o dano), não fazer (obstar a continuidade da lesão) e indenizar (dever de indenizar os efeitos remanescentes do dano). A indenização deve abranger a totalidade dos danos causados.

### Conceitos
- **Responsabilidade Civil**: O direito pelo qual uma pessoa pode ser condenada a reparar os danos causados por outra.
- **Danos Ambientais**: Lesões causadas ao meio ambiente, que podem ser reparadas ou indenizadas.
- **Obrigação de Fazer**: A imposição da adoção de medidas para reparar o dano ambiental causado.
- **Obrigação de Não Fazer**: Para obstar a continuidade da lesão ao meio ambiente.
- **Obrigação de Indenizar**: Dever de indenizar os efeitos remanescentes do dano ambiental.

### Referências legais
- Art. 192 da Lei nº 6.938/78

### Jurisprudência
- Súmula 629/STJ

### Dicas de prova
- Destacar a importância da integralidade dos danos causados ao meio ambiente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.218 (1)", "page_number": 218, "discipline": "Direito Ambiental", "legal_refs": ["Art. 192 da Lei nº 6.938/78"], "jurisprudence": ["Súmula 629/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T18:25:50.785972+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=218", "doc_key": "4b4e1fbc4db92f2120032bdb7e376b25"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '171bae24eb139ed9856cbe7607347e592344579b0fba00cea82cd65836ab6fa3'),
  ('cpiuris2025::ce4ff0a030ceb53c7add08872f9dd0aa', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade Penal por Crimes Ambientais', '## Responsabilidade Penal por Crimes Ambientais

A responsabilidade penal ambiental é subjetiva e pressupõe comprovação de condutas dolosas ou culposas. A Lei Federal n.º 9.605/98 regulamentou as regras gerais sobre a responsabilidade penal ambiental.

### Conceitos
- **Responsabilidade Penal**: Subjetiva, pressupondo comprovação de condutas dolosas ou culposas
- **Teoria Finalista da Ação**: Teoria que afirma a responsabilidade penal é subjetiva
- **Lei dos Crimes Ambientais (LCA)**: Norma infraconstitucional que regulamenta a responsabilidade penal ambiental

### Referências legais
- Art. 225, §3º da Constituição da República
- Lei Federal n.º 9.605/98

### Jurisprudência
- REsp n. 1.652.072/PR
- AgInt nos EDcl no AgInt

### Dicas de prova
- Distinção entre responsabilidade penal e administrativa
- Importância da Lei dos Crimes Ambientais (LCA)
- Teoria Finalista da Ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.218 (2)", "page_number": 218, "discipline": "Direito Ambiental", "legal_refs": ["Art. 225, §3º da Constituição da República", "Lei Federal n.º 9.605/98"], "jurisprudence": ["REsp n. 1.652.072/PR", "AgInt nos EDcl no AgInt"], "confidence": 0.8, "extracted_at": "2026-05-25T18:26:18.518056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=218", "doc_key": "ce4ff0a030ceb53c7add08872f9dd0aa"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '0ad6812843cc2d716a156e3885809dc2a44b89d0242c61b0901a7703db549ce5'),
  ('cpiuris2025::074d9316a37813805360e81a087fc70e', 'doutrina', 'cp_iuris', 'Direito Ambiental — Responsabilidade por Ilícitos Ambientais', '## Responsabilidade por Ilícitos Ambientais

A Lei n.º 9.605/98 disciplinou as regras especiais sobre os crimes ambientais, estabelecendo sanções penais e administrativas para condutas lesivas ao meio ambiente.

### Conceitos
- **Responsabilidade**: obrigação de reparar danos causados ao meio ambiente
- **Lesividade Ambiental**: conduta ou atividade que causa dano ao meio ambiente
- **Sanções Penais e Administrativas**: medidas legais tomadas contra os infratores
- **Código Penal**: legislação que regula as infrações penais
- **Código de Processo Penal**: legislação que regula o processo penal
- **Lei Federal n.º 9.099/95**: legislação que regula o processo civil
- **Subsidiariamente**: aplicação de regras gerais apenas quando não há previsão específica

### Referências legais
- Art. 79 da Lei Federal n.º 9.605/98
- Súmula 387 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Responsabilidade por Ilícitos Ambientais

### Dicas de prova
- Entenda a noção de responsabilidade ambiental e suas consequências
- Identifique as sanções penais e administrativas previstas na Lei n.º 9.605/98
- Conheça a aplicação subsidiária das regras gerais do Código Penal e do Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.219", "page_number": 219, "discipline": "Direito Ambiental", "legal_refs": ["Art. 79 da Lei Federal n.º 9.605/98", "Súmula 387 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Responsabilidade por Ilícitos Ambientais"], "confidence": 0.8, "extracted_at": "2026-05-25T18:26:53.360563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=219", "doc_key": "074d9316a37813805360e81a087fc70e"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '01eda33b5419d5e9b4ca233807ccd3f01471f93490e650f77bd5e549dafa97b2'),
  ('cpiuris2025::44cce048958e8a1f345c52fa49aafe51', 'doutrina', 'cp_iuris', 'Direito Ambiental — Questões de Direito Ambiental', '## Questões de Direito Ambiental

Resumo de questões de direito ambiental com gabarito

### Conceitos
- **Meio Ambiente**: Ambiente natural e social em que vivem os seres humanos
- **Poluição**: Condicionamento nocivo do meio ambiente que prejudica a saúde humana, animal ou vegetal
- **Reserva Ambiental**: Área protegida para preservação do meio ambiente e da biodiversidade
- **Licença de Exploração**: Permissão concedida pelo órgão ambiental competente para explorar recursos naturais
- **Impacto Ambiental**: Efeito negativo que uma atividade ou projeto pode ter no meio ambiente
- **Sustentabilidade**: Prática de produção e consumo que não prejudica o meio ambiente
- **Desmatamento**: Remoção intencional de árvores de um local para fins econômicos ou outros
- **Políticas Públicas Ambientais**: Medidas adotadas pelo Estado para proteger o meio ambiente e promover a sustentabilidade

### Referências legais
- Art. 225 da Lei nº 6.938/76
- Súmula 656 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Política de Desenvolvimento Sustentável

### Dicas de prova
- Perguntas sobre meio ambiente e poluição
- Importância da licença de exploração para proteger o meio ambiente
- Impacto ambiental é um conceito fundamental em direito ambiental
- Sustentabilidade é uma prática importante para reduzir o impacto ambiental
- Desmatamento é uma atividade que pode ter consequências negativas para o meio ambiente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.222", "page_number": 222, "discipline": "Direito Ambiental", "legal_refs": ["Art. 225 da Lei nº 6.938/76", "Súmula 656 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Política de Desenvolvimento Sustentável"], "confidence": 0.8, "extracted_at": "2026-05-25T18:27:42.850078+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=222", "doc_key": "44cce048958e8a1f345c52fa49aafe51"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '187e0d17e231df90e2793abc4ac42b1e2320672399a6ab9b44f020f5ab724802'),
  ('cpiuris2025::913eb218dfffa3582f9c33d835892461', 'doutrina', 'cp_iuris', 'Direito Ambiental — Leis Federais e Complementares de Meio Ambiente', '## Leis Federais e Complementares de Meio Ambiente

Resumo de leis federais e complementares relacionadas ao meio ambiente.

### Conceitos
- **Código Florestal**: Lei que regula a exploração e conservação das florestas.
- **Política Nacional do Meio Ambiente (PNMA)**: Lei que estabelece a política ambiental do país.
- **Lei de Proteção à Fauna**: Lei que protege e conserva as espécies animais.
- **Código de Águas Minerais**: Lei que regula a exploração e uso das águas minerais.
- **Infrações Ambientais**: Leis que estabelecem as infrações ambientais e suas penalidades.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das leis ambientais no Brasil.
- Conheça as diferentes categorias de leis ambientais (federais e complementares).
- Aprenda a distinguir entre as infrações ambientais e suas penalidades.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.223", "page_number": 223, "discipline": "Direito Ambiental", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:28:17.989528+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=223", "doc_key": "913eb218dfffa3582f9c33d835892461"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', '5b95d98c80689b852f3d9a965c94a8ee4071d9379c2caadf745f191056431caa'),
  ('cpiuris2025::6c29e628bf394cb0835fffa7f8936f5d', 'doutrina', 'cp_iuris', 'Direito Ambiental — Decreto Federal e Resolução CONAMA', '## Decreto Federal e Resolução CONAMA

Resumo de Decreto Federal e Resolução CONAMA relevantes para o Direito Ambiental.

### Conceitos
- **Decreto Federal**: Lei federal que estabelece normas gerais para a proteção do meio ambiente.
- **Resolução CONAMA**: Decisão da Comissão Nacional de Valores Ambientais (CONAMA) que estabelece normas técnicas e regulamentações ambientais.

### Referências legais
- Art. 5º da Constituição Federal
- Lei n.º 6.938/1997

### Jurisprudência
- RE 586.224/SP
- RE 654.833/AC
- Súmula Vinculante n.º 10

### Dicas de prova
- Entenda a importância das Resoluções CONAMA e Decreto Federal no Direito Ambiental.
- Conheça as normas gerais estabelecidas por esses documentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf", "source_ref": "IURIS - Direito Ambiental - Vol. 10 - 2025.pdf · p.224", "page_number": 224, "discipline": "Direito Ambiental", "legal_refs": ["Art. 5º da Constituição Federal", "Lei n.º 6.938/1997"], "jurisprudence": ["RE 586.224/SP", "RE 654.833/AC", "Súmula Vinculante n.º 10"], "confidence": 0.8, "extracted_at": "2026-05-25T18:28:45.767320+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Ambiental - Vol. 10 - 2025.pdf#page=224", "doc_key": "6c29e628bf394cb0835fffa7f8936f5d"}'::jsonb, '{"materia": "Direito Ambiental"}'::jsonb, 'cp_iuris_2025', 'a527befd55e29ee7ca2a83fc946529bd43a08d64f755a23ba993839e61b962ec'),
  ('cpiuris2025::c6072adaa1abf4d84226c3ea161422b5', 'doutrina', 'cp_iuris', 'Direito Civil — Introdução ao Direito Civil', '## Introdução ao Direito Civil

Resumo objetivo: Este texto apresenta a introdução ao Direito Civil, uma das disciplinas mais amplas do ordenamento jurídico brasileiro.

### Conceitos
- **Direito Civil**: Disciplina que regula as relações de ordem civil entre os cidadãos.
- **Relações de Ordem Civil**: Conceito abrangente que engloba todas as relações entre os indivíduos, empresas e entidades do ordenamento jurídico.

### Referências legais
- Art. 1.3 da Lei nº 9.527/97

### Dicas de prova
- Entenda o conceito de Direito Civil e suas relações com outras disciplinas do direito.
- Identifique a abrangência das relações de ordem civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.2", "page_number": 2, "discipline": "Direito Civil", "legal_refs": ["Art. 1.3 da Lei nº 9.527/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:29:15.802516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=2", "doc_key": "c6072adaa1abf4d84226c3ea161422b5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e3b8f614bab618c0789966b6d218c6c24413c2f9477bec8ae0b7f272f881de4e'),
  ('cpiuris2025::afbb8b2c145ca5f9b55679d8e1310dac', 'doutrina', 'cp_iuris', 'Direito Civil — Autores', '## Autores

Resumo sobre os autores do livro, incluindo informações sobre suas profissões e experiências.

### Conceitos
- **Advogado**: Profissional qualificado para representar interesses em tribunal
- **Professor**: Pessoa que ensina e instrui em uma instituição de ensino
- **Concurso Público**: Processo seletivo para preencher vagas em órgãos públicos

### Dicas de prova
- Identifique a profissão dos autores e suas experiências relevantes
- Entenda o conceito de concurso público e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.3", "page_number": 3, "discipline": "Direito Civil", "legal_refs": [], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:29:34.091580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=3", "doc_key": "afbb8b2c145ca5f9b55679d8e1310dac"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1fbccf3e5e69320f6d28602822b2ab7ea38c4d66c112009d2c15c53a67afc4bd'),
  ('cpiuris2025::43adde303da29ecb1e358735ce0bd328', 'doutrina', 'cp_iuris', 'Direito Civil — Lei de Introdução às Normas do Direito Brasileiro (LINDB)', '## Lei de Introdução às Normas do Direito Brasileiro (LINDB)

Regulamenta a vigência, validade e aplicação das normas do direito brasileiro.

### Conceitos
- **Vigência**: Período de tempo em que uma lei ou norma é aplicável.
- **Validade**: Qualidade de ser válida ou não
- **Repristinação**: Restabelecimento de uma situação anterior
- **Normas gerais e especiais**: Regras que abrangem todas as áreas do direito e regras específicas para cada área
- **Integração das normas**: Fusão de leis e regulamentos para criar uma nova regra
- **Equidade**: Princípio que visa a justiça e a equidade em decisões judiciais
- **Aplicação e interpretação das normas jurídicas**: Procedimento para aplicar as leis de forma correta
- **Irretroatividade das leis**: Princípio que proíbe a retroatividade de leis

### Referências legais
- Art. 1 da Lei nº 9.868/1998

### Dicas de prova
- Entenda o conceito de vigência e validade das normas.
- Conheça a diferença entre normas gerais e especiais.
- Aprenda a aplicar as regras de integração das normas.
- Fique atento à importância da equidade em decisões judiciais.
- Entenda o conceito de irretroatividade das leis.
- Conheça os casos de conflito de leis no tempo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Civil", "legal_refs": ["Art. 1 da Lei nº 9.868/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:30:20.127669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=4", "doc_key": "43adde303da29ecb1e358735ce0bd328"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '081020956452e6fdc87a313acaee34e5e0eafc7ab3ca637963ddaf07de655aee'),
  ('cpiuris2025::076f0de2f1a24e8be8533f4ff3d12424', 'doutrina', 'cp_iuris', 'Direito Civil — Definição e conceitos básicos do Direito Civil', '## Definição e conceitos básicos do Direito Civil

O Direito Civil é disciplinado pelas leis civis, que regem as relações entre os indivíduos e as pessoas jurídicas. Ele aborda conceitos como a socialidade, éticidade, operabilidade e direito civil constitucional.

### Conceitos
- **Socialidade**: Relação entre os indivíduos
- **Eticidade**: Conformidade com as normas morais
- **Operabilidade**: Capacidade de produzir efeitos
- **Direito civil constitucional**: Leis que regem a vida e o patrimônio dos cidadãos
- **Diálogo das fontes**: Combinação de leis civis, comuns e constitucionais

### Referências legais
- Art. 1.3 da Lei nº 9.514/1998

### Dicas de prova
- Entenda a definição de socialidade e sua importância no Direito Civil
- Conheça as diferentes fontes do direito civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direito Civil", "legal_refs": ["Art. 1.3 da Lei nº 9.514/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:30:56.355740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=4", "doc_key": "076f0de2f1a24e8be8533f4ff3d12424"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '597e22264be4f0a0153ba62c3c3a3580b2304789cc944b8e7f4c79cec3efc902'),
  ('cpiuris2025::c77f108741120d05d4ff1ab84019d8bf', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações e Relações Jurídicas', '## Obrigações e Relações Jurídicas

Capítulo que aborda a teoria geral das obrigações, suas figuras e relações jurídicas obrigacionais.

### Conceitos
- **Obrigação**: Relação jurídica que obriga um devido ao outro
- **Direito Real**: Direito que se transmite por herança ou compra
- **Direito Obrigacional**: Direito que se estabelece por meio de uma relação jurídica obrigatória
- **Boa-fé Objetiva**: Conduzimento da vontade do devedor com a intenção de cumprir com o dever
- **Promessa de Recompensa**: Declaração feita por uma parte para se comprometer a realizar algo em favor da outra

### Referências legais
- Art. 107 do CC/2016
- Súmula 245 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Teoria das Obrigações

### Dicas de prova
- Entenda a distinção entre direitos reais e obrigacionais
- Conheça as figuras híbridas de obrigações
- Aprenda a teoria dualista das obrigações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito Civil", "legal_refs": ["Art. 107 do CC/2016", "Súmula 245 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Teoria das Obrigações"], "confidence": 0.8, "extracted_at": "2026-05-25T18:31:25.609320+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=4", "doc_key": "c77f108741120d05d4ff1ab84019d8bf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '900af59a2642d96fc4cdf567931bbda727d4c50a2578c456fb22fb035cc1f79e'),
  ('cpiuris2025::68b8c9bf55a9798bd5a7a89e03882747', 'doutrina', 'cp_iuris', 'Direito Civil — Gestão de Negócios e Pagamento Indevido', '## Gestão de Negócios e Pagamento Indevido

Artigos relacionados à gestão de negócios e pagamento indevido, destacando a importância da gestão eficaz para evitar pagamentos indevidos.

### Conceitos
- **Gestão de Negócios**: A organização e coordenação dos recursos para alcançar objetivos
- **Pagamento Indevido**: O pagamento feito por um devedor a mais do que o valor devido ao credor

### Referências legais
- Art. 173 da Código Civil
- Código de Comércio

### Jurisprudência
- Súmula 245/STJ
- RE 123456

### Dicas de prova
- Entenda a importância da gestão eficaz para evitar pagamentos indevidos.
- Diferencie entre pagamento indevido e erro de cálculo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.4 (4)", "page_number": 4, "discipline": "Direito Civil", "legal_refs": ["Art. 173 da Código Civil", "Código de Comércio"], "jurisprudence": ["Súmula 245/STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:31:44.596351+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=4", "doc_key": "68b8c9bf55a9798bd5a7a89e03882747"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8f3a4be75b002bb4463489c2aed631fd8309caf97ca8200e4b9d55fe42602e1b'),
  ('cpiuris2025::c23e7bcec3c30a3929d1ca6155a88968', 'doutrina', 'cp_iuris', 'Direito Civil — Classificação das obrigações', '## Classificação das obrigações

O texto discute a classificação básica e especial das obrigações, bem como as diferentes categorias de obrigações, como dar, fazer e não fazer.

### Conceitos
- **Obrigação**: obrigação jurídica
- **Classificação básica**: divisão em obrigações de dar e obrigações de fazer
- **Classificação especial**: subdivisões dentro da classificação básica
- **Obrigação de dar**: obrigação de entregar uma coisa certa ou incerta
- **Obrigação de fazer**: obrigação de realizar uma ação
- **Obrigação de não fazer**: obrigação de não realizar uma ação

### Referências legais
- Art. 117 do Código Civil

### Dicas de prova
- Entenda a classificação básica e especial das obrigações
- Conheça as diferentes categorias de obrigações (dar, fazer e não fazer)
- Aprenda a distinguir entre obrigação de dar e obrigação de fazer', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Civil", "legal_refs": ["Art. 117 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:32:23.010780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=5", "doc_key": "c23e7bcec3c30a3929d1ca6155a88968"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3b9bbc0855266bac97b29b0fc8c6855405d5a12ec2095e5b2d6222e368cab32b'),
  ('cpiuris2025::70263230b233db18b3600fa645b993d6', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Solidária', '## Obrigação Solidária

Discute-se a obrigação solidária, suas formas e transmissão das obrigações.

### Conceitos
- **Obrigação Solidária**: obrigação conjunta de duas ou mais pessoas
- **Solidariedade Ativa**: formas de solidariedade ativa, como a responsabilidade conjunta e a obrigação conjunta
- **Solidariedade Passiva**: formas de solidariedade passiva, como a responsabilidade solidária e a obrigação solidária
- **Cessão de Crédito**: transmissão do direito de cobrar uma dívida para outra pessoa
- **Cessão de Débito**: transmissão da obrigação de pagar uma dívida para outra pessoa

### Referências legais
- Art. 840 CC/2012
- Súmula 245 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Obrigação Solidária

### Dicas de prova
- Entenda a diferença entre solidariedade ativa e passiva
- Conheça as formas de transmissão das obrigações, como cessão de crédito e cessão de débito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Civil", "legal_refs": ["Art. 840 CC/2012", "Súmula 245 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Obrigação Solidária"], "confidence": 0.8, "extracted_at": "2026-05-25T18:32:50.671518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=5", "doc_key": "70263230b233db18b3600fa645b993d6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e6dce6c9cad7ce7e5588086fc6545a045154b238c75ca7af898aaab945d2ebf4'),
  ('cpiuris2025::40f183ba0d47d24d421a91f2211722b3', 'doutrina', 'cp_iuris', 'Direito Civil — Cessão de contratos e inadimplemento das obrigações', '## Cessão de contratos e inadimplemento das obrigações

Tratamento da cessão de contratos, inadimplemento das obrigações e seus princípios, bem como a formação dos contratos.

### Conceitos
- **Cessão de contratos**: Transferência do direito de um contrato para outro
- **Inadimplemento das obrigações**: Omissão ou não cumprimento das obrigações contratuais
- **Atos culposos**: Ações que resultam em dano ao devedor
- **Fato não imputável**: Circunstância que não pode ser atribuída ao devedor
- **Cláusula penal e arras**: Condição que impõe sanções em caso de inadimplemento

### Referências legais
- Art. 389 do CC

### Dicas de prova
- Entenda a diferença entre cessão e transferência
- Conheça as hipóteses de inadimplemento das obrigações
- Aprenda com os exemplos de atos culposos e fato não imputável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Civil", "legal_refs": ["Art. 389 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:33:22.616237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=5", "doc_key": "40f183ba0d47d24d421a91f2211722b3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '57dd03883dbeafb734e6f1e03506b2ab2e040d349f0883c29f65201addecf567'),
  ('cpiuris2025::5f8e7628c364f46fd4946ec797cc9742', 'doutrina', 'cp_iuris', 'Direito Civil — Formas Contratuais', '## Formas Contratuais

Discute as formas de contrato, incluindo preliminar, estipulação em favor de terceiros, promessa de fato de terceiro e contrato aleatório.

### Conceitos
- **Contrato Preliminar**: Acordo entre duas ou mais pessoas sobre os termos de um contrato, que pode ser posteriormente formalizado.
- **Estipulação em favor de terceiros**: Cláusula no contrato que beneficia terceiros, regulamentada pelos arts. 436 a 438 do CC/02.
- **Promessa de fato de terceiro**: Declaração feita por um terceiro sobre o cumprimento de uma obrigação, regulamentada pelos arts. 439 e 440 do CC/02.
- **Contrato Aleatório**: Acordo que não tem natureza jurídica de contrato, regulamentado pelos arts. 458 a 461 do CC/02.
- **Cláusula Pecúniaria**: Cláusula no contrato que estabelece o valor da obrigação.
- **Contrato de Fato**: Acordo entre duas ou mais pessoas sobre os termos de um contrato, que pode ser posteriormente formalizado.
- **Obrigação**: Dívida ou dever de cumprir uma obrigação
- **Terceiro**: Pessoa que não é parte do contrato, mas pode ser afetada por ele.

### Referências legais
- Art. 436 a 438 do CC/02
- Art. 439 e 440 do CC/02
- Art. 458 a 461 do CC/02

### Dicas de prova
- Entenda a diferença entre um contrato preliminar e uma estipulação em favor de terceiros.
- Conheça as regras para a promessa de fato de terceiro e contrato aleatório.
- Avalie a importância das cláusulas pecuniárias nos contratos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.5 (4)", "page_number": 5, "discipline": "Direito Civil", "legal_refs": ["Art. 436 a 438 do CC/02", "Art. 439 e 440 do CC/02", "Art. 458 a 461 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:34:14.160389+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=5", "doc_key": "5f8e7628c364f46fd4946ec797cc9742"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '70781b2a4e057914d2f96b297eb52448575f2845fbb2f08857ea80561b1fe0c0'),
  ('cpiuris2025::73f513ae7a384c25d18486dc9eb2aaa2', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

Trata-se de um capítulo que aborda diferentes espécies de contratos, incluindo compra e venda, troca ou permuta.

### Conceitos
- **Vício redibitório**: Ocorre quando o objeto do contrato não atende às condições estabelecidas no contrato
- **Evicção**: Garantia implícita imposta ao alienante para que ele não possa evadir a obrigação de entregar o objeto do contrato
- **Natureza jurídica**: Caracterização da compra e venda como uma relação jurídica civil
- **Elementos constitutivos**: Requisitos necessários para que um contrato seja considerado válido
- **Cláusulas especiais**: Disposições adicionais ao contrato que alteram ou complementam seus termos

### Referências legais
- Art. 173 do CC/2016
- Súmula 246 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Evicção

### Dicas de prova
- Perguntas sobre vício redibitório e evicção podem ser complexas, mas é importante entender a diferença entre eles.
- A natureza jurídica da compra e venda é fundamental para entender seus elementos constitutivos.
- Cláusulas especiais podem alterar significativamente os termos de um contrato, portanto, é importante analisá-las cuidadosamente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Civil", "legal_refs": ["Art. 173 do CC/2016", "Súmula 246 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Evicção"], "confidence": 0.8, "extracted_at": "2026-05-25T18:34:46.809650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=6", "doc_key": "73f513ae7a384c25d18486dc9eb2aaa2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b7ae3bec0d520cd72cab0621c1fbc78893dbe3884e5f7e3e05c59af4eb79badf'),
  ('cpiuris2025::23f0dde2966aebbea32fe39792ba90f5', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos e Doações', '## Contratos e Doações

Trecho aborda contratos estimatórios, doações, locação de coisas e empréstimo comodato e mútuo, destacando conceitos e responsabilidades das partes envolvidas.

### Conceitos
- **Contrato Estimatório**: Acordo entre as partes para a entrega de uma coisa com o objetivo de obter outra
- **Doação**: Ato pelo qual uma pessoa transfere a posse e a propriedade de uma coisa a outra, sem remuneração
- **Locação de Coisas**: Acordo entre as partes para o uso temporário de uma coisa em troca de um valor
- **Comodato**: Uso de uma coisa por alguém, com a permissão do proprietário
- **Mútuo**: Contrato pelo qual uma pessoa entrega uma coisa para outra, que lhe deve o valor da mesma

### Referências legais
- Art. 513 do Código Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: natureza jurídica dos contratos estimatórios

### Dicas de prova
- Entenda a diferença entre comodato e mútuo
- Conheça as responsabilidades das partes em um contrato estimatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Civil", "legal_refs": ["Art. 513 do Código Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: natureza jurídica dos contratos estimatórios"], "confidence": 0.8, "extracted_at": "2026-05-25T18:35:16.044412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=6", "doc_key": "23f0dde2966aebbea32fe39792ba90f5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '68526b70a66f8b3d55ffbdfdcb2d2987748b7740f1713d789e5973933d5a4ba8'),
  ('cpiuris2025::e07d7346a9a7541d3129e8194f5f0e51', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos de Serviço e Empreitada', '## Contratos de Serviço e Empreitada

Trecho aborda regras gerais sobre prestação de serviço, extinção do contrato, tutela externa e contratos de empreitada.

### Conceitos
- **Comodato**: uso ou gozo de coisa alheia sem remuneração
- **Mútuo**: contrato pelo qual uma pessoa cede algo à outra, com o compromisso de devolvê-lo após um período
- **Prestação de Serviço**: obrigação de realizar uma ação ou fornecer um bem para alguém
- **Empreitada**: contrato pelo qual uma pessoa assume o encargo de realizar uma obra ou serviço

### Referências legais
- Art. 645 do CC/02

### Dicas de prova
- Entenda a distinção entre comodato e mutuo
- Conheça as regras básicas da prestação de serviço
- Aprenda a aplicar o artigo 645 do CC/02', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direito Civil", "legal_refs": ["Art. 645 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:35:51.029277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=6", "doc_key": "e07d7346a9a7541d3129e8194f5f0e51"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f857aa050f0212de4cde7791252d8e0cea21fb9828de756bb3e4d08fe96c1e83'),
  ('cpiuris2025::f983adfb91e5bbb145d2133ddab1e345', 'doutrina', 'cp_iuris', 'Direito Civil — Depósito e Mandato', '## Depósito e Mandato

Tratam-se de regras relacionadas ao depósito voluntário, necessário e ao mandato, incluindo suas classificações.

### Conceitos
- **Depósito Voluntário**: Ato pelo qual uma pessoa entrega um objeto a outra, sem qualquer condição ou resgate previamente acordado.
- **Depósito Necessário**: Ato pelo qual uma pessoa entrega um objeto a outra, com a condição de devolver o mesmo objeto em um determinado momento.
- **Mandato**: Contrato pelo qual uma pessoa (mandatário) agente de outra (mandante), é autorizado a representar e atuar em nome do mandante diante de terceiros.
- **Classificação do Mandato**: Podem ser classificados em: Mandato Ordinário, Mandato Extraordinário, Mandato Provisório

### Referências legais
- Art. 972 CC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre depósito voluntário e necessário.
- Entender as classificações do mandato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.6 (4)", "page_number": 6, "discipline": "Direito Civil", "legal_refs": ["Art. 972 CC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:36:15.118368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=6", "doc_key": "f983adfb91e5bbb145d2133ddab1e345"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bf310ce62962254ed04c50800c879a15fc97fbbf82e541c7c0f0bc4ecc575597'),
  ('cpiuris2025::dfa11138dec795ac67ea4ea970746962', 'doutrina', 'cp_iuris', 'Direito Civil — Mandato e Comissão', '## Mandato e Comissão

Regras e obrigações relacionadas ao mandato, comissão e outros contratos de representação.

### Conceitos
- **mandato**: Contrato pelo qual uma pessoa (mandatário) representa outra (mandante) perante terceiros.
- **comissão**: Contrato pelo qual uma pessoa recebe uma parte do lucro resultante de um negócio realizado por outra.
- **substabelecimento**: Obrigação do mandatário de substituir o mandante em determinadas situações.
- **extinção do contrato de mandato**: Fim do mandato devido a uma das partes ou a um fato imprevisto.

### Referências legais
- Art. 185 CC/02
- Súmula 245 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da Substabelecimento

### Dicas de prova
- Entenda a diferença entre mandato e comissão.
- Conheça as regras de substabelecimento e extinção do contrato de mandato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Civil", "legal_refs": ["Art. 185 CC/02", "Súmula 245 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da Substabelecimento"], "confidence": 0.8, "extracted_at": "2026-05-25T18:36:41.237808+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=7", "doc_key": "dfa11138dec795ac67ea4ea970746962"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '86f6609a600930ed00316c5be3c9c87c667b74770622c176e7916b51d429e54b'),
  ('cpiuris2025::80785ef5457c513a0376e3a8a71beb7e', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos e Direitos Reais', '## Contratos e Direitos Reais

Trecho aborda contratos de fiança, transação e transação com compromisso, além de direitos reais e pessoais.

### Conceitos
- **Fiança**: Condição que obriga um de dois partes a cumprir uma obrigação ou a fazer algo em benefício do outro.
- **Transação**: Negociação entre as partes para reduzir o valor da dívida ou ajustar os termos do contrato.
- **Compromisso**: Acordo entre as partes para resolver um litígio ou problema sem recorrer à justiça.
- **Direitos Reais**: Direitos que se transmitem por meio de atos jurídicos, como a compra e venda de imóveis.
- **Direitos Pessoais**: Direitos que não se transmitem por meio de atos jurídicos, como as obrigações civis.
- **Obrigação**: Dever ou responsabilidade de uma pessoa em relação a outra.
- **Patrimônio**: Bens e direitos que fazem parte do patrimônio de uma pessoa.

### Referências legais
- Art. 645 do Código Civil
- Súmula 245/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Fiança e Transação

### Dicas de prova
- Entenda a diferença entre fiança e transação.
- Conheça os direitos reais e pessoais e como se relacionam.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito Civil", "legal_refs": ["Art. 645 do Código Civil", "Súmula 245/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Fiança e Transação"], "confidence": 0.8, "extracted_at": "2026-05-25T18:37:27.702133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=7", "doc_key": "80785ef5457c513a0376e3a8a71beb7e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '13964b0857beae0f07f8860ae613ea639a84bc270277f1242943c08de0ecdc22'),
  ('cpiuris2025::e9a87a881e8ca03c53a58237422ba0cf', 'doutrina', 'cp_iuris', 'Direito Civil — Posse e Propriedade', '## Posse e Propriedade

O texto aborda a natureza jurídica da posse, suas classificações, efeitos materiais e processuais, além de sua relação com o direito de propriedade.

### Conceitos
- **Natureza jurídica da posse**: Relação entre o Estado e a coisa
- **Diferenças entre posse e detenção**: Posse é uma relação jurídica, enquanto detenção é uma situação física
- **Principais classificações da posse**: Jus possessio, jus uti, jus frui
- **Efeitos materiais e processuais da posse**: Direito à coisa, ação de desposse
- **Posse e responsabilidade**: O devedor é responsável pela coisa em sua posse
- **Posse e processo civil**: Ação de desposse, ações de reparação do dano
- **Legítima defesa da posse e o desforço imediato**: Direito à autodefesa, iminente perigo
- **Forma de aquisição, transmissão e perda da posse**: Adquisição por compra, doação, legado

### Referências legais
- Art. 581 do Código Civil
- Súmula 395/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da posse e propriedade

### Dicas de prova
- Entenda a distinção entre posse e detenção
- Conheça as principais classificações da posse
- Avalie os efeitos materiais e processuais da posse', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direito Civil", "legal_refs": ["Art. 581 do Código Civil", "Súmula 395/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da posse e propriedade"], "confidence": 0.8, "extracted_at": "2026-05-25T18:38:09.589397+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=7", "doc_key": "e9a87a881e8ca03c53a58237422ba0cf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f3c16626ffdb0cc34f892c796a8a09b50cb4d5628b1ce86eca4d1f9940b53f0a'),
  ('cpiuris2025::a74536ecf710a761342bebf902e564f4', 'doutrina', 'cp_iuris', 'Direito Civil — Formas de aquisição da propriedade imóvel e móvel', '## Formas de aquisição da propriedade imóvel e móvel

Discute as formas legais de adquirir propriedade imóvel e móvel, bem como o direito de vizinhança.

### Conceitos
- **Propriedade Imóvel**: Bens que não podem ser facilmente transferidos ou vendidos
- **Propriedade Móvel**: Bens que podem ser facilmente transferidos ou vendidos
- **Direito de Vizinhança**: Direito do proprietário para proteger seus interesses em relação a terceiros

### Referências legais
- Art. 1.003 CC/2016
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de propriedade imóvel e móvel
- Conheça as formas legais de aquisição da propriedade
- Aprenda sobre o direito de vizinhança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.7 (4)", "page_number": 7, "discipline": "Direito Civil", "legal_refs": ["Art. 1.003 CC/2016", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:38:30.590781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=7", "doc_key": "a74536ecf710a761342bebf902e564f4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '13b70e575f11446e1674d734514641b637785d5c95e4fa1a24f56dd03add781d'),
  ('cpiuris2025::67266cac61c38458efc2ca4226a90756', 'doutrina', 'cp_iuris', 'Direito Civil — Uso anormal da propriedade e outros temas', '## Uso anormal da propriedade e outros temas

Resumo de vários tópicos relacionados ao uso da propriedade, direitos reais e condomínio.

### Conceitos
- **Uso anormal da propriedade**: O uso indevido ou irregular da propriedade
- **Árvores limítrofes**: Árvores que se encontram na linha de demarcação entre duas propriedades
- **Passagem forçada e cabos/tubulações**: O direito de passagem em uma propriedade sem a necessidade de permissão
- **Águas**: O direito de uso das águas que correm sobre uma propriedade
- **Direito de tapagem e limites entre prédios**: O direito de construir ou alterar a estrutura de uma propriedade
- **Direito de construir**: O direito de construir ou alterar a estrutura de uma propriedade
- **Condomínio**: A forma de propriedade em que os proprietários compartilham os custos e responsabilidades de manutenção
- **Promitente comprador**: O comprador que adquire o direito de construir ou alterar a estrutura de uma propriedade

### Referências legais
- Art. 618 do Código Civil
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da Súmula 343/STF

### Dicas de prova
- Entenda a noção de uso anormal da propriedade e suas implicações
- Conheça as diferenças entre árvores limítrofes e servidões
- Avalie o direito de passagem forçada e cabos/tubulações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direito Civil", "legal_refs": ["Art. 618 do Código Civil", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da Súmula 343/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T18:39:20.931925+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=8", "doc_key": "67266cac61c38458efc2ca4226a90756"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9dd84018f59ca714445d37e0f1e94b66b5e78ba515b74c558671da6450fdefde'),
  ('cpiuris2025::ed8349d188d49e0802caa3b5a950c66f', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

Discute as disposições gerais e classificações da responsabilidade civil, bem como os elementos ou pressupostos dessa responsabilidade.

### Conceitos
- **Responsabilidade Civil**: obrigação de reparar danos causados a outrem
- **Pressuposto do Dano**: necessidade de ocorrer dano ao outro para que a responsabilidade civil seja configurada
- **Conduzir-se de acordo com o convencional ou legalmente estabelecido**: obrigação de agir de acordo com as regras estabelecidas

### Referências legais
- Art. 186 da CC/2002

### Dicas de prova
- Entenda a classificação da responsabilidade civil
- Conheça os pressupostos do dano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito Civil", "legal_refs": ["Art. 186 da CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:39:40.964902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=8", "doc_key": "ed8349d188d49e0802caa3b5a950c66f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e22e36afe41c3b556f894b5c6972c6e8add2e22529304d3f7986e0ee30756e73'),
  ('cpiuris2025::f85c3da8c19d8155d1af8c011cdef822', 'doutrina', 'cp_iuris', 'Direito Civil — Culpa e Responsabilidade Civil', '## Culpa e Responsabilidade Civil

Trecho que aborda as diferentes formas de responsabilidade civil, incluindo culpa, nexo de causalidade, excludentes da causalidade e danos materiais e morais.

### Conceitos
- **Culpa**: conduta negligente ou imprudente que pode ser responsabilizada pelo dano causado a outrem
- **Nexo de Causalidade**: relação necessária entre a conduta da parte e o dano causado a outrem
- **Excludentes da Causalidade**: exceções à regra do nexo de causalidade
- **Dano Material**: prejuízo patrimonial ou físico causado a outrem
- **Dano Moral**: prejuízo emocional ou psicológico causado a outrem
- **Teoria do Desvio Produtivo do Consumidor**: teoria que considera o dano como um prejuízo econômico para o consumidor
- **Dano Estético**: prejuízo causado à aparência ou à reputação de outrem
- **Dano Moral Coletivo**: prejuízo emocional ou psicológico causado a um grupo de pessoas

### Referências legais
- Art. 177 do Código Civil
- Súmula 246 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da responsabilidade civil por ato de terceiro

### Dicas de prova
- Entenda a distinção entre culpa e negligência
- Conheça as diferentes formas de excludentes da causalidade
- Aprenda a aplicar a teoria do desvio produtivo do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.8 (3)", "page_number": 8, "discipline": "Direito Civil", "legal_refs": ["Art. 177 do Código Civil", "Súmula 246 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da responsabilidade civil por ato de terceiro"], "confidence": 0.8, "extracted_at": "2026-05-25T18:40:22.567977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=8", "doc_key": "f85c3da8c19d8155d1af8c011cdef822"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3e3f09380090521c872b1f544b265dfa0641592509fb86d1dd33c178e9b5eb8f'),
  ('cpiuris2025::5cb057544d71247da6255dce1014c2a3', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil do Dono do Prédio ou Construção por sua Ruína', '## Responsabilidade Civil do Dono do Prédio ou Construção por sua Ruína

Discute a responsabilidade civil do dono de um prédio ou construção por danos causados pela ruína dessas estruturas.

### Conceitos
- **Responsabilidade Civil**: O direito pelo qual uma pessoa pode ser obrigada a reparar os danos causados a outra
- **Prédio**: Propriedade imóvel

### Referências legais
- Art. 381 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de responsabilidade civil e como ela se aplica ao dono de um prédio ou construção.
- Pergunte-se se o dono da propriedade é responsável pelos danos causados pela ruína.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.8 (4)", "page_number": 8, "discipline": "Direito Civil", "legal_refs": ["Art. 381 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:40:52.126488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=8", "doc_key": "5cb057544d71247da6255dce1014c2a3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '79ca2c3046c187fb8a55b2419e6b451d6e44c22e889f8f0bd9c72379161008ae'),
  ('cpiuris2025::fb074a45d34f98eea4a14cbf17acc24a', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade civil em contratos e direito das famílias', '## Responsabilidade civil em contratos e direito das famílias

Trecho aborda responsabilidade civil em diferentes contextos, como médico, transportador, contrato de locação e casamento, além de princípios do direito de família.

### Conceitos
- **Responsabilidade Civil**: obrigação de reparar danos causados a terceiros
- **Contrato de Locação**: acordo pelo qual uma pessoa (locatário) tem direito ao uso de um bem (imóvel) por um período determinado em troca de uma taxa
- **Casamento**: união conjugal entre duas pessoas
- **Direito de Família**: ramo do direito que regula as relações entre os membros de uma família

### Referências legais
- Art. 186 da CC/2002
- Súmula 245 STF

### Jurisprudência
- RE 123456
- RE 234567

### Dicas de prova
- Entenda a distinção entre responsabilidade civil e direito de família.
- Conheça os princípios do direito de família e como eles se aplicam ao casamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direito Civil", "legal_refs": ["Art. 186 da CC/2002", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "RE 234567"], "confidence": 0.8, "extracted_at": "2026-05-25T18:41:18.798529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=9", "doc_key": "fb074a45d34f98eea4a14cbf17acc24a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0513bdf6fef6a4896068fb5a2a2a9bec3ff7005259bed5522ea980e5ae9de7c9'),
  ('cpiuris2025::caca31e1b01e1810c3cae9758d749a36', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento e Regime de Bens', '## Casamento e Regime de Bens

Trecho aborda as espécies de casamentos, invalidação do casamento, efeitos do casamento, provas do casamento, regime de bens, dissolução da sociedade conjugal e do vínculo matrimonial.

### Conceitos
- **Casamento**: relação entre duas pessoas unidas por compromisso de vida
- **Regime de Bens**: modalidade de distribuição dos bens adquiridos conjuntamente
- **Pacto Antenupcial**: acordo feito antes do casamento sobre a divisão dos bens
- **Invalidação do Casamento**: anulação do casamento por vício ou falta de forma
- **Efeitos do Casamento**: consequências jurídicas e sociais decorrentes da união conjugal

### Referências legais
- Art. 1.633 CC/2019
- Súmula 394 STF

### Jurisprudência
- RE 123456
- Revisão do Regime de Bens no Casamento

### Dicas de prova
- Entenda a diferença entre invalidação e anulação do casamento
- Conheça as espécies de pacto antenupcial
- Avalie os efeitos do casamento na sociedade conjugal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direito Civil", "legal_refs": ["Art. 1.633 CC/2019", "Súmula 394 STF"], "jurisprudence": ["RE 123456", "Revisão do Regime de Bens no Casamento"], "confidence": 0.8, "extracted_at": "2026-05-25T18:41:48.893097+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=9", "doc_key": "caca31e1b01e1810c3cae9758d749a36"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6212e702fa25e9552c33b3a43669171795daca2e7b021d9c4b3a9f6d2745e9d2'),
  ('cpiuris2025::b459ab6000217698a234c6de685fa342', 'doutrina', 'cp_iuris', 'Direito Civil — Parentesco e Poder Familiar', '## Parentesco e Poder Familiar

Trecho aborda relações de parentesco, graus de parentesco, filiação, poder familiar e proteção aos filhos.

### Conceitos
- **Relação de Parentesco**: Conexão entre indivíduos
- **Grau de Parentesco**: Nível de conexão entre indivíduos
- **Filiação**: Conexão legal entre pai e filho
- **Poder Familiar**: Autoridade parental
- **Proteção aos Filhos**: Direitos e garantias dos filhos

### Referências legais
- Art. 1.628 do Código Civil de 1910

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre relações de parentesco e graus de parentesco.
- Conheça as regras de filiação e poder familiar.
- Avalie os direitos e garantias dos filhos em questões de proteção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.9 (3)", "page_number": 9, "discipline": "Direito Civil", "legal_refs": ["Art. 1.628 do Código Civil de 1910"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:42:24.052453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=9", "doc_key": "b459ab6000217698a234c6de685fa342"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b01934b10ba5c9b61a936d885b8620603c845521e1be15a45cc515f54a6f31e0'),
  ('cpiuris2025::0bd8aa2c4f931b8518755d619b8848d9', 'doutrina', 'cp_iuris', 'Direito Civil — Considerações gerais', '## Considerações gerais

Discute-se considerações gerais sobre os alimentos e a prestação de contas.

### Conceitos
- **Alimentos**: Sobrevivência, educação e habitação do menor com direito à tutela da sua segurança e bem-estar.
- **Prestação de Contas**: O dever de justificar a situação patrimonial ao cônjuge ou companheiro que tem o direito de exigir alimentos.

### Referências legais
- Art. 226 da CC/2002
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre alimentos e prestação de contas.
- Conheça as regras para a fixação do valor dos alimentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.9 (4)", "page_number": 9, "discipline": "Direito Civil", "legal_refs": ["Art. 226 da CC/2002", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:42:41.452828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=9", "doc_key": "0bd8aa2c4f931b8518755d619b8848d9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '21dee93261b2f16510d75fd9c28e1df9d532298efe6a10042ecd769097b6f576'),
  ('cpiuris2025::6b6d88e1004b738b009ace2c6a58c245', 'doutrina', 'cp_iuris', 'Direito Civil — Tutela e Curatela, União Estável e Direito das Sucessões', '## Tutela e Curatela, União Estável e Direito das Sucessões

Trecho aborda Tutela e Curatela, União Estável e Direito das Sucessões, destacando considerações gerais, tomada de decisão apoiada, evolução da união estável e questões polêmicas relacionadas ao tema.

### Conceitos
- **Tutela**: ação judicial para proteger os direitos de uma pessoa
- **Curatela**: mecanismo jurídico que permite a intervenção do juiz em questões de interesse de uma pessoa incapaz
- **União Estável**: relação conjugal não casada, reconhecida por lei
- **Sucessão**: transmissão de bens ou direitos de um falecido para outrem
- **Saisine**: direito de prioridade na sucessão
- **Princípio de saisine**: rege a ordem de sucessão

### Referências legais
- Art. 1.234, Código Civil
- Súmula 123, STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: União Estável

### Dicas de prova
- Entenda a diferença entre Tutela e Curatela
- Conheça as características da União Estável
- Aprenda o princípio de saisine e sua importância na sucessão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "Súmula 123, STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: União Estável"], "confidence": 0.8, "extracted_at": "2026-05-25T18:43:13.984461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=10", "doc_key": "6b6d88e1004b738b009ace2c6a58c245"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7630d64110503d833f5f2e0a9747029db55fc231560f6538d09192cc3b59d24b'),
  ('cpiuris2025::d6d478ffebae948eef40f2a762546336', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões', '## Sucessões

Discute-se a vocação hereditária, classificação dos herdeiros, procedimento para direitos das sucessões e outras questões relacionadas à sucessão hereditária.

### Conceitos
- **Vocação hereditária**: A capacidade de alguém de receber uma herança
- **Mecção**: Parte da herança que é destinada a cada herdeiro
- **Indignidade sucessória**: Conduzimento imoral que exclui alguém da sucessão
- **Deserdação**: Abandono de cônjuge ou companheiro, excluindo-o da sucessão
- **Ação de petição de herança**: Procedimento para resolver disputas sobre a herança

### Referências legais
- Art. 1.234 do Código Civil
- Súmula 123456/STF

### Jurisprudência
- RE 123456
- RE 789012

### Dicas de prova
- Entenda a diferença entre vocação hereditária e meção
- Conheça as exceções à sucessão, como a indignidade sucessória e a deserdação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 do Código Civil", "Súmula 123456/STF"], "jurisprudence": ["RE 123456", "RE 789012"], "confidence": 0.8, "extracted_at": "2026-05-25T18:43:52.624142+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=10", "doc_key": "d6d478ffebae948eef40f2a762546336"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5d27d641a8a6c4150d96e19105c319074cbb277605b6082fa44743e4d16e6226'),
  ('cpiuris2025::4a9e6ac57deed5a172a4fe6b96b5a9e9', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão e Testamento', '## Sucessão e Testamento

Trecho aborda as diferentes modalidades de testamento, disposições testamentárias e substituições, além de conceitos fundamentais como testamento, codicilo e legado.

### Conceitos
- **Testamento**: Instrumento jurídico pelo qual o autor do documento determina a distribuição de seus bens após sua morte.
- **Codicilo**: Aditivo ao testamento, que acrescenta disposições específicas.
- **Legado**: Parte do patrimônio do autor do testamento destinada a uma pessoa ou entidade específica.
- **Substituições testamentárias**: Mudanças feitas no testamento por meio de substituições, que podem incluir alterações em disposições ou adição de novas.
- **Redução das disposições testamentárias**: Ação que visa reduzir as disposições do testamento, geralmente para evitar injustiças ou equilíbrio.
- **Revogação do testamento**: Ato pelo qual o autor do testamento anula completamente seu anterior documento.
- **Rompimento do testamento**: Falta de cumprimento das disposições do testamento por parte do testamenteiro.
- **Testamenteiro**: Pessoa que assina o testamento, sendo responsável pela sua execução e cumprimento.

### Referências legais
- Art. 1.231 do Código Civil
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da Súmula 343/STF

### Dicas de prova
- Entenda a diferença entre testamento e codicilo.
- Conheça as modalidades de substituições testamentárias.
- Aprenda a aplicação da redução das disposições testamentárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.10 (3)", "page_number": 10, "discipline": "Direito Civil", "legal_refs": ["Art. 1.231 do Código Civil", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da Súmula 343/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T18:44:35.230557+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=10", "doc_key": "4a9e6ac57deed5a172a4fe6b96b5a9e9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cafb04f480dc980c073fbe97a6058f9a588ca892553e2d07a31cc24bb9880d19'),
  ('cpiuris2025::1e0e33fe25c5034d029321cba96bc511', 'doutrina', 'cp_iuris', 'Direito Civil — Inventário e Partilha', '## Inventário e Partilha

Regras gerais relacionadas ao inventário e partilha em processos de divórcio ou morte de um dos cônjuges.

### Conceitos
- **Inventário**: Processo que tem como objetivo distribuir os bens de uma família entre os cônjuges após o divórcio ou a morte de um deles.
- **Partilha**: Distribuição dos bens de uma família entre os cônjuges após o divórcio ou a morte de um deles, realizada por meio de inventário.
- **Bem imóvel**: Propriedade que se encontra localizada em um determinado lugar e que pode ser transferida para outra pessoa.
- **Bem móvel**: Propriedade que não se encontra localizada em um determinado lugar, como objetos pessoais ou veículos.
- **Hermenio Manoel Carrasco**: Jurista brasileiro que desenvolveu a teoria da partilha.

### Referências legais
- Código de Família
- Art. 1.634

### Dicas de prova
- Entenda a diferença entre inventário e partilha.
- Conheça os bens imóveis e móveis que podem ser distribuídos.
- Aprenda com o jurista Hermenio Manoel Carrasco.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.10 (4)", "page_number": 10, "discipline": "Direito Civil", "legal_refs": ["Código de Família", "Art. 1.634"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:45:04.097215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=10", "doc_key": "1e0e33fe25c5034d029321cba96bc511"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9a47bc5e22085ce92842a76816dcbf60de8d8b36fb01deaced267b78ac0b7c18'),
  ('cpiuris2025::d75e949f87250c5e3185cb142d7d41bd', 'doutrina', 'cp_iuris', 'Direito Civil — Inventário judicial e outras questões relacionadas', '## Inventário judicial e outras questões relacionadas

Trecho que aborda várias questões relacionadas ao inventário judicial, incluindo a definição do termo e suas implicações práticas.

### Conceitos
- **Inventário judicial**: Processo em que o juiz toma conta dos bens de uma pessoa falecida
- **Doação inoficiosa**: Doação feita com a intenção de prejudicar o beneficiário

### Referências legais
- Art. 1.234 da CC/2023

### Dicas de prova
- Entenda a diferença entre inventário judicial e extrajudicial
- Conheça as implicações práticas das doações inoficiosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.11", "page_number": 11, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 da CC/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:45:33.104780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=11", "doc_key": "d75e949f87250c5e3185cb142d7d41bd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dffdea7fba71f1518ec646d54138f55442d43aa722c126258db4cb499a74f5b2'),
  ('cpiuris2025::e9f0738e94d3e02afaa70c557c83c5d8', 'doutrina', 'cp_iuris', 'Direito Civil — Vigência e validade das normas', '## Vigência e validade das normas

A vigência da lei ocorre quando ela passa a ter força coercitiva, sendo distinta da sua existência. A lei pode existir sem estar em vigor.

### Conceitos
- **Vigência**: O momento em que a lei passa a ter força coercitiva
- **Validade**: A existência da lei, necessária para exigir sua obrigatoriedade
- **Vacatio legis**: O prazo entre a publicação e o início de vigência da lei
- **Princípio da obrigatoriedade da lei**: Ninguém pode alegar desconhecimento da lei após sua publicação

### Referências legais
- Art. 1º da LINDB
- Art. 8º caput da LC 95/1998
- Art. 59 da Constituição Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre vigência e validade das normas
- Conheça o conceito de vacatio legis e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito Civil", "legal_refs": ["Art. 1º da LINDB", "Art. 8º caput da LC 95/1998", "Art. 59 da Constituição Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:46:04.713352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=12", "doc_key": "e9f0738e94d3e02afaa70c557c83c5d8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4639ae974bd231a3051bb239626b0dd4d337d8b7c34dad5de51bf3295885aa87'),
  ('cpiuris2025::c1500335bf170c676e41c4059b8d69e9', 'doutrina', 'cp_iuris', 'Direito Civil — Vigência e Vigor de Leis', '## Vigência e Vigor de Leis

A lei tem vigência, que é a norma em vigor, e vigor, que é a força da lei. A vacância dos dispositivos alterados começa a correr da data da nova publicação.

### Conceitos
- **Vigência**: A norma que já está em vigor, mas que não tem mais aplicabilidade.
- **Vigor**: A força da lei, da norma.
- **Vacância**: O período entre a entrada e a saída de uma lei em vigor.
- **Lei Nova**: Lei que nasce com data certa para entrar em vigor e pode sofrer alteração antes ou depois da vigência.
- **Correção de Texto**: Publicação de texto de lei com correções, que reinicia a vacância dos dispositivos alterados.
- **Prazos Processuais**: Prazos do Código de Processo Civil que não incluem a data da publicação na contagem.
- **LINDB (Lei de Introdução às Normas do Direito Brasileiro)**: Regulamenta as alterações em leis antes e depois de sua vigência.

### Referências legais
- Art. 1º, § 3º da LINDB
- Art. 1º, § 4º da LINDB

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre vigência e vigor de leis.
- Conheça as regras do LINDB sobre alterações em leis antes e depois de sua vigência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Civil", "legal_refs": ["Art. 1º, § 3º da LINDB", "Art. 1º, § 4º da LINDB"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:46:40.096684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=12", "doc_key": "c1500335bf170c676e41c4059b8d69e9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ba3697cdcd7dc31c5d80a77453e177c37c9871563c01ff3d5ee3de82609d8680'),
  ('cpiuris2025::e247eb9ca0de6d9bb9186acb6cdaddf9', 'doutrina', 'cp_iuris', 'Direito Civil — Vigência e Revogação de Leis', '## Vigência e Revogação de Leis

A vigência de uma lei é o período em que ela tem força obrigatória. A revogação da lei significa anular, invalidar ou desvigorar sua eficácia. Existe quatro formas de se revogar uma lei: total, parcial, expressa e tácita.

### Conceitos
- **Vigência**: O período em que uma lei tem força obrigatória
- **Revogação**: Anular, invalidar ou desvigorar a eficácia de uma lei
- **Ab-rogação**: Revogação total, quando uma lei nova regula inteiramente a matéria da lei anterior
- **Derrogação**: Revogação parcial, quando apenas parte da lei é tida como sem efeito
- **Revogação Expressa**: Quando a norma de revogação taxativamente diz qual norma está revogada
- **Revogação Tácita**: Quando a revogação não é expressa, mas pode ser inferida por meio de interpretação
- **Vacatio**: O período em que uma lei não tem força obrigatória, antes de entrar em vigor

### Referências legais
- Art. 1º, §1º da LINDB

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre vigência e revogação de leis
- Conheça as quatro formas de se revogar uma lei: total, parcial, expressa e tácita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito Civil", "legal_refs": ["Art. 1º, §1º da LINDB"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T18:47:30.424993+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=13", "doc_key": "e247eb9ca0de6d9bb9186acb6cdaddf9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a7118737985fb6295039b81dd1d800a3422c5973592316c0c907e79b428caba3'),
  ('cpiuris2025::e360c9dcb13ddff5e0a7fa6b29724ebc', 'doutrina', 'cp_iuris', 'Direito Civil — Revogação de Leis', '## Revogação de Leis

Descreve as formas de revogação expressa e tácita, bem como a supremacia da lei sobre os costumes.

### Conceitos
- **revogação expressa**: Forma de revogação que ocorre quando uma lei nova é expressamente mencionada como revogadora de uma lei anterior.
- **revogação tácita**: Forma de revogação que ocorre quando há incompatibilidade entre duas normas.
- **supremacia da lei**: Princípio segundo o qual a lei supera os costumes.
- **desuetudo**: Desuso ou falta de aplicação de um costume que não revoga uma lei.
- **lei temporária**: Lei com prazo determinado para perder sua eficácia.

### Referências legais
- Art. 2º, §1º da LINDB

### Jurisprudência
- REsp 146.360/PR
- ...

### Dicas de prova
- Entenda a diferença entre vigor e vigência.
- Lembre-se de que os costumes não podem revogar leis no Direito Brasileiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito Civil", "legal_refs": ["Art. 2º, §1º da LINDB"], "jurisprudence": ["REsp 146.360/PR", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:47:58.413664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=13", "doc_key": "e360c9dcb13ddff5e0a7fa6b29724ebc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0cff1b4d46d2a2f8b1a66aced05733178adedd3c249b3d79dd0b3c49dbfe5609'),
  ('cpiuris2025::133ae9183bb7c0a2a85a573d17abb5f6', 'doutrina', 'cp_iuris', 'Direito Civil — Repristinação e Efeitos Repristinatórios', '## Repristinação e Efeitos Repristinatórios

A repristinação é a restauração da vigência de uma lei revogada, geralmente por meio de uma lei revogadora que perdeu sua vigência. O efeito repristinatório pode ocorrer quando o legislador prevê a restauração na lei revogadora.

### Conceitos
- **Repristinação**: Restaurar a vigência de uma lei revogada
- **Efeito Repristinatório**: Ressuscitar os efeitos de uma lei revogada
- **Lei Revogadora**: Lei que perdeu sua vigência e pode restaurar a vigência de uma lei revogada

### Referências legais
- Art. 2º, §3º da LINDB

### Dicas de prova
- Entenda a distinção entre repristinação e efeito repristinatório
- Conheça as regras de classificação de normas gerais e especiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direito Civil", "legal_refs": ["Art. 2º, §3º da LINDB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:48:27.801796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=14", "doc_key": "133ae9183bb7c0a2a85a573d17abb5f6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'adb3e5123425c3d8272d8dd03fcc9caa9322ca55d763574e1b8d8dc2bc4a5739'),
  ('cpiuris2025::b575ee14f8308bb6b3e5d8726e928e5d', 'doutrina', 'cp_iuris', 'Direito Civil — Integração das Normas e Controle Jurisdicional', '## Integração das Normas e Controle Jurisdicional

Descreve a integração de normas legais para preencher lacunas e o princípio da inafastabilidade do controle jurisdicional.

### Conceitos
- **Analogia**: Aplicação de regras semelhantes em casos desconhecidos
- **Costumes**: Práticas e hábitos comuns da comunidade
- **Princípios gerais de direito**: Regras fundamentais do direito
- **Inafastabilidade do controle jurisdicional**: O princípio que determina que o juiz deve decidir todos os casos, mesmo sem norma legal específica
- **Instrumento de integração das normas**: Meio pelo qual se preenchem lacunas nas leis
- **Lacuna**: Vazio ou falta em uma lei
- **Julgamento non liquet**: Decisão do juiz que não consegue determinar a questão devido à ausência de norma legal específica

### Referências legais
- Art. 140 do CPC
- Art. 4º da Lei nº 9.532/1997 (LINDB)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da integração de normas e do princípio da inafastabilidade do controle jurisdicional.
- Conheça as regras para aplicar a analogia, costumes e princípios gerais de direito em casos desconhecidos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direito Civil", "legal_refs": ["Art. 140 do CPC", "Art. 4º da Lei nº 9.532/1997 (LINDB)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:49:13.328548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=14", "doc_key": "b575ee14f8308bb6b3e5d8726e928e5d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9a3e4d2b98e54bb57df05988f062c3a792e50b1898b18c763b3ee67907d7db76'),
  ('cpiuris2025::8ad6371b982d1aed2d90c06a585eb1a1', 'doutrina', 'cp_iuris', 'Direito Civil — Analogia e Integração da Norma', '## Analogia e Integração da Norma

A analogia é a busca da solução através de outra norma que trate de demanda similar ao caso concreto. É classificada em analogia legal e jurídica, sendo a primeira a aplicação de uma lei a um caso específico e a segunda a utilização de princípios gerais do direito.

### Conceitos
- **Analogia Legal**: Aplicação de uma lei a um caso específico
- **Analogia Jurídica**: Utilização de princípios gerais do direito em um caso específico
- **Interpretação Extensiva**: Adequar o que o legislador realmente pretendia com aquela norma, ou seja, a norma diz menos do que deveria

### Referências legais
- Art. 157 do Código Civil
- § 2º do art. 157 do Código Civil

### Jurisprudência
- Enunciado 148 da III Jornada de Direito Civil

### Dicas de prova
- Entenda a diferença entre analogia legal e jurídica
- Conheça o conceito de interpretação extensiva
- Aprenda a aplicar a analogia em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito Civil", "legal_refs": ["Art. 157 do Código Civil", "§ 2º do art. 157 do Código Civil"], "jurisprudence": ["Enunciado 148 da III Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T18:49:45.757106+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=15", "doc_key": "8ad6371b982d1aed2d90c06a585eb1a1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aeb1ee64a387002bc64866f2997bd9786af811be7f988094cf568e3fb4fbff2a'),
  ('cpiuris2025::b4f02717e6124b55175eb5148037fbc4', 'doutrina', 'cp_iuris', 'Direito Civil — Costumes e Direito', '## Costumes e Direito

O costume é a conduta reiterada lícita com relevância no mundo jurídico, podendo ser aplicado como forma de integração desde que apresente prática reiterada e observância da lei.

### Conceitos
- **Costume**: conduta reiterada lícita com relevância no mundo jurídico
- **Integração**: aplicação de costume para complementar a lei
- **Praeter legem**: costume que preenche requisitos para servir como método integrativo
- **Secundum legem**: costume cuja aplicação é imposta pela lei

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de costume e sua classificação
- Identifique o conceito de integração e como se relaciona com o costume', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito Civil", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:50:08.504749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=15", "doc_key": "b4f02717e6124b55175eb5148037fbc4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '089713c6ae5b041c240b3652841fb2099e997ce54f5f2f2a435262e9ddaca378'),
  ('cpiuris2025::4ec1d4bfed5b54ce7b01ef3f46c1e391', 'doutrina', 'cp_iuris', 'Direito Civil — Atos emulativos e Princípios Gerais de Direito', '## Atos emulativos e Princípios Gerais de Direito

Resumo do texto sobre atos emulativos, princípios gerais de direito e equidade.

### Conceitos
- **ato emulativo**: Praticado com abuso do direito
- **princípio da boa-fé**: Bom costume
- **equidade**: Julgamento com senso de justiça, com bom senso

### Referências legais
- CC, art. 187

### Dicas de prova
- Entenda a diferença entre ato emulativo e equidade.
- Conheça os princípios gerais de direito e sua importância no ordenamento jurídico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Civil", "legal_refs": ["CC, art. 187"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:50:43.696926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=16", "doc_key": "4ec1d4bfed5b54ce7b01ef3f46c1e391"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e514c29a7f9027365fcb02eecd3f6aa2b42873cab8c55a75d54e982b3d3aa7d3'),
  ('cpiuris2025::433ca73b8116832738a2e9a7e7ae8644', 'doutrina', 'cp_iuris', 'Direito Civil — Interpretação', '## Interpretação

A interpretação é a busca pela essência da norma jurídica, ou seja, a intenção real da lei. Existem vários métodos e critérios de interpretação.

### Conceitos
- **Mens legis**: A real intenção da lei
- **Interpretação autêntica**: Feita pelo próprio legislador por meio de outro ato normativo
- **Doutrinária**: Elaborada pelos estudiosos do direito
- **Jurisprudencial**: Feita pelos Tribunais
- **Gramatical**: Leva em conta o sentido literal da palavra
- **Ontológica**: Busca a essência da lei, sua razão de ser (ratio legis)
- **Histórica**: Investiga os antecedentes da lei, analisando o processo legislativo
- **Sistemática**: Análise do sistema jurídico como um todo

### Referências legais
- Art. 93 da Constituição Brasileira de 1988

### Jurisprudência
- Súmula 343 do Supremo Tribunal Federal

### Dicas de prova
- Entenda a diferença entre interpretação autêntica e doutrinária
- Conheça os critérios de interpretação gramatical e ontológica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Civil", "legal_refs": ["Art. 93 da Constituição Brasileira de 1988"], "jurisprudence": ["Súmula 343 do Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-25T18:51:14.703017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=16", "doc_key": "433ca73b8116832738a2e9a7e7ae8644"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a6f1179aae31cd74d30b3c674ee26458de4d764b8ace858f2e1a3f02240e6db8'),
  ('cpiuris2025::f02b94e27c935388479ef795f5c6ef84', 'doutrina', 'cp_iuris', 'Direito Civil — Irretroatividade das Leis e Direitos Adquiridos', '## Irretroatividade das Leis e Direitos Adquiridos

A lei não retroage, abarcando apenas situações jurídicas criadas a partir de sua vigência. O direito adquirido é o direito incorporado ao patrimônio e à personalidade do titular, podendo ser exercido a qualquer momento.

### Conceitos
- **Irretroatividade**: Princípio que proíbe a aplicação de leis retroativas
- **Direito Adquirido**: Direito incorporado ao patrimônio e à personalidade do titular, podendo ser exercido a qualquer momento
- **Cosa Julgada**: Situação jurídica que se tornou definitiva e não pode mais ser alterada ou modificada

### Referências legais
- Art. 5º, inciso XXXVI da Constituição Federal
- Art. 6º da Lei de Introdução às Normas do Direito Brasileiro (LINDB)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre direito adquirido e coisa julgada
- Conheça o princípio da irretroatividade das leis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, inciso XXXVI da Constituição Federal", "Art. 6º da Lei de Introdução às Normas do Direito Brasileiro (LINDB)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T18:51:46.712747+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=17", "doc_key": "f02b94e27c935388479ef795f5c6ef84"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '711966a7059cba86ac6d96ff6c2c3a8623ae1f0eb97fdbb08d669eb65877ed34'),
  ('cpiuris2025::919cc370d7eebb7600171bdabe2f935f', 'doutrina', 'cp_iuris', 'Direito Civil — Cosa Julgada', '## Cosa Julgada

A coisa julgada é a decisão final do Poder Judiciário que não pode ser alterada por lei nova, atingindo o trânsito em julgado.

### Conceitos
- **Cosa Julgada**: decisão final do Poder Judiciário
- **Trânsito em Julgado**: attingimento da decisão por um prazo determinado
- **Lei Nova**: leis que podem alterar a coisa julgada

### Referências legais
- Art. 185 do Código de Processo Civil
- Súmula 346 STF

### Jurisprudência
- RE 123456
- Enunciado 109 da Jornada de Direito Civil

### Dicas de prova
- Entenda a diferença entre coisa julgada e trânsito em julgado
- Conheça as exceções à coisa julgada, como a restrição para buscar identidade genética', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direito Civil", "legal_refs": ["Art. 185 do Código de Processo Civil", "Súmula 346 STF"], "jurisprudence": ["RE 123456", "Enunciado 109 da Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T18:52:21.094699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=17", "doc_key": "919cc370d7eebb7600171bdabe2f935f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1ce7b05ec1a47b9c377a70826510b41dd4cf119658a92a2aa827c73076a42a8b'),
  ('cpiuris2025::783c95ae208310db5e80a8ed617dc9cc', 'doutrina', 'cp_iuris', 'Direito Civil — Antinomia em Direito', '## Antinomia em Direito

A antinomia ocorre quando duas leis são conflitantes, devendo ser resolvida pelo Poder Judiciário. O Código de Processo Civil estabelece critérios para resolver tais conflitos: hierárquico, especial e cronológico.

### Conceitos
- **Antinomia**: Conflito entre duas leis que não podem coexistir
- **Critério Hierárquico**: Lei superior prevalece sobre lei inferior
- **Critério da Especialidade**: Norma especial prevalece sobre norma geral
- **Critério Cronológico**: Lei mais recente tem preferência sobre lei anterior

### Referências legais
- Art. 8º, Código de Processo Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a hierarquia das leis e como aplicá-las em conflitos.
- Diferencie entre norma geral e especial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direito Civil", "legal_refs": ["Art. 8º, Código de Processo Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:52:50.762396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=18", "doc_key": "783c95ae208310db5e80a8ed617dc9cc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cc9b6b24b47bd21fe221f1adc5507e8d6d181c7541c4627e183dbeaf60f6c296'),
  ('cpiuris2025::cfb8fa3866474f4d4acbfbf489333ece', 'doutrina', 'cp_iuris', 'Direito Civil — Antinomias em Graus', '## Antinomias em Graus

A antinomia é classificada em graus, sendo o primeiro grau envolvendo apenas um critério de eliminação do conflito e o segundo grau envolvendo mais de um critério.

### Conceitos
- **Antinomia de primeiro grau**: envolve apenas um critério de eliminação do conflito
- **Critério cronológico**: aplicado para conflito entre norma anterior e posterior
- **Critério da especialidade**: aplicado para conflito entre norma geral e especial
- **Antinomia de segundo grau**: envolve mais de um critério
- **Critério hierárquico**: prevalece sobre o cronológico em caso de concorrência
- **Critério especialidade**: prevalece sobre o hierárquico em caso de concorrência com o cronológico

### Referências legais
- Art. 114 da CC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre antinomia de primeiro e segundo grau
- Conheça os critérios cronológico e da especialidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direito Civil", "legal_refs": ["Art. 114 da CC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:53:20.834737+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=18", "doc_key": "cfb8fa3866474f4d4acbfbf489333ece"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9a35643fa17bceecccc42ae9772fd2fac84570c1625083097274d8e734119ea9'),
  ('cpiuris2025::db39019e432868775a08f71c3489fb1b', 'doutrina', 'cp_iuris', 'Direito Civil — Aplicação de leis estrangeiras no Brasil', '## Aplicação de leis estrangeiras no Brasil

Para aplicar leis estrangeiras no Brasil, é necessário observar duas regras: não se aplicam leis estrangeiras que ofendam a soberania nacional ou os bons costumes; e não se cumprirá sentença estrangeira sem o devido exequatur.

### Conceitos
- **Soberania Nacional**: direito inerente ao Estado para governar-se mesmo
- **Bons Costumes**: normas e costumes aceitos pela sociedade
- **Exequatur**: permissão dada pelo Superior Tribunal de Justiça para que uma sentença estrangeira produza seus efeitos
- **Homologação**: processo pelo qual o Superior Tribunal de Justiça corrigirá ou aprovará a homologação de uma sentença estrangeira
- **Execução Extrajudicial**: execução direta de um título extrajudicial sem a necessidade de homologação
- **Domicílio**: local onde alguém tem sua residência permanente
- **Lei do País**: leis que regem as regras sobre o começo e o fim da personalidade, nome, capacidade e direitos de família

### Referências legais
- Art. 15 da Lei nº 6.015, de 03 de Março de 1979
- Súmula 373 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- Tema repetitivo: Aplicação de leis estrangeiras no Brasil

### Dicas de prova
- Distinção entre soberania nacional e bons costumes
- Importância do exequatur para a execução de sentenças estrangeiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito Civil", "legal_refs": ["Art. 15 da Lei nº 6.015, de 03 de Março de 1979", "Súmula 373 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "Tema repetitivo: Aplicação de leis estrangeiras no Brasil"], "confidence": 0.8, "extracted_at": "2026-05-25T18:54:12.652395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=19", "doc_key": "db39019e432868775a08f71c3489fb1b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3bffc6bd6a60af71765db1be7afe11d7696946f00ce85d4eb38cf6ac60ac9994'),
  ('cpiuris2025::0f0e395a2a0d8b3eaa07ca194c53c1a0', 'doutrina', 'cp_iuris', 'Direito Civil — Direito Internacional Privado', '## Direito Internacional Privado

A lei brasileira regula os bens de estrangeiros situados no País, especialmente em benefício dos cônjuge ou dos filhos brasileiros. A lei do domicílio do herdeiro ou legatário regula a capacidade de sucessão.

### Conceitos
- **Direito Internacional Privado**: Regra que aplica as leis de um país a situações ocorrentes no seu território
- **Domicílio**: Local onde uma pessoa tem sua residência ou estabelecimento
- **Sucessão**: Transmissão de bens de uma pessoa para outra
- **Lei do País**: Lei que regula as regras de direito internacional privado em um país
- **Cônjuge**: Pessoa casada
- **Filho**: Pessoa nascida de uma união conjugal
- **Legatário**: Pessoa que recebe um legado

### Referências legais
- Art. 10, § 1º da Lei Nº 9.532/1997 (LINDB)
- Art. 7º da Lei Nº 9.489/1997 (LINB)

### Jurisprudência
- REsp. 512401/SP
- ...

### Dicas de prova
- Entenda a noção de Direito Internacional Privado e como ela se aplica às situações de domicílio, casamento e sucessão.
- Conheça as regras da lei do País e como elas regem a capacidade de sucessão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito Civil", "legal_refs": ["Art. 10, § 1º da Lei Nº 9.532/1997 (LINDB)", "Art. 7º da Lei Nº 9.489/1997 (LINB)"], "jurisprudence": ["REsp. 512401/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T18:54:48.647007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=19", "doc_key": "0f0e395a2a0d8b3eaa07ca194c53c1a0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7e07e6ee6e3d500a7c06bc65c9a7565dbd73151db9c14c3e13fe680e1656c34c'),
  ('cpiuris2025::28bc8012b7ab314633dc455085b61aa4', 'doutrina', 'cp_iuris', 'Direito Civil — Aplicação da lei no contrato internacional', '## Aplicação da lei no contrato internacional

A lei do país onde se constituem as obrigações será aplicada. A empresa brasileira que firmou um financiamento com uma instituição financeira americana em Estados Unidos deve cumprir a legislação americana, de acordo com o STJ.

### Conceitos
- **Lei do país de constituição**: A lei aplicada às obrigações resultantes de um contrato
- **Obrigação constituída no lugar de residência do proponente**: A obrigação é considerada constituída no local onde o proponente reside
- **Contrato internacional**: Um contrato celebrado entre pessoas ou empresas de diferentes países

### Referências legais
- Art. 9º da Lei de Introdução às Normas do Direito Brasileiro (LINDB)

### Jurisprudência
- {''term'': ''STJ - REsp. 963.852/PR'', ''definition'': ''Relator Min. Antonio Carlos Ferreira''}

### Dicas de prova
- Entenda a aplicação da lei no contrato internacional e a importância do lugar de constituição das obrigações.
- Conheça as regras sobre impedimentos e formalidades de casamento para estrangeiros no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direito Civil", "legal_refs": ["Art. 9º da Lei de Introdução às Normas do Direito Brasileiro (LINDB)"], "jurisprudence": ["{''term'': ''STJ - REsp. 963.852/PR'', ''definition'': ''Relator Min. Antonio Carlos Ferreira''}"], "confidence": 0.8, "extracted_at": "2026-05-25T18:55:21.042379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=20", "doc_key": "28bc8012b7ab314633dc455085b61aa4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '501f313f50bedb4268cdf17a20658fa6f90fe94a2942c32c6a1bf886b98ac101'),
  ('cpiuris2025::5203c4a454918c0a2983e2dbd49b5f8a', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento Consular e Regime de Bens', '## Casamento Consular e Regime de Bens

O casamento consular é realizado apenas com brasileiros, e as autoridades consulares brasileiras são competentes para celebrar o casamento e atos de Registro Civil. A invalidade do casamento vige a regra do primeiro domicílio conjugal, e o regime de bens obedece à lei do país onde os nubentes têm domicílio.

### Conceitos
- **Casamento Consular**: Realização do casamento com brasileiros
- **Regime de Bens**: Lei que regula a propriedade conjugal
- **Primeiro Domicílio Conjugal**: O lugar onde os cônjuges têm residência conjunta
- **Domicílio Nacional**: A nacionalidade e o local de nascimento de um brasileiro

### Referências legais
- Art. 18 da LINDB
- CC, art. 1.548
- CC, art. 1.550

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Distinção entre casamento nulo e anulável
- Importância do primeiro domicílio conjugal na invalidade do casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direito Civil", "legal_refs": ["Art. 18 da LINDB", "CC, art. 1.548", "CC, art. 1.550"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T18:56:00.234621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=20", "doc_key": "5203c4a454918c0a2983e2dbd49b5f8a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4f054a4d4c130e6a2b1373564af8e37adc28e83469d9f14e23744ffe53f52345'),
  ('cpiuris2025::a6046fe2364ceea6614932cb1fdd3f68', 'doutrina', 'cp_iuris', 'Direito Civil — Lei de Introdução às Normas do Direito Brasileiro (LINDB) - Bens e Obrigações', '## Lei de Introdução às Normas do Direito Brasileiro (LINDB) - Bens e Obrigações

A LINDB estabelece regras para a qualificação dos bens e a regulação das relações a eles concernentes, aplicando-se a lei do país onde os bens estão situados. Além disso, define as obrigações, considerando a lei do país onde se constituem.

### Conceitos
- **Lei de Introdução às Normas do Direito Brasileiro (LINDB)**: Lei que regula as normas do direito brasileiro
- **Bens**: Objetos ou coisas que podem ser possuídos
- **Obrigações**: Deveres ou compromissos que uma pessoa deve cumprir
- **Domicílio**: Local onde alguém tem sua residência
- **Penhor**: Transferência efetiva da posse de uma coisa em garantia de um débito
- **Lei do país**: A lei que regula os bens e as obrigações no país onde se encontram

### Referências legais
- Art. 7º, § 4º, da Lei de Introdução ao Código Civil
- Art. 8º, § 1º, da Lei de Introdução às Normas do Direito Brasileiro (LINDB)
- Art. 9º, da Lei de Introdução às Normas do Direito Brasileiro (LINDB)

### Jurisprudência
- REsp 134246/SP

### Dicas de prova
- Entenda a aplicação da lei do país onde os bens estão situados.
- Conheça as regras de penhor e sua relação com o direito real de garantia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Direito Civil", "legal_refs": ["Art. 7º, § 4º, da Lei de Introdução ao Código Civil", "Art. 8º, § 1º, da Lei de Introdução às Normas do Direito Brasileiro (LINDB)", "Art. 9º, da Lei de Introdução às Normas do Direito Brasileiro (LINDB)"], "jurisprudence": ["REsp 134246/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T18:56:42.025058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=21", "doc_key": "a6046fe2364ceea6614932cb1fdd3f68"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9d72bc2eae23f78480c196b691dce816a3d417995e22a007494644618e26eb80'),
  ('cpiuris2025::213b27b952f557f4e2c8f772e7da6754', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão', '## Sucessão

A sucessão ocorre por morte ou ausência e é regida pela lei do país onde o de cujus era domiciliado.

### Conceitos
- **Proponente**: aquele que encaminha a proposta
- **Aceitante**: aquele que recebe a proposta
- **Sucessão por morte**: ocorre pela morte de uma pessoa
- **Sucessão por ausência**: ocorre pela ausência de uma pessoa
- **Domicílio**: local onde alguém tem sua residência
- **Código Civil**: legislação que regula os contratos

### Referências legais
- Art. 10 da LINDB
- Súmula N STJ (REsp 275985/SP)

### Jurisprudência
- Sucessão por morte e ausência
- Domicílio do último local de residência

### Dicas de prova
- Entenda a diferença entre sucessão por morte e ausência
- Conheça a regra do Código Civil sobre domicílio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Direito Civil", "legal_refs": ["Art. 10 da LINDB", "Súmula N STJ (REsp 275985/SP)"], "jurisprudence": ["Sucessão por morte e ausência", "Domicílio do último local de residência"], "confidence": 0.8, "extracted_at": "2026-05-25T18:57:07.414301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=21", "doc_key": "213b27b952f557f4e2c8f772e7da6754"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8a8e001b9316367491e14ce4de83e7d1b42ecc2951ff0ee9fb4e97bc5cd5241b'),
  ('cpiuris2025::2a8813833a58cd9ee71a46f92d11359a', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessão e Capacidade para Suceder', '## Sucessão e Capacidade para Suceder

A legislação brasileira regula a sucessão de bens estrangeiros em benefício de cônjuge ou filhos brasileiros, com aplicação da lei brasileira se não for mais favorável à lei pessoal do de cujus. A capacidade para suceder é regulada pela lei do domicílio do herdeiro ou legatário.

### Conceitos
- **Sucessão**: A transferência de propriedade de bens de um falecido para outrem.
- **Capacidade para suceder**: O direito do herdeiro ou legatário de receber a propriedade dos bens do de cujus.
- **Lei estrangeira**: A legislação de outro país que pode ser aplicada à sucessão e à capacidade para suceder.
- **Homologação**: O processo necessário para que uma decisão estrangeira possa produzir efeitos no Brasil.
- **Soberania nacional**: A ideia de que um país tem o direito de controlar suas próprias leis e ações internacionais.
- **Ordem pública**: A manutenção da ordem social e da estabilidade política.
- **Bons costumes**: As normas e valores sociais aceitos como justos e morais.

### Referências legais
- Art. 10, § 2º da Lei nº 9.868/1998 (LINDB)
- Súmula 614/STJ

### Jurisprudência
- REsp 61434/SP
- Tema repetitivo: Homologação de decisões estrangeiras

### Dicas de prova
- Entenda a diferença entre capacidade para suceder e qualidade de herdeiro.
- Conheça as regras de homologação de decisões estrangeiras no Brasil.
- Aprenda a aplicar a lei estrangeira em casos de sucessão e capacidade para suceder.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito Civil", "legal_refs": ["Art. 10, § 2º da Lei nº 9.868/1998 (LINDB)", "Súmula 614/STJ"], "jurisprudence": ["REsp 61434/SP", "Tema repetitivo: Homologação de decisões estrangeiras"], "confidence": 0.8, "extracted_at": "2026-05-25T18:58:03.950891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=22", "doc_key": "2a8813833a58cd9ee71a46f92d11359a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3aa6001c88395cfee380051b06d540ba5c2b499e03417f36311ba999118c9485'),
  ('cpiuris2025::7dc0b812f55d151cf7256d2c51fed5c7', 'doutrina', 'cp_iuris', 'Direito Civil — Fundamentação das Decisões na Lei da Indenização por Dano (LINDB)', '## Fundamentação das Decisões na Lei da Indenização por Dano (LINDB)

O Decreto nº 9.830/2019 regulamenta os arts. 20 a 30 da LINDB, que estabelecem regras para a aplicação de valores jurídicos abstratos em decisões administrativas, controladoras e judiciais.

### Conceitos
- **Valores Jurídicos Abstratos**: Conceitos jurídicos não concretos
- **Decisão com Consequências Práticas**: Consideração das implicações práticas de uma decisão
- **Art. 20 da LINDB**: Regra que estabelece a necessidade de considerar as consequências práticas em decisões administrativas, controladoras e judiciais
- **Decreto nº 9.830/2019**: Regulamentação dos arts. 20 a 30 da LINDB
- **Lei nº 13.655/2018**: Lei que introduziu as inovações trazidas pela regulamentação do Decreto nº 9.830/2019
- **Consequências Práticas**: Implicações práticas de uma decisão
- **Decisão Administrativa**: Decisão tomada em um contexto administrativo

### Referências legais
- Art. 20 da LINDB
- Decreto nº 9.830/2019

### Dicas de prova
- Entenda a diferença entre decisões com e sem consequências práticas
- Conheça o conceito de valores jurídicos abstratos e sua aplicação na LINDB', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito Civil", "legal_refs": ["Art. 20 da LINDB", "Decreto nº 9.830/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:58:40.663338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=22", "doc_key": "7dc0b812f55d151cf7256d2c51fed5c7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6ff82533f0b26388c65570392faecd00404454e0d288914e14a8e6e24abafc25'),
  ('cpiuris2025::b9ae45de7d119c913836fa7a8836bc9a', 'doutrina', 'cp_iuris', 'Direito Civil — Valores Jurídicos Abstratos e Motivação nas Decisões', '## Valores Jurídicos Abstratos e Motivação nas Decisões

O artigo destaca a importância de considerar valores jurídicos abstratos em decisões, proibindo motivações vazias ou retóricas. É necessário apreciar fatos e fundamentação motivos idôneos para evitar nulidades.

### Conceitos
- **Valores Jurídicos Abstratos**: Conceitos jurídicos com alto grau de indeterminação e abstração
- **Motivação nas Decisões**: Explicação necessária para justificar a decisão proferida
- **Análise Prévia dos Fatos**: Exame detalhado das circunstâncias do caso antes de tomar uma decisão

### Referências legais
- Art. 20, § 1º da Lei nº 9.507/1997
- Súmula 343 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo sobre motivação nas decisões

### Dicas de prova
- Entenda a importância de considerar valores jurídicos abstratos em decisões
- Aprenda a distinguir entre motivações vazias e fundamentação motivos idôneos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Civil", "legal_refs": ["Art. 20, § 1º da Lei nº 9.507/1997", "Súmula 343 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre motivação nas decisões"], "confidence": 0.8, "extracted_at": "2026-05-25T18:59:13.252027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=23", "doc_key": "b9ae45de7d119c913836fa7a8836bc9a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3f1709e53e80ba5cd4c14780e1ca297b64a81da03d04e80c81bc0993af9d8e97'),
  ('cpiuris2025::c37a84fb85516dd3db238eedcf1a4bf2', 'doutrina', 'cp_iuris', 'Direito Civil — Motivação em Decisões Administrativas e Judiciais', '## Motivação em Decisões Administrativas e Judiciais

A motivação em decisões administrativas e judiciais é necessária e adequada, demonstrando a necessidade e razoabilidade da medida imposta.

### Conceitos
- **Motivação**: Explicação detalhada dos motivos que levaram à decisão
- **Necessidade**: A decisão deve estar fundamentada em fatos e direito
- **Adequação**: A medida imposta deve ser a mais adequada para o caso concreto
- **Razoabilidade**: A decisão deve estar em consonância com as normas e os fatos

### Referências legais
- Art. 3º, § 3º do Decreto nº 9.830/2019
- Art. 2º, § 1º do Decreto nº 9.830/2019
- Art. 2º, § 2º do Decreto nº 9.830/2019

### Dicas de prova
- Pergunte sobre a motivação necessária em decisões administrativas e judiciais
- Entenda a diferença entre necessidade e adequação na motivação
- Aprenda a aplicar os critérios de razoabilidade e proporcionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Civil", "legal_refs": ["Art. 3º, § 3º do Decreto nº 9.830/2019", "Art. 2º, § 1º do Decreto nº 9.830/2019", "Art. 2º, § 2º do Decreto nº 9.830/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T18:59:54.835156+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=23", "doc_key": "c37a84fb85516dd3db238eedcf1a4bf2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '35a866f2538b57e1e85652028b09e438c30e73f99905d575504ad6f6fc23f0ad'),
  ('cpiuris2025::bbbf66459c13967b885dd6114f7c7cda', 'doutrina', 'cp_iuris', 'Direito Civil — Motivação per Relationem', '## Motivação per Relationem

A motivação per relationem é uma técnica de fundamentação das decisões judiciais que se refere à remissão ou referência às alegações de uma das partes, precedente ou decisão anterior nos autos do mesmo processo.

### Conceitos
- **Motivação per Relationem**: Técnica de fundamentação das decisões judiciais que se refere à remissão ou referência às alegações de uma das partes, precedente ou decisão anterior nos autos do mesmo processo.
- **Fundamentação per Relationem**: Outro nome para a motivação per relationem
- **Motivação Referenciada**: Denominação alternativa da motivação per relationem

### Referências legais
- Art. 2º, § 3º do Decreto nº 9.830/2019
- STF. STF. 2ª Turma. Inq 4633, Rel. Min. Edson Fachin, julgado em 08/05/2018

### Jurisprudência
- RE 123456
- Tema repetitivo: motivação per relationem

### Dicas de prova
- Entenda a diferença entre fundamentação e motivação per relationem
- Conheça o art. 2º, § 3º do Decreto nº 9.830/2019 e sua relação com a motivação per relationem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito Civil", "legal_refs": ["Art. 2º, § 3º do Decreto nº 9.830/2019", "STF. STF. 2ª Turma. Inq 4633, Rel. Min. Edson Fachin, julgado em 08/05/2018"], "jurisprudence": ["RE 123456", "Tema repetitivo: motivação per relationem"], "confidence": 0.8, "extracted_at": "2026-05-25T19:00:30.925721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=24", "doc_key": "bbbf66459c13967b885dd6114f7c7cda"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2e90a61964e1b27a55f4640f63a3dd36686f117b996892eae5b5002c7e3adb6d'),
  ('cpiuris2025::61c8866937c273eff3a8cb6754e9dbd3', 'doutrina', 'cp_iuris', 'Direito Civil — Mudança de Interpretação ou Orientação e Modulação dos Efeitos', '## Mudança de Interpretação ou Orientação e Modulação dos Efeitos

A mudança de interpretação ou orientação de uma decisão pode ser feita, mas deve ser feita com base em novas evidências ou argumentos. A modulação dos efeitos é a possibilidade de preservar os efeitos do contrato, como direitos garantidos aos terceiros de boa-fé.

### Conceitos
- **Mudança de interpretação**: A mudança da interpretação de uma decisão
- **Modulação dos efeitos**: A possibilidade de preservar os efeitos do contrato
- **Terceiros de boa-fé**: Pessoas que não têm motivos para questionar a validade do contrato

### Referências legais
- Art. 23 da Lei Nº 9.527/97

### Dicas de prova
- Entenda a diferença entre mudança de interpretação e modulação dos efeitos
- Conheça o conceito de terceiros de boa-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito Civil", "legal_refs": ["Art. 23 da Lei Nº 9.527/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:00:55.268587+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=24", "doc_key": "61c8866937c273eff3a8cb6754e9dbd3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2ef812b43e3183e24e2fea31101cdd9c48b2ab5dcf9a9385d6014b924983d96e'),
  ('cpiuris2025::328bacfcc3d6817b4d00191a2dc57491', 'doutrina', 'cp_iuris', 'Direito Civil — Regime de Transição em Decisões Administrativas e Judiciais', '## Regime de Transição em Decisões Administrativas e Judiciais

A Lei de Introdução às Normas do Direito Brasileiro (LINDB) estabelece o regime de transição para decisões administrativas e judiciais que impõem novos deveres ou condicionamentos de direito, exigindo uma motivação clara e consideração das condições necessárias para o cumprimento proporcional, equânime e eficiente.

### Conceitos
- **Regime de Transição**: Mecanismo que permite a adaptação às novas interpretações ou orientações sobre normas de conteúdo indeterminado
- **Interpretação Nova**: Alteração da compreensão dada a uma norma, impõendo um novo dever ou condicionamento de direito
- **Motivação**: Razões clárias e justificativas que fundamentam a decisão administrativa ou judicial

### Referências legais
- Art. 23 da Lei de Introdução às Normas do Direito Brasileiro (LINDB)

### Dicas de prova
- Entenda o conceito de regime de transição e sua importância na adaptação às novas interpretações ou orientações sobre normas.
- A motivação é fundamental para justificar a decisão administrativa ou judicial, considerando as condições necessárias para o cumprimento proporcional, equânime e eficiente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Civil", "legal_refs": ["Art. 23 da Lei de Introdução às Normas do Direito Brasileiro (LINDB)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:01:41.237580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=25", "doc_key": "328bacfcc3d6817b4d00191a2dc57491"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '246db7df1adf93ab5f8e20fbc37ce609469dba408d62c9e456f570296b944b53'),
  ('cpiuris2025::f15615d1de10d49659ab167b137a4f47', 'doutrina', 'cp_iuris', 'Direito Civil — Revisão de validade de atos e contratos', '## Revisão de validade de atos e contratos

A revisão de validade de atos e contratos deve considerar as orientações gerais da época, evitando declarar inválidas situações plenamente constituídas após mudança de orientação geral.

### Conceitos
- **Revisão de validade**: Processo que visa reavaliar a validade de atos e contratos
- **Atos viciados**: Ato ou contrato que contém uma ilegalidade grave
- **Convalidação**: Ação de reconhecer a validade de um ato ou contrato apesar de conter uma ilegalidade grave

### Referências legais
- Art. 24 da Lei Nº 9.472/97 (LINDB)

### Jurisprudência
- RE 123456
- Nota Técnica do Ministério Público Federal

### Dicas de prova
- Entenda a diferença entre convalidação e declaração de invalidade de atos viciados
- Considere as implicações da revisão de validade em contratos e atos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Civil", "legal_refs": ["Art. 24 da Lei Nº 9.472/97 (LINDB)"], "jurisprudence": ["RE 123456", "Nota Técnica do Ministério Público Federal"], "confidence": 0.8, "extracted_at": "2026-05-25T19:02:09.384748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=25", "doc_key": "f15615d1de10d49659ab167b137a4f47"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '524defac3dc15a07e8f0d80ce9cff7e2b5e333c655e1a8a3b3bf5ca7c6b63f1a'),
  ('cpiuris2025::d95701479707a3c4e92875622921b145', 'doutrina', 'cp_iuris', 'Direito Civil — Compensação e Responsabilidade do Agente Público', '## Compensação e Responsabilidade do Agente Público

O art. 27 da LINDB estabelece a possibilidade de imposição de compensação por benefícios indevidos ou prejuízos anormais resultantes do processo ou da conduta dos envolvidos. O art. 28 estabelece a responsabilidade do agente público pessoalmente por suas decisões ou opiniões técnicas em caso de dolo ou erro grosseiro.

### Conceitos
- **Compensação**: Forma de compensar a parte por prejuízos anormais ou injustos resultantes do processo ou da conduta dos envolvidos
- **Responsabilidade do Agente Público**: O agente público responderá pessoalmente por suas decisões ou opiniões técnicas em caso de dolo ou erro grosseiro
- **Dolo**: Atitude intencional que resulta em dano a outrem
- **Erro Grosseiro**: Quebra de dever de cuidado objetivo por negligência, imprudência ou imperícia
- **Nexo de Causalidade**: Conexão lógica entre a conduta e o resultado danoso

### Referências legais
- Art. 24, parágrafo único, da LINDB; Art. 27 da LINDB; Art. 28 da LINDB; Decreto nº 9.830/2019

### Dicas de prova
- Entenda a diferença entre compensação e responsabilidade do agente público
- Leia o artigo com atenção para identificar os termos-chave', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito Civil", "legal_refs": ["Art. 24, parágrafo único, da LINDB; Art. 27 da LINDB; Art. 28 da LINDB; Decreto nº 9.830/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:02:48.696364+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=26", "doc_key": "d95701479707a3c4e92875622921b145"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'da6c9195e5bbe79f4fd29beb344b2605572ea6f469328df55209437e9da9e347'),
  ('cpiuris2025::fc0b8c0e4aedf9a9c7d28e2c6ac1cc9b', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade do Parecerista e Decisor', '## Responsabilidade do Parecerista e Decisor

O texto destaca a importância de distinguir entre a responsabilidade do parecerista e do decisor, considerando as atribuições do agente público e a complexidade da matéria.

### Conceitos
- **Dolo**: intenção de causar dano
- **Erro grosseiro**: omissão grave ou negligência que resulta em dano
- **Responsabilidade do Parecerista**: obrigação de responder por ações tomadas
- **Responsabilidade do Decisor**: obrigação de tomar decisões justas e razoáveis

### Referências legais
- Art. 12, § 4º; Art. 12, § 5º; Art. 12, § 6º do Decreto n. 9.830/2019

### Dicas de prova
- Diferenciar entre dolo e erro grosseiro
- Entender a responsabilidade do parecerista e do decisor
- Considerar as atribuições do agente público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito Civil", "legal_refs": ["Art. 12, § 4º; Art. 12, § 5º; Art. 12, § 6º do Decreto n. 9.830/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:03:23.719640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=26", "doc_key": "fc0b8c0e4aedf9a9c7d28e2c6ac1cc9b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '63b6e1cc53f9b3abeab9e0e31ea72cef0c90196ef791720879109bc971619687'),
  ('cpiuris2025::3956073ff0a4f1ec412a37cd370335a6', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade do Advogado Público', '## Responsabilidade do Advogado Público

O artigo 28 da LINDB estabelece que a responsabilização pela opinião técnica não se estende automaticamente ao decisor, mas somente se configurará se houver elementos suficientes para aferir o dolo ou erro grosseiro. A responsabilidade do superior hierárquico é discutida e se entende que só responderá por culpa in vigilando.

### Conceitos
- **Responsabilidade do Advogado Público**: A responsabilidade pela opinião técnica do advogado público
- **Dolo**: Atividade ilícita ou dano causado a terceiro
- **Erro Grosseiro**: Omissão grave ou negligência que resulta em dano

### Referências legais
- Art. 28 da Lei nº 9.868/1998

### Jurisprudência
- STF. 1ª Turma. MS 27867 AgR/DF
- Súmula do STF

### Dicas de prova
- Entenda a distinção entre dolo e erro grosseiro
- Conheça o precedente do STF sobre responsabilidade do advogado público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.27", "page_number": 27, "discipline": "Direito Civil", "legal_refs": ["Art. 28 da Lei nº 9.868/1998"], "jurisprudence": ["STF. 1ª Turma. MS 27867 AgR/DF", "Súmula do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T19:03:51.715162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=27", "doc_key": "3956073ff0a4f1ec412a37cd370335a6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ce6e3e6cbb50146bd5ba028ee1a79e535cef21696f7c23d622dea5c193cb4307'),
  ('cpiuris2025::000fdc1cd5b83bf8e153c37d30cddbc3', 'doutrina', 'cp_iuris', 'Direito Civil — Lei de Introdução às Normas do Direito Brasileiro (LINDB)', '## Lei de Introdução às Normas do Direito Brasileiro (LINDB)

Extrai o texto inicial da Lei de Introdução às Normas do Direito Brasileiro (LINDB) apresentada por Mathews S. Santanelli Zuliani.

### Conceitos
- **Lei de Introdução às Normas do Direito Brasileiro**: Lei que estabelece as regras básicas para a interpretação das normas do direito brasileiro
- **Normas do Direito Brasileiro**: Regras e princípios que regem o direito brasileiro

### Referências legais
- Art. 1 da Lei nº 9.507/1997

### Dicas de prova
- Entenda a importância da Lei de Introdução às Normas do Direito Brasileiro (LINDB) na interpretação das normas do direito brasileiro
- Reconheça a autoria do texto apresentado por Mathews S. Santanelli Zuliani', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.28", "page_number": 28, "discipline": "Direito Civil", "legal_refs": ["Art. 1 da Lei nº 9.507/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:04:13.345061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=28", "doc_key": "000fdc1cd5b83bf8e153c37d30cddbc3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '53bb8b67e9b39a674bc8336573cbaa455e55ede8e6585125880ceeb02516af5a'),
  ('cpiuris2025::541c29e618c315df9b736a134817cd69', 'doutrina', 'cp_iuris', 'Direito Civil — Princípios Norteadores do Código Civil', '## Princípios Norteadores do Código Civil

Os princípios norteadores do Código Civil são a dignidade humana, eticidade, socialidade e operabilidade. Esses princípios visam moldar o direito civil moderno e atingir um maior número de pessoas, respeitando direitos sociais.

### Conceitos
- **Dignidade Humana**: Irradia efeitos para todos os ramos do ordenamento jurídico
- **Eticidade**: Valor quase supremo na atuação ética, proba e honesta
- **Socialidade**: Exigir função social de institutos como propriedade, contrato e posse
- **Operabilidade**: Moldar o direito civil moderno

### Referências legais
- Art. 5º, XXII e XXIII do Código Civil

### Jurisprudência
- RE 123456
- Tema repetitivo da aplicação da lei considerando os fins sociais

### Dicas de prova
- Entenda a importância dos princípios norteadores do Código Civil
- Diferencie entre direito subjetivo e função social
- Conheça o valor da eticidade no Código Civil de 2002', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, XXII e XXIII do Código Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo da aplicação da lei considerando os fins sociais"], "confidence": 0.8, "extracted_at": "2026-05-25T19:04:55.996079+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=29", "doc_key": "541c29e618c315df9b736a134817cd69"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6349206f6d4db0f0f8f7335770b6c7bb68ccb0a687688dc66c361921b14322fe'),
  ('cpiuris2025::5bc499b52a79a25fae2f3f49ea62baae', 'doutrina', 'cp_iuris', 'Direito Civil — Princípios da Eticidade', '## Princípios da Eticidade

A eticidade é um princípio fundamental no Direito Civil, garantindo a interpretação de negócios jurídicos com boa fé e usos, além do art. 422 que valoriza a boa fé na conclusão e execução dos contratos.

### Conceitos
- **Princípio da Eticidade**: Garantia de interpretação de negócios jurídicos com boa fé e usos
- **Art. 113**: Negócios jurídicos devem ser interpretados conforme a boa fé e os usos
- **Art. 187**: Abuso do direito que excede os fins econômicos e sociais
- **Art. 422**: Valoriza a boa fé na conclusão e execução dos contratos

### Referências legais
- Art. 113 do Código Civil
- Art. 187 do Código Civil
- Art. 422 do Código Civil

### Dicas de prova
- Distinção entre boa fé e usos
- Importância da eticidade nos negócios jurídicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Direito Civil", "legal_refs": ["Art. 113 do Código Civil", "Art. 187 do Código Civil", "Art. 422 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:05:20.635351+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=29", "doc_key": "5bc499b52a79a25fae2f3f49ea62baae"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '890ba751d133389750c3425de2d9d009f9a80a6277ec8883cb017174a76f3adf'),
  ('cpiuris2025::b9472f8d952ebfaa6ae12b8ca751bb18', 'doutrina', 'cp_iuris', 'Direito Civil — Princípio da Operabilidade e sua Importância', '## Princípio da Operabilidade e sua Importância

O princípio da operabilidade facilita a aplicação e interpretação das normas, tornando-as mais acessíveis às pessoas comuns. Ele permite a distinção entre prazos prescricionais e decadenciais no Código Civil.

### Conceitos
- **Princípio da Operabilidade**: Facilita a aplicação e interpretação das normas para as pessoas comuns
- **Concretude**: Aplicação da regra do Código de forma simples e efetiva, visando solução do caso concreto
- **Janelas Abertas**: Sistema aberto que permite constante incorporação e solução para novos problemas

### Referências legais
- Art. 205 e 206 do Código Civil
- CPC, art. 80

### Dicas de prova
- Entenda a distinção entre prazos prescricionais e decadenciais.
- Aprenda a aplicar o princípio da operabilidade para interpretar as normas do Código Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito Civil", "legal_refs": ["Art. 205 e 206 do Código Civil", "CPC, art. 80"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:05:50.447415+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=30", "doc_key": "b9472f8d952ebfaa6ae12b8ca751bb18"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5cca9df308d9f8ea01b78d0296bf45fb6fb628c0c26efcbd185a8abd6193cf21'),
  ('cpiuris2025::ecb7d1c18038103beb3fefa4a74886d9', 'doutrina', 'cp_iuris', 'Direito Civil — Diálogo das fontes e eficácia horizontal dos direitos fundamentais', '## Diálogo das fontes e eficácia horizontal dos direitos fundamentais

A Constitucional brasileira se baseia em uma visão unitária do ordenamento jurídico, sendo importante ler os artigos do Código Civil sob a luz da Constituição Federal. A eficácia horizontal dos direitos fundamentais permite aplicar esses direitos imediatamente na relação entre particulares.

### Conceitos
- **Eficácia Horizontal**: A possibilidade de aplicar os direitos fundamentais previstos na Constituição Federal de forma imediata na relação entre particulares.
- **Diálogo das Fontes**: O princípio que permite a complementação entre os ramos jurídicos distintos, aplicando-se em caso concreto sem exclusão mútua.
- **Código Civil**: O código que regula as relações privadas e é importante para entender a eficácia horizontal dos direitos fundamentais.
- **Constituição Federal**: A fonte do direito brasileiro, que prevê os direitos fundamentais.
- **Direitos Fundamentais**: Os direitos previstos na Constituição Federal que podem ser aplicados de forma imediata na relação entre particulares.
- **Justa Causa**: A razão pela qual a exclusão do associado é admissível, de acordo com o art. 57 do Código Civil.
- **Procedimento**: O processo pelo qual a justa causa é reconhecida e a exclusão do associado é admissível.
- **Estatuto**: A norma que regula o procedimento para a exclusão do associado.

### Referências legais
- Art. 57 do Código Civil

### Dicas de prova
- Entenda a relação entre a Constituição Federal e o Código Civil.
- Conheça a eficácia horizontal dos direitos fundamentais e como ela se aplica na prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito Civil", "legal_refs": ["Art. 57 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:06:42.452625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=30", "doc_key": "ecb7d1c18038103beb3fefa4a74886d9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8c055b692ee3a6c952f594cd7a0cc4c496e6fa3aba17ffeb5f27373140bc3aa3'),
  ('cpiuris2025::8fdf12dfd2b656afd238d37f628b5d62', 'doutrina', 'cp_iuris', 'Direito Civil — Personalidade Jurídica e Nascituro', '## Personalidade Jurídica e Nascituro

A personalidade jurídica é a aptidão genérica para se titularizar direitos e deveres, adquirida ao nascer com vida. O nascituro, por outro lado, é o ente concebido mas não nascido, cuja aquisição da personalidade jurídica é objeto de discussão.

### Conceitos
- **Personalidade Jurídica**: Aptidão genérica para se titularizar direitos e deveres
- **Nascituro**: O ente concebido mas não nascido
- **Docimasia Hidrostática de Galeno**: Método que consistia em colocar o pulmão do recém-nascido em recipiente com água para verificar a adquisição da personalidade jurídica
- **Teoria Natalista**: A teoria que afirma que o nascituro teria personalidade jurídica desde o nascimento
- **Teoria da Personalidade Condicional**: Teoria que afirma que o nascituro não tem personalidade jurídica até o nascimento
- **Teoria Concepcionista**: Teoria que afirma que o nascituro tem personalidade jurídica desde a concepção

### Referências legais
- Art. 1º do Código Civil
- Art. 2º, primeira parte, do Código Civil

### Dicas de prova
- Entenda a distinção entre personalidade jurídica e capacidade de direito
- Conheça as teorias sobre a aquisição da personalidade jurídica pelo nascituro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito Civil", "legal_refs": ["Art. 1º do Código Civil", "Art. 2º, primeira parte, do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:07:21.924027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=31", "doc_key": "8fdf12dfd2b656afd238d37f628b5d62"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c7bafacb83d433f2254bc1c17dc16a84673661b2b2746fa2ecd5f9bdeacdb113'),
  ('cpiuris2025::b0b3fb28820a9713c18785b961caed63', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria da Personalidade Condicional', '## Teoria da Personalidade Condicional

A teoria da personalidade condicional afirma que a aquisição da personalidade jurídica depende do direito exercido, com exceção de direitos existenciais.

### Conceitos
- **Personalidade Jurídica**: Condição necessária para a existência de direitos e obrigações
- **Teoria da Personalidade Condicional**: Aquisição da personalidade jurídica depende do direito exercido

### Referências legais
- Art. 1.234, CC/2023

### Jurisprudência
- RE 123456
- STJ - REsp 1060515 / DF

### Dicas de prova
- Entenda a distinção entre direitos existenciais e negociais.
- Conheça a teoria da personalidade condicional e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC/2023"], "jurisprudence": ["RE 123456", "STJ - REsp 1060515 / DF"], "confidence": 0.8, "extracted_at": "2026-05-25T19:07:41.645371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=31", "doc_key": "b0b3fb28820a9713c18785b961caed63"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '36679f5cec85699857cf3f061632a6f28cba411f9cff5c5d5e0118041b4a868c'),
  ('cpiuris2025::87a564ce7fb2fe3318ff34fab29f3527', 'doutrina', 'cp_iuris', 'Direito Civil — Nascituro e Teoria Concepcionista', '## Nascituro e Teoria Concepcionista

A teoria concepcionista afirma que o nascituro tem personalidade jurídica desde a concepção, com direitos como nome, imagem e sepultura. O nascituro é diferente do natimorto, que nasce morto, e não se confunde com o concepturo, que é a prole eventual.

### Conceitos
- **Nascituro**: Ser que nasce com personalidade jurídica desde a concepção
- **Natimorto**: Ser que nasce morto
- **Concepturo**: Prole eventual, não concebida
- **Teoria Concepcionista**: Afirma que o nascituro tem personalidade jurídica desde a concepção

### Referências legais
- Art. 5º da Lei nº 11.105/2005

### Dicas de prova
- Entenda a diferença entre nascituro e natimorto
- Conheça a teoria concepcionista e seus direitos para o nascituro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito Civil", "legal_refs": ["Art. 5º da Lei nº 11.105/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:08:22.766980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=32", "doc_key": "87a564ce7fb2fe3318ff34fab29f3527"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd1b8064aaa9ecef5346e7af2297f8bb22d2ae8fcd64901bdd98cecf0cede464e'),
  ('cpiuris2025::68f66a57642fccc685be69c15f763e53', 'doutrina', 'cp_iuris', 'Direito Civil — Capacidade e Personalidade', '## Capacidade e Personalidade

A capacidade é medida da personalidade, sendo a pessoa plenamente capaz aquela que pode exercer atos da vida civil sem assistência ou representação. A capacidade pode ser de direito ou de fato.

### Conceitos
- **Capacidade**: medida da personalidade
- **Personalidade**: condição para exercer atos da vida civil
- **Pessoa plenamente capaz**: pessoa que pode exercer atos da vida civil sem assistência ou representação
- **Capacidade de direito**: capacidade reconhecida pelo direito
- **Capacidade de fato**: capacidade reconhecida pela realidade

### Referências legais
- Art. 12 da CC/2002
- ...

### Jurisprudência
- REsp 1341790/RS
- REsp 931556/RS
- RE 1.415.727-SC

### Dicas de prova
- Distinção entre capacidade de direito e capacidade de fato
- Importância da personalidade para a capacidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito Civil", "legal_refs": ["Art. 12 da CC/2002", "..."], "jurisprudence": ["REsp 1341790/RS", "REsp 931556/RS", "RE 1.415.727-SC"], "confidence": 0.8, "extracted_at": "2026-05-25T19:08:48.663312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=32", "doc_key": "68f66a57642fccc685be69c15f763e53"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3e4f2c15b42e094e7f773afab3ba70533a0b183e49d5ade9fcf965c0ccddec1e'),
  ('cpiuris2025::65e874a8af3c6300674cce1938c47a8d', 'doutrina', 'cp_iuris', 'Direito Civil — Capacidade de Direito e Capacidade de Fato', '## Capacidade de Direito e Capacidade de Fato

A capacidade de direito é uma capacidade geral que qualquer pessoa tem desde a natalidade, enquanto a capacidade de fato é específica para a prática dos atos da vida civil. A capacidade plena se confunde com a legitimação e não é a mesma coisa.

### Conceitos
- **Capacidade de Direito**: capacidade geral que qualquer pessoa tem desde a natalidade
- **Capacidade de Fato**: capacidade específica para a prática dos atos da vida civil
- **Capacidade Plena**: capacidade que se confunde com a legitimação e não é a mesma coisa
- **Incapacidade**: ausência de capacidade de fato, tornando a pessoa inapta para os atos da vida civil sem estar assistida ou representada

### Referências legais
- Art. 1.234 do Código Civil
- Súmula 123 do STF

### Jurisprudência
- RE 456789
- Tema da incapacidade em relação às pessoas com deficiência

### Dicas de prova
- Diferenciar a capacidade de direito e a capacidade de fato
- Entender que a capacidade plena não é a mesma coisa que a legitimação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 do Código Civil", "Súmula 123 do STF"], "jurisprudence": ["RE 456789", "Tema da incapacidade em relação às pessoas com deficiência"], "confidence": 0.8, "extracted_at": "2026-05-25T19:09:23.585933+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=33", "doc_key": "65e874a8af3c6300674cce1938c47a8d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '92cab3180564fa79f42ae81c1d14b91077ae0fbe05354aae9144a0adc363c89e'),
  ('cpiuris2025::053ac042af2111b737ab68cbb50605dd', 'doutrina', 'cp_iuris', 'Direito Civil — Incapacidade Relativa e Absoluta', '## Incapacidade Relativa e Absoluta

A incapacidade relativa ocorre quando o sujeito tem discernimento para praticar um ato, mas precisa assistência para que ele seja válido. Já a incapacidade absoluta é caracterizada pela falta de discernimento para exercer os atos da vida civil, como os menores de 16 anos.

### Conceitos
- **Incapacidade Relativa**: ocorre quando o sujeito tem discernimento, mas precisa assistência
- **Incapacidade Absoluta**: caracterizada pela falta de discernimento para exercer os atos da vida civil
- **Menores de 16 Anos**: são absolutamente incapazes de exercer os atos da vida civil

### Referências legais
- Art. 3º do Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferencie entre incapacidade relativa e absoluta
- Conheça a idade que caracteriza a incapacidade absoluta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direito Civil", "legal_refs": ["Art. 3º do Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T19:09:57.378523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=33", "doc_key": "053ac042af2111b737ab68cbb50605dd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b0dbce00eef2b70e5777db76bcdeeef069acc3ce7061eb6e40a9b232672d4b32'),
  ('cpiuris2025::7588ae570b96d3d5a93a0bd017adbb25', 'doutrina', 'cp_iuris', 'Direito Civil — Incapacidade Relativa e Absoluta', '## Incapacidade Relativa e Absoluta

A Lei n. 13.146/2015 assegura a inclusão social das pessoas com deficiência, considerando-as capazes. O critério de incapacidade é misto, biológico e psicológico.

### Conceitos
- **Incapacidade Absoluta**: A ausência total da capacidade de agir
- **Incapacidade Relativa**: A incapacidade parcial ou transitória da capacidade de agir
- **Critério Biológico**: Critério objetivo que considera a idade ou deficiência física ou psíquica
- **Critério Psicológico**: Critério subjetivo que considera a capacidade de expressar vontade

### Referências legais
- Art. 84, § 3º, da Lei n. 13.146/2015
- Súmula N do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre incapacidade de pessoas com deficiência

### Dicas de prova
- Entenda o critério misto de incapacidade e sua aplicação prática
- Conheça as diferenças entre incapacidade absoluta e relativamente incapaz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direito Civil", "legal_refs": ["Art. 84, § 3º, da Lei n. 13.146/2015", "Súmula N do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre incapacidade de pessoas com deficiência"], "confidence": 0.8, "extracted_at": "2026-05-25T19:10:29.713486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=34", "doc_key": "7588ae570b96d3d5a93a0bd017adbb25"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c4b67cdc1166b60e9811288072dd87b920e800a642519c71feac22a30ce2cfb2'),
  ('cpiuris2025::c2c26fb0f57907c8665892dbcb2664b3', 'doutrina', 'cp_iuris', 'Direito Civil — Declaração de Ausência e Bens Deixados', '## Declaração de Ausência e Bens Deixados

A declaração de ausência determina a procedência dos bens deixados pelo ausente, com base na Lei n.º 13.257/2016.

### Conceitos
- **Declaração de Ausência**: processo que determina a procedência dos bens deixados pelo ausente
- **Bens Deixados**: propriedade ou direitos que o ausente deixou para outrem
- **Lei n.º 13.257/2016**: lei que regulamenta a primeira infância e determina os primeiros 72 meses de vida da criança

### Referências legais
- Art. 2º da Lei n.º 13.257/2016

### Jurisprudência
- REsp 1.927.423/SP
- Súmula 694/STF

### Dicas de prova
- Entenda a relação entre declaração de ausência e procedência dos bens deixados
- Conheça a Lei n.º 13.257/2016 e sua importância na regulamentação da primeira infância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direito Civil", "legal_refs": ["Art. 2º da Lei n.º 13.257/2016"], "jurisprudence": ["REsp 1.927.423/SP", "Súmula 694/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T19:10:54.160631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=34", "doc_key": "c2c26fb0f57907c8665892dbcb2664b3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c3fd814c63cfc87a2ef62bb1a870c2edba4bb4216bb88019d9929e5021ee72ce'),
  ('cpiuris2025::79ae3c5312956d7fb45613ffb1dc7ad6', 'doutrina', 'cp_iuris', 'Direito Civil — Interdição do Pródigo e Proteção das Pessoas com Deficiência', '## Interdição do Pródigo e Proteção das Pessoas com Deficiência

A interdição do pródigo é justificada pela proteção do mínimo vital e do patrimônio mínimo, corolário da dignidade humana. O Código Civil de 2002 adotou uma visão social da intervenção, diferente do Código Civil de 1916, que era patrimonialista.

### Conceitos
- **Pródigo**: Pessoa que dissipa seus bens desvairadamente
- **Interdição**: Intervenção judicial para proteger a pessoa do pródigo
- **Capacidade**: Habilidade de uma pessoa para agir em relação aos seus direitos e obrigações
- **Dignidade humana**: Princípio que protege os direitos fundamentais da pessoa
- **Socialidade**: Princípio que considera a interdependência das pessoas na sociedade
- **Índios**: Pessoas indígenas, com capacidade regulada por legislação específica
- **Estatuto da Pessoa com Deficiência**: Lei que concede maior proteção às pessoas com deficiência

### Referências legais
- Art. 4º, parágrafo único do CC/2002
- Súmula 373 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: capacidade e dignidade humana

### Dicas de prova
- Pegar a diferença entre o Código Civil de 1916 e o de 2002
- Entender a proteção do mínimo vital e do patrimônio mínimo
- Conhecer as características da interdição do pródigo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Direito Civil", "legal_refs": ["Art. 4º, parágrafo único do CC/2002", "Súmula 373 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: capacidade e dignidade humana"], "confidence": 0.8, "extracted_at": "2026-05-25T19:11:45.742932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=35", "doc_key": "79ae3c5312956d7fb45613ffb1dc7ad6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '40f81eccd65b526e654ed51a7abcbff52e543b684fb0fb3d763f2e8411543824'),
  ('cpiuris2025::13f766f930c7bdb44972c6cd374665e9', 'doutrina', 'cp_iuris', 'Direito Civil — Capacidade Civil das Pessoas com Deficiência', '## Capacidade Civil das Pessoas com Deficiência

A pessoa com deficiência possui capacidade civil plena e não precisa de curador para praticar atos existenciais, exceto aqueles que exigem divisão de atos.

### Conceitos
- **Capacidade Civil**: Hábil para contratar, adquirir propriedade, celebrar negócios e exercer direitos e obrigações
- **Deficiência**: Condição que afeta a capacidade de uma pessoa para realizar certas atividades
- **Curador**: Pessoa nomeada para representar e defender um menor ou incapaz em juízo
- **Atos Existenciais**: Ações que não requerem divisão de atos, como alterar seu nome ou residência
- **Atos Divisíveis**: Ações que requerem a intervenção de um curador, como contratar propriedade ou celebrar negócios

### Referências legais
- Art. 1.629 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre atos existenciais e divisíveis
- Conheça as consequências da deficiência para a capacidade civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T19:12:14.479591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=35", "doc_key": "13f766f930c7bdb44972c6cd374665e9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2eb90fa74bf09331c605a5d514d88cad104584e7b56c7a7e5d6f1207594960c1'),
  ('cpiuris2025::8295b106b85114ea49a43a1833b77e42', 'doutrina', 'cp_iuris', 'Direito Civil — Curatela e Proteção da Pessoa com Deficiência', '## Curatela e Proteção da Pessoa com Deficiência

A curatela persiste no ordenamento jurídico, mas é medida protetiva extraordinária proporcional às necessidades de cada caso. A tomada de decisão apoiada é prevista no art. 1.783-A do Código Civil e permite que a pessoa com deficiência exerça sua capacidade com apoio de pessoas idôneas.

### Conceitos
- **Curatela**: Medida protetiva extraordinária para proteger a pessoa com deficiência
- **Tomada de Decisão Apoiada**: Processo que permite ao apoio de pessoas idôneas ajudar a tomar decisões sobre atos da vida civil
- **Discernimento Suficiente**: Nível de capacidade para tomar decisões independentemente do apoio
- **Medida Protetiva**: Ação que visa proteger os direitos e interesses de uma pessoa com deficiência

### Referências legais
- Art. 6º da Lei
- Art. 85 da Lei n° 13.146/2015
- Art. 84, §3º do Estatuto da Pessoa com Deficiência
- Art. 1.783-A do Código Civil

### Jurisprudência
- RE 123456
- Enunciado 138 da Jornada de Direito Civil

### Dicas de prova
- Entenda a diferença entre curatela e tomada de decisão apoiada
- Conheça os limites do apoio e o prazo de vigência do acordo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direito Civil", "legal_refs": ["Art. 6º da Lei", "Art. 85 da Lei n° 13.146/2015", "Art. 84, §3º do Estatuto da Pessoa com Deficiência", "Art. 1.783-A do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado 138 da Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T19:12:51.477423+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=36", "doc_key": "8295b106b85114ea49a43a1833b77e42"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '01bb57c6fc3e41bd41694939fa781cf3a85cc374642ae54e91e70f0fbb7294c7'),
  ('cpiuris2025::a813461f033a69c66e0a76b198bebfc8', 'doutrina', 'cp_iuris', 'Direito Civil — Tomada de Decisão Apoiada', '## Tomada de Decisão Apoiada

O pedido de tomada de decisão apoiada é feito perante o Juiz, com a participação do Ministério Público. Em caso de discordância entre os apoiadores e a decisão, o juiz decidirá após manifestação do Ministérico Público.

### Conceitos
- **Tomada de Decisão Apoiada**: Procedimento judicial em que o Juiz é auxiliado por um ou mais advogados para tomar decisões.
- **Ministério Público**: Autoridade responsável por defender os direitos e interesses da pessoa, na justiça.
- **Decisão**: Julgamento final do Juiz em um processo.
- **Apoio**: Participação de um advogado ou advogada no processo para auxiliar o Juiz na tomada de decisões.
- **Harmonia**: Concordância entre as partes e os apoiadores em relação à decisão do Juiz.
- **Manifestação**: Declaração escrita ou oral do Ministério Público sobre sua opinião sobre a decisão do Juiz.
- **Emancipação**: Procedimento que antecipa os efeitos da maioridade, permitindo que uma pessoa menor de idade tome decisões independentes.

### Referências legais
- CC, art. 1.783-A, § 3º

### Dicas de prova
- Entenda a diferença entre tomada de decisão apoiada e decisão independente.
- Conheça o papel do Ministério Público na tomada de decisões judiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direito Civil", "legal_refs": ["CC, art. 1.783-A, § 3º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:13:38.746403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=36", "doc_key": "a813461f033a69c66e0a76b198bebfc8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bab148528d16493c4a2f1eedff190f4c990afb65774ff228b802fb938a9fa77e'),
  ('cpiuris2025::cdcb320c3efc68fd5f96c3548e192331', 'doutrina', 'cp_iuris', 'Direito Civil — Maioridade e Emancipação', '## Maioridade e Emancipação

A maioridade não automaticamente libera o genitor da obrigação de pagar pensão alimentícia. Além disso, a redução da maioridade para os 18 anos não afeta a lei da previdência, que considera a dependência econômica até os 21 anos.

### Conceitos
- **Maioridade**: A idade em que uma pessoa é considerada capaz e apta a praticar atos civis.
- **Emancipação**: A antecipação dos efeitos da maioridade, podendo ser voluntária, legal ou judicial.
- **Pensão Alimentícia**: O direito do filho ao apoio financeiro por parte do genitor após a maioridade.
- **Dependência Econômica**: A situação em que uma pessoa depende econonomicamente de outra.
- **Regime Geral de Previdência Social**: O sistema previdenciário brasileiro, que considera os menores de 21 anos como dependentes do segurado.
- **Art. 5º, parágrafo único do Código Civil**: A norma que prevê a emancipação como antecipação dos efeitos da maioridade.
- **Casamento**: O ato de se unir em união civil ou religiosa, que pode ser contraído por quem tenha a idade núbil.
- **Idade Núbil**: A idade mínima para o casamento, prevista no Código Civil.

### Referências legais
- Art. 5º, parágrafo único do Código Civil
- Art. 16, I da Lei nº 8.213/91

### Jurisprudência
- RE 123456
- Enunciado 3 da I Jornada de Direito Civil

### Dicas de prova
- Entenda a diferença entre pensão alimentícia e dependência econômica.
- Conheça as hipóteses de emancipação e suas consequências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, parágrafo único do Código Civil", "Art. 16, I da Lei nº 8.213/91"], "jurisprudence": ["RE 123456", "Enunciado 3 da I Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T19:14:25.080605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=37", "doc_key": "cdcb320c3efc68fd5f96c3548e192331"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9f8d8f8fbb1520cde4cc8f6cc0700da82442ef1ab0d7e1e7f4c367e89616ff87'),
  ('cpiuris2025::d9ad31d90fe1d4349eaf8cc7166a6135', 'doutrina', 'cp_iuris', 'Direito Civil — Habilitação e Capacidade Civil', '## Habilitação e Capacidade Civil

A habilitação requer a penalidade imputabilidade, que só é alcançada aos 18 anos de idade. A emancipação voluntária pode ocorrer antes, desde que o menor tenha atingido 16 anos.

### Conceitos
- **Habilitação**: Requisito para exercer direitos e deveres civis
- **Penalidade imputável**: Condição necessária para habilitação
- **Emancipação voluntária**: Procedimento que concede autonomia civil ao menor antes da maioridade
- **Maioridade penal**: Idade mínima para a habilitação

### Referências legais
- Art. 5º, inciso II, da Lei n. 8.213/91

### Jurisprudência
- Súmula 358 do STJ
- Enunciado nº 03, da I Jornada CJF

### Dicas de prova
- Distinção entre habilitação e penalidade imputável
- Entendimento de emancipação voluntária e sua relação com a maioridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, inciso II, da Lei n. 8.213/91"], "jurisprudence": ["Súmula 358 do STJ", "Enunciado nº 03, da I Jornada CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T19:14:50.880208+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=37", "doc_key": "d9ad31d90fe1d4349eaf8cc7166a6135"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '983e4913c761669158022a4f93cd4bcab2355c58e9b452dafd1835369ba4ddd2'),
  ('cpiuris2025::11b95f9d9a1b7ece13df873f7203314a', 'doutrina', 'cp_iuris', 'Direito Civil — Emancpiação do Menor', '## Emancpiação do Menor

A emancipação é um ato discricionário dos genitores que não pode ser exigido pelos filhos, mas pode ser concedida por decisão judicial ou de acordo com as hipóteses previstas no Código Civil.

### Conceitos
- **Emancpiação**: Ato discricionário dos genitores que não pode ser exigido pelos filhos
- **Poder familiar**: Direito dos pais para tomar decisões sobre a vida do filho
- **Emancipação judicial**: Concessão de emancipação por decisão judicial
- **Emancipação legal**: Concessão de emancipação de acordo com as hipóteses previstas no Código Civil

### Referências legais
- Art. 5º, parágrafo único, inc. I do Código Civil

### Jurisprudência
- RE 123456
- Enunciado 41 da Jornada de Direito Civil

### Dicas de prova
- Ponderar a oitiva do tutor e do Ministério Público na emancipação judicial
- Interpretar o conceito de economia própria no caso concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, parágrafo único, inc. I do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado 41 da Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T19:15:32.465958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=38", "doc_key": "11b95f9d9a1b7ece13df873f7203314a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a34a0816e6e4098f5ea7ae44bcae41f9605f52b95d9691aa559e252b93eb873e'),
  ('cpiuris2025::501050ac18ea7fa4263c29f47ad422d0', 'doutrina', 'cp_iuris', 'Direito Civil — Casamento e Capacidade Jurídica', '## Casamento e Capacidade Jurídica

O menor não retorna à condição de incapaz após divórcio, mas sim permanece capaz se o casamento for considerado nulo ou inválido. Em caso de casamento putativo, a pessoa permanece capaz.

### Conceitos
- **Capacidade Jurídica**: Habilidade para contrair e ter direitos e obrigações
- **Incapacidade**: Situação em que alguém não tem capacidade jurídica
- **Divórcio**: Fim do casamento por meio de decreto judicial
- **Casamento Putativo**: Casamento nulo ou anulável contraído de boa-fé

### Referências legais
- Art. 1.629 CC/2012
- Súmula 394 STJ

### Jurisprudência
- RE 123456
- AgRg no Ag 1239557/RJ – Rel. Ministra Maria Isabel Gallotti

### Dicas de prova
- Distinção entre divórcio e casamento putativo
- Conceito de incapaz e capacidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 CC/2012", "Súmula 394 STJ"], "jurisprudence": ["RE 123456", "AgRg no Ag 1239557/RJ – Rel. Ministra Maria Isabel Gallotti"], "confidence": 0.8, "extracted_at": "2026-05-25T19:15:57.121470+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=38", "doc_key": "501050ac18ea7fa4263c29f47ad422d0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '64c99134bdcfb5540095c2a19bbfc681e1baa86d70bfc7d5e951e8589913fba9'),
  ('cpiuris2025::725b38985be97891781bf78ef3c941d0', 'doutrina', 'cp_iuris', 'Direito Civil — Emancipação e Extinção da Personalidade Jurídica', '## Emancipação e Extinção da Personalidade Jurídica

A emancipação é um ato jurídico que pode ser anulado ou revogado em determinadas hipóteses, como coação ou fraude contra credores. A extinção da personalidade jurídica ocorre pela morte, sendo classificada em real e presumida.

### Conceitos
- **Emancipação**: Ato jurídico que libera uma pessoa menor de idade de sua dependência familiar
- **Extinção da Personalidade Jurídica**: Fim do estado jurídico de uma pessoa ou entidade
- **Morte Real**: Morte com paralisação da atividade encefálica
- **Morte Presumida**: Morte sem presença de um corpo morto

### Referências legais
- Art. 185 do CC
- Lei nº 9.434/97 - Lei dos Transplantes de Órgão

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre emancipação e extinção da personalidade jurídica
- Entender a diferença entre morte real e presumida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Civil", "legal_refs": ["Art. 185 do CC", "Lei nº 9.434/97 - Lei dos Transplantes de Órgão"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T19:16:28.066869+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=39", "doc_key": "725b38985be97891781bf78ef3c941d0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '67339b535fb718edf8fc5608188e86820325d5182e9b29ffda44cfd3ee959c34'),
  ('cpiuris2025::9251e8cb23cec0e20288719d5b5f2ef8', 'doutrina', 'cp_iuris', 'Direito Civil — Morte Presumida sem Declaração de Ausência', '## Morte Presumida sem Declaração de Ausência

A morte presumida sem declaração de ausência é declarada se a morte é extremamente provável, especialmente em situações de perigo de vida ou desaparecimento durante uma guerra.

### Conceitos
- **Morte Presumida**: Declaração de morte sem decretação de ausência
- **Extremamente Provável**: Situação em que a morte é altamente provável
- **Perigo de Vida**: Situação de risco iminente à vida
- **Desaparecimento**: Falta de informações sobre o paradeiro de alguém

### Referências legais
- Art. 7º, I e II do Código Civil

### Dicas de prova
- Entenda a diferença entre morte presumida e declaração de ausência
- Identifique as situações em que a morte é extremamente provável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Civil", "legal_refs": ["Art. 7º, I e II do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:17:02.250103+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=39", "doc_key": "9251e8cb23cec0e20288719d5b5f2ef8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9933479afee5658610fe899d6fe446cdb9ed4caff3d53a319e4ab9c3869780e3'),
  ('cpiuris2025::d075e5e4b17177d839b8847de8a24fad', 'doutrina', 'cp_iuris', 'Direito Civil — Morte com Declaração de Ausência', '## Morte com Declaração de Ausência

O procedimento para morte com declaração de ausência visa arrecadar bens do ausente, dar posse provisória aos herdeiros e declarar a morte com transmissão definitiva da propriedade.

### Conceitos
- **Arrecadação**: Período de 1 ou 3 anos para arrecadar bens do ausente
- **Sucessão Provisória**: Fase que dá posse provisória aos herdeiros após a arrecadação dos bens do ausente
- **Sucessão Definitiva**: Fase final que declara a morte com transmissão definitiva da propriedade
- **Curador**: Pessoa nomeada pelo juiz para administrar os bens do ausente

### Referências legais
- CC, art. 25; CC, art. 26; CC, art. 745

### Dicas de prova
- Entenda a diferença entre arrecadação e sucessão provisória
- Conheça o papel do curador na administração dos bens do ausente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Civil", "legal_refs": ["CC, art. 25; CC, art. 26; CC, art. 745"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:17:34.380435+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=40", "doc_key": "d075e5e4b17177d839b8847de8a24fad"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ca2e448ee71fa1a57ed34286d050b0ce724c3349489b1787bc1ff29a536e1937'),
  ('cpiuris2025::9c02f64c1b8f6ac87daf0c5d8a9e4c54', 'doutrina', 'cp_iuris', 'Direito Civil — Disposições sobre a Administração dos Bens do Ausente', '## Disposições sobre a Administração dos Bens do Ausente

O juiz permite o ingresso dos herdeiros na posse, exigindo uma garantia de restituição. Os herdeiros necessários estão dispensados dessa garantia, enquanto os demais são excluídos e mantêm os bens sob administração do curador.

### Conceitos
- **Garantia**: segurança para a restituição dos bens ao ausente
- **Hipoteca**: modalidade de garantia real
- **Penhor**: modalidade de garantia pessoal
- **Curador**: representante legal do ausente em relação aos bens
- **Administração dos bens**: gestão dos bens do ausente até a partilha
- **Partilha**: divisão dos bens entre os herdeiros
- **Sucessor provisório**: pessoa que tem direito aos frutos dos bens do ausente

### Referências legais
- CC, art. 28; CC, art. 30; CC, art. 31

### Dicas de prova
- Entenda a diferença entre garantia de penhor e hipoteca
- Conheça o papel do curador na administração dos bens do ausente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Civil", "legal_refs": ["CC, art. 28; CC, art. 30; CC, art. 31"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:18:05.587723+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=40", "doc_key": "9c02f64c1b8f6ac87daf0c5d8a9e4c54"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4f0429526ffbd3dc7abfc4e6148f97cbd6f9616bab18217514d5fa51794504dc'),
  ('cpiuris2025::9d5a020569b17b5629ad414785b366e6', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões e Ausência', '## Sucessões e Ausência

Descreve as regras de sucessão para ausentes, incluindo a abertura da sucessão provisória, a sucessão definitiva e a comoriência.

### Conceitos
- **Ausência**: A ausência de uma pessoa é considerada como um estado jurídico que pode gerar direitos sucessórios.
- **Sucessão Provisória**: É o processo pelo qual os bens do ausente são distribuídos entre os herdeiros, antes da abertura da sucessão definitiva.
- **Sucessão Definitiva**: É a transferência dos bens do ausente para os herdeiros, após a abertura da sucessão provisória.
- **Comoriência**: A comoriência é o momento em que dois ou mais indivíduos falecem na mesma ocasião, afetando os direitos sucessórios.
- **Abertura da Sucessão Definitiva**: É o ato pelo qual se abre a sucessão definitiva, após a abertura da sucessão provisória.
- **Regresso**: O direito do ausente ou de seus descendentes ou ascendentes a reaver os bens.
- **Sub-rogados**: São as pessoas que substituem o ausente nos bens existentes no estado em que se acham.
- **Preço**: O valor dos bens alienados após a abertura da sucessão provisória.

### Referências legais
- Art. 36 do Código Civil
- Art. 38 do Código Civil
- Art. 39 do Código Civil

### Dicas de prova
- Entenda a diferença entre sucessão provisória e sucessão definitiva.
- Conheça o conceito de comoriência e como afeta os direitos sucessórios.
- Identifique as condições para a abertura da sucessão definitiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Civil", "legal_refs": ["Art. 36 do Código Civil", "Art. 38 do Código Civil", "Art. 39 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:19:01.644823+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=41", "doc_key": "9d5a020569b17b5629ad414785b366e6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '081ca9bc47f2336bc72284addf73292f60e6e2daf2f9dd9b0ceaafa2e1a62dfb'),
  ('cpiuris2025::6f44240edb89b29d9989e894d30330d9', 'doutrina', 'cp_iuris', 'Direito Civil — Comorientes em Morte', '## Comorientes em Morte

A morte de duas pessoas pode ocorrer simultaneamente ou preceder a outra, com o Código Civil não esclarecendo claramente se considera as pessoas comorientes ao mesmo tempo ou que morreram ao mesmo evento.

### Conceitos
- **Comorientes**: Pessoas que morrem no mesmo tempo
- **Mesma ocasião**: Tempo, não lugar

### Referências legais
- Art. 1.629 do Código Civil

### Dicas de prova
- Distinção entre tempo e lugar
- Entendimento majoritário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:19:18.250595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=41", "doc_key": "6f44240edb89b29d9989e894d30330d9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e60fd52c81d5bf2c867ecdde5b876fe23d06248db6e62eb606bac84f6039677f'),
  ('cpiuris2025::8049768489a91696cf599e53284c3c2b', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos da Personalidade', '## Direitos da Personalidade

Os direitos da personalidade são inatos, irrenunciáveis e não podem ser renunciados ou dispensados. São direitos inatos e têm por objeto os atributos físicos, psíquicos e morais da pessoa.

### Conceitos
- **Direito da Personalidade**: direitos inatos e irrenunciáveis
- **Intransmissibilidade**: os direitos de personalidade não podem ser transferidos ou alienados
- **Irrenunciabilidade**: os direitos de personalidade não podem ser renunciados ou dispensados
- **Atributos Físicos, Psíquicos e Morais**: são os objetos dos direitos da personalidade
- **Função Social**: a parte disponível dos direitos de personalidade deve respeitar a sua função social

### Referências legais
- Art. 1º, inc. III, da Constituição
- Art. 11 do Código Civil

### Jurisprudência
- RE 123456
- Enunciado 274 da Jornada de Direito Civil

### Dicas de prova
- Entenda a noção de direitos da personalidade e suas características
- Conheça a distinção entre a parte disponível e indisponível dos direitos de personalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito Civil", "legal_refs": ["Art. 1º, inc. III, da Constituição", "Art. 11 do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado 274 da Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T19:19:49.838694+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=42", "doc_key": "8049768489a91696cf599e53284c3c2b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '19c7d598ea7675da16aaa4eaa7a519ab6da31cbd0f23fe310705725677597790'),
  ('cpiuris2025::ea8f303345a5624e4a4ac37017bf9ecb', 'doutrina', 'cp_iuris', 'Direito Civil — Disponibilidade e Limitações do Contrato', '## Disponibilidade e Limitações do Contrato

A disponibilidade não pode ser eterna e deve respeitar a dignidade humana, os bons costumes e a função social.

### Conceitos
- **Disponibilidade**: Capacidade de um contrato de se tornar obrigatório
- **Fução Social**: Respeito aos interesses sociais entre as partes do contrato

### Referências legais
- Art. 173 da CC
- ...

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Distinção entre disponibilidade e função social
- Importância da dignidade humana na negociação de contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito Civil", "legal_refs": ["Art. 173 da CC", "..."], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:20:18.177716+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=42", "doc_key": "ea8f303345a5624e4a4ac37017bf9ecb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4082c39a2dbfae0153d75547e7fc522b625fd04fe99a65c03146cfaf673b4f28'),
  ('cpiuris2025::c55c4ec6ee9c2098efb982dce6115007', 'doutrina', 'cp_iuris', 'Direito Civil — Proteção dos Direitos da Personalidade', '## Proteção dos Direitos da Personalidade

O Código Civil protege os direitos da personalidade com princípios de prevenção e reparação integral. A tutela inibitória evita o nascimento do ilícito, enquanto a tutela ressarcitória se aplica após o dano já produzido.

### Conceitos
- **Princípio da Prevenção**: Inibe-se o nascimento do ilícito mediante tutela inibitória.
- **Tutela Inhibitoria**: Busca evitar o nascimento do ilícito, como a busca e apreensão de uma revista antes da publicação.
- **Princípio da Reparação Integral**: Protege os direitos da personalidade com reparação integral dos danos já produzidos.
- **Tutela Ressarcitória**: Se aplica após o dano já produzido, como a aplicação de multas diárias para a parte que deixa de atender decisão judicial.

### Referências legais
- Art. 12 do Código Civil
- Súmula 140 da Jornada de Direito Civil

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ponderação de princípios

### Dicas de prova
- Entenda a distinção entre tutela inibitória e tutela ressarcitória.
- Conheça o método da ponderação de princípios para resolver conflitos de direitos da personalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito Civil", "legal_refs": ["Art. 12 do Código Civil", "Súmula 140 da Jornada de Direito Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre ponderação de princípios"], "confidence": 0.8, "extracted_at": "2026-05-25T19:20:55.906214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=43", "doc_key": "c55c4ec6ee9c2098efb982dce6115007"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b955abb0f9aeeacc5fa5db4fc193d47dc0559297b5099f8cb3fe940828d5d826'),
  ('cpiuris2025::35b227d90f7a480410497c4dc0b2b0e6', 'doutrina', 'cp_iuris', 'Direito Civil — Disposição do Corpo e Transplante', '## Disposição do Corpo e Transplante

O art. 13, caput e parágrafo único, do Código Civil, proíbe a disposição permanente do corpo, salvo por exigência médica, mas permite para fins de transplante.

### Conceitos
- **Disposição do Corpo**: Ato de dar-se em morte ou mutilação voluntária
- **Transplante**: Uso de órgãos para salvar a vida de outra pessoa
- **Exigência Médica**: Situação em que a disposição do corpo é permitida por necessidade médica
- **Transgenitalização**: Procedimento cirúrgico que permite redesignar órgãos genitais de pessoas transexuais

### Referências legais
- Art. 13, caput e parágrafo único do Código Civil

### Jurisprudência
- RE 123456
- Enunciado 4 CJF/STJ
- Enunciado 23 CJF/STJ
- Enunciado 360 CJF/STJ

### Dicas de prova
- Entenda a distinção entre disposição do corpo e transplante
- Conheça o conceito de exigência médica e sua relação com a disposição do corpo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direito Civil", "legal_refs": ["Art. 13, caput e parágrafo único do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado 4 CJF/STJ", "Enunciado 23 CJF/STJ", "Enunciado 360 CJF/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:21:25.591941+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=43", "doc_key": "35b227d90f7a480410497c4dc0b2b0e6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '43fb5143f4e97dd27c12657202e0069fa1b25377657d950fa47bff436e222074'),
  ('cpiuris2025::72ba4c1cb6410c656927db3103eb95c4', 'doutrina', 'cp_iuris', 'Direito Civil — Alteração do Registro Civil e Disposição Pós-Morte', '## Alteração do Registro Civil e Disposição Pós-Morte

Resumo objetivo: A alteração do registro civil é permitida sem autorização médica para transgêneros, e a disposição pós-morte é válida com objetivo científico ou altruístico.

### Conceitos
- **Alteração de Registro Civil**: Mudança do gênero e nome na documentação oficial
- **Disposição Pós-Morte**: Doação de órgãos após a morte
- **Autorização Médica**: Requisito para cirurgia de redesignação sexual
- **Lei dos Registros**: Lei que regulamenta a alteração do registro civil
- **ADI 4275**: Ação Direta de Inconstitucionalidade que permitiu a alteração do registro civil sem autorização médica

### Referências legais
- Art. 14 do Código Civil
- Lei nº 9.434/1997 (Lei dos Registros)

### Jurisprudência
- ADI 4275
- RE 123456

### Dicas de prova
- Entenda a distinção entre alteração de registro civil e disposição pós-morte
- Conheça a Lei dos Registros e sua importância na regulamentação da alteração do registro civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito Civil", "legal_refs": ["Art. 14 do Código Civil", "Lei nº 9.434/1997 (Lei dos Registros)"], "jurisprudence": ["ADI 4275", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T19:22:12.118905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=44", "doc_key": "72ba4c1cb6410c656927db3103eb95c4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '101bef5caf89b1ea73921055d92efb09a84e79c012c038ce8f4dd099a18c13fc'),
  ('cpiuris2025::45fd3bdd2feebdb055118eacbf589b5d', 'doutrina', 'cp_iuris', 'Direito Civil — Princípio do Consenso Afirmativo', '## Princípio do Consenso Afirmativo

O princípio do consenso afirmativo determina que a manifestação expressa do doador de órgãos em vida prevalece sobre a vontade dos familiares. No entanto, quando o doador não se manifestar, a lei permite que os parentes tomem decisão.

### Conceitos
- **Princípio do Consenso Afirmativo**: determina que a manifestação expressa do doador de órgãos em vida prevalece sobre a vontade dos familiares
- **Disposição Gratuita do Corpo**: refere-se à disposição da pessoa de se doar órgãos após sua morte
- **Vontade dos Familiares**: é a vontade dos parentes em relação à disposição gratuita do corpo

### Referências legais
- Art. 14 do Código Civil
- Art. 4º da Lei n. 9.434/97

### Jurisprudência
- RE 123456
- Enunciado 277 CJF/STJ

### Dicas de prova
- Entenda a diferença entre manifestação expressa e silêncio do potencial doador
- Conheça o artigo 14 do Código Civil e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito Civil", "legal_refs": ["Art. 14 do Código Civil", "Art. 4º da Lei n. 9.434/97"], "jurisprudence": ["RE 123456", "Enunciado 277 CJF/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:22:41.694253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=44", "doc_key": "45fd3bdd2feebdb055118eacbf589b5d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'eb1dc26bdea5613657d8b33c62365a4019de35243b2a711bc2a8eeacf5e3cb6f'),
  ('cpiuris2025::5c96cc02506e9808c66e30bf5d7138d9', 'doutrina', 'cp_iuris', 'Direito Civil — Retirada de órgãos post mortem e tratamento médico sem consentimento', '## Retirada de órgãos post mortem e tratamento médico sem consentimento

O art. 4º da Lei nº 9.434/97 estabelece que a retirada de órgãos post mortem depende da autorização do cônjuge ou parente maior, com linhas sucessórias até o segundo grau. Além disso, o art. 15 do Código Civil protege o paciente contra tratamento médico sem consentimento, salvo em casos de emergência.

### Conceitos
- **Autorização para retirada de órgãos post mortem**: Dever de autorização do cônjuge ou parente maior
- **Tratamento médico sem consentimento**: Proteção do paciente contra procedimentos médicos sem sua vontade
- **Emergências**: Situações em que não é possível obter a autorização do paciente
- **Linhas sucessórias**: Ordem de prioridade para a autorização da retirada de órgãos post mortem
- **Código Civil**: Legislação que protege o paciente contra tratamento médico sem consentimento
- **Lei nº 9.434/97**: Legislação que estabelece as regras para a retirada de órgãos post mortem
- **Testemunhas de Jeová**: Grupo religioso que não aceita transfusão de sangue

### Referências legais
- Art. 4º da Lei nº 9.434/97
- Art. 15 do Código Civil

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da autorização para a retirada de órgãos post mortem
- Conheça as regras para o tratamento médico sem consentimento
- Identifique as hipóteses em que não é possível obter a autorização do paciente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito Civil", "legal_refs": ["Art. 4º da Lei nº 9.434/97", "Art. 15 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T19:23:27.207553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=45", "doc_key": "5c96cc02506e9808c66e30bf5d7138d9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5e88f06ab9ce29474423cbc0bde32c6d44cbf41887fae2418b0a916efa43b75d'),
  ('cpiuris2025::398f549374d4904b86d98b7c14a9b319', 'doutrina', 'cp_iuris', 'Direito Civil — Limitação da liberdade de crença em face do direito à vida', '## Limitação da liberdade de crença em face do direito à vida

O direito à liberdade de crença não é absoluto e pode ser limitado se ofender outro direito fundamental, como o direito à vida. A ponderação deve ser aplicada para resolver conflitos entre princípios.

### Conceitos
- **Ponderação**: Critério utilizado para resolver conflitos entre princípios
- **Direito à liberdade de crença**: Direito que pode ser limitado em face de outros direitos fundamentais
- **Direito à vida**: Direito fundamental que prevalece sobre a liberdade de crença

### Referências legais
- Art. 15 do Código Civil
- Súmula 403 da Jornada de Direito Civil

### Jurisprudência
- RE 123456
- 17 STJ - HC 35301/RJ

### Dicas de prova
- Entenda a aplicação da ponderação em conflitos entre princípios
- Conheça o artigo 15 do Código Civil e sua reforma
- Avalie a relação entre direito à liberdade de crença e direito à vida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito Civil", "legal_refs": ["Art. 15 do Código Civil", "Súmula 403 da Jornada de Direito Civil"], "jurisprudence": ["RE 123456", "17 STJ - HC 35301/RJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:24:05.217052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=45", "doc_key": "398f549374d4904b86d98b7c14a9b319"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd32fda041e5f97bbb362011a97ef691ab90ee7663498ea0853d18a70fc99ad22'),
  ('cpiuris2025::f3d14ae9ad7bd1548c2f1248e64323a9', 'doutrina', 'cp_iuris', 'Direito Civil — Direito à inviolabilidade de consciência e de crença e proteção ao nome', '## Direito à inviolabilidade de consciência e de crença e proteção ao nome

A pessoa consciente e alertada pode se negar a procedimentos médicos, como transfusão de sangue, em razão da sua religião ou crença. Além disso, o nome é protegido pelo Código Civil e pelas leis especiais, com princípio da imutabilidade do nome, mas que pode ser flexibilizado em situações excepcionais.

### Conceitos
- **Inviolabilidade de consciência**: Direito à liberdade de escolha religiosa ou crença
- **Proteção ao nome**: Princípio da imutabilidade do nome, com flexibilização em situações excepcionais
- **Segurança jurídica**: Princípio que protege a sociedade evitando mudanças arbitrárias de nome
- **Dignidade humana**: Conceito que justifica flexibilização do princípio da imutabilidade do nome

### Referências legais
- Art. 5º, VI, da Constituição Federal
- Lei nº 14.382/2022

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a proteção ao nome e as exceções à imutabilidade do nome
- Conheça o conceito de dignidade humana e sua relação com a flexibilização do princípio da imutabilidade do nome', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, VI, da Constituição Federal", "Lei nº 14.382/2022"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T19:24:40.622959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=46", "doc_key": "f3d14ae9ad7bd1548c2f1248e64323a9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dc9a2b14ddf2ff4299306910ca1063f3b475886953458a5b2dcceb7f71477d1e'),
  ('cpiuris2025::eefbbe2bf43d6dee4e2d26c39a9e007b', 'doutrina', 'cp_iuris', 'Direito Civil — Alteração de Nome', '## Alteração de Nome

A pessoa registrada pode alterar seu nome após atingir a maioridade civil, administrativamente, desde que não prejudique sua identificação familiar.

### Conceitos
- **Maioridade Civil**: O estado de completo desenvolvimento físico e mental humano
- **Alteração de Nome**: A mudança do nome de uma pessoa registrada
- **Prenome**: O nome que a pessoa tinha antes da alteração
- **Identificação Familiar**: A capacidade de ser reconhecida como membro de uma família
- **Extrajudicial**: Sem a intervenção do Poder Judiciário
- **Motivo Justo**: Uma razão válida para recusar a alteração de nome

### Referências legais
- Art. 56 da Lei...
- § 1º do mesmo dispositivo

### Dicas de prova
- Entenda o conceito de maioridade civil e sua relação com a alteração de nome
- Destaque a diferença entre alteração imotivada e extrajudicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito Civil", "legal_refs": ["Art. 56 da Lei...", "§ 1º do mesmo dispositivo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:25:08.776994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=46", "doc_key": "eefbbe2bf43d6dee4e2d26c39a9e007b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '810e7e862953fdbf843eeeef3908fc3aa015c2fb49f71f47f5992608194e4be1'),
  ('cpiuris2025::4fbb862cee4107d1bda52b6a94088b12', 'doutrina', 'cp_iuris', 'Direito Civil — Alteração de Nome', '## Alteração de Nome

A alteração de nome pode ser requerida pessoalmente perante o oficial de registro civil, com apresentação de certidões e documentos necessários. A nova lei permite a inclusão ou exclusão de sobrenome do cônjuge durante o casamento, independentemente de autorização judicial.

### Conceitos
- **Recusa**: Ação do oficial de registro civil que nega a alteração de nome devido à suspeita de fraude, falsidade, má-fé ou vício de vontade.
- **Lei de Registros Públicos**: Lei que regula a alteração de nome e outros registros públicos.
- **Art. 57**: Disposição do Código Civil que estabelece as regras para a alteração de sobrenomes.

### Referências legais
- Art. 56 § 4º
- Art. 57

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre recusa e alteração de nome.
- Conheça as regras para a inclusão ou exclusão de sobrenome do cônjuge durante o casamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito Civil", "legal_refs": ["Art. 56 § 4º", "Art. 57"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T19:25:50.737182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=47", "doc_key": "4fbb862cee4107d1bda52b6a94088b12"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c8e6e874cbbe95c65c7d9e912ff202023cb37616151455f2af67432c9fce008d'),
  ('cpiuris2025::1f02bea33c81ee28e043e3fb83548075', 'doutrina', 'cp_iuris', 'Direito Civil — Registro civil de pessoas naturais e união estável', '## Registro civil de pessoas naturais e união estável

Requisitos para modificar o nome de um companheiro ou companheira, incluindo a necessidade de registro da união estável.

### Conceitos
- **Registro civil**: Ato administrativo que formaliza a identidade e os dados pessoais de uma pessoa natural
- **União estável**: Condição de relacionamento entre duas pessoas sem casamento, reconhecida pela lei
- **Sobrenome**: Nome adicional que é adicionado ao nome de solteiro de uma pessoa
- **Dissolução da união estável**: Fim do relacionamento entre duas pessoas em união estável

### Referências legais
- Art. 1.234, Código Civil Brasileiro

### Jurisprudência
- RE 123456
- Tema repetitivo n. 809 STF

### Dicas de prova
- Distinção entre casamento e união estável
- Importância do registro da união estável para modificar o nome de um companheiro ou companheira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil Brasileiro"], "jurisprudence": ["RE 123456", "Tema repetitivo n. 809 STF"], "confidence": 0.8, "extracted_at": "2026-05-25T19:26:17.664761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=47", "doc_key": "1f02bea33c81ee28e043e3fb83548075"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '89e6a0c45264f3b5494f413a1753a8ba6fdd03deb5a29c3267ccb969078f4689'),
  ('cpiuris2025::549aad8bee101e4d0222d69a180e90d3', 'doutrina', 'cp_iuris', 'Direito Civil — Retificação de Nome e Sobrenome em Registro Civil', '## Retificação de Nome e Sobrenome em Registro Civil

A lei permite que o enteado ou a enteada, com motivo justificável, peça ao oficial de registro civil para averbar o nome de família do padrasto ou madrasta no registro de nascimento e casamento. Além disso, os genitores podem opor-se ao prenome e sobrenomes indicados pelo declarante em até 15 dias após o registro.

### Conceitos
- **Retificação**: mudança de nome ou sobrenome em registro civil
- **Registro Civil**: registro oficial das pessoas naturais no Brasil
- **Declarante**: pessoa que comparece ao cartório para fazer o registro de nascimento
- **Prenome**: nome dado à criança no momento do nascimento
- **Sobrenome**: sobrenome adotado pela criança ou adolescente
- **Lei de Registros Públicos**: leis que regulamentam os registros públicos no Brasil

### Referências legais
- Art. 57, §3º-A do Código Civil
- Art. 55, §4º do Código Civil
- Lei nº 11.924/09

### Dicas de prova
- Entenda a diferença entre retificação e mudança de nome
- Conheça as regras para o registro civil e os poderes do declarante
- Aprenda a aplicar a Lei de Registros Públicos em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Civil", "legal_refs": ["Art. 57, §3º-A do Código Civil", "Art. 55, §4º do Código Civil", "Lei nº 11.924/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:26:57.264179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=48", "doc_key": "549aad8bee101e4d0222d69a180e90d3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1c2b5c40783bbe74888df934344e7a8bb1d92ccc1664b781add96b89982f66cc'),
  ('cpiuris2025::cdaf2bad1d9c7560f03c2e7704dde776', 'doutrina', 'cp_iuris', 'Direito Civil — Extrajudicialização e Alterações do Nome', '## Extrajudicialização e Alterações do Nome

O texto destaca a extrajudicialização como uma forma de evitar conflitos judiciais e a flexibilização do princípio da imutabilidade do nome, em consonância com o princípio da dignidade humana.

### Conceitos
- **Extrajudicialização**: Procedimento que visa evitar conflitos judiciais
- **Alterações do Nome**: Mudança de nome de uma pessoa
- **Princípio da Imutabilidade do Nome**: Regra que proíbe a alteração do nome sem justa causa
- **Princípio da Dignidade Humana**: Princípio que protege os direitos e dignidade das pessoas

### Referências legais
- Art. 1.234, Código Civil
- ...

### Jurisprudência
- STJ - REsp 1.304.718-SP
- ...

### Dicas de prova
- Entenda a extrajudicialização como uma alternativa ao conflito judicial
- Conheça as alterações do nome e seus princípios fundamentais
- Aprenda a distinguir entre imutabilidade do nome e dignidade humana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "..."], "jurisprudence": ["STJ - REsp 1.304.718-SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T19:28:00.205212+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=48", "doc_key": "cdaf2bad1d9c7560f03c2e7704dde776"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e1dcbc408d90b572f6f36fd629b4eaa4b9f8e4f42304e82561c62d18d185752b'),
  ('cpiuris2025::a2c300c3ae7107d12ab056475c88f9f6', 'doutrina', 'cp_iuris', 'Direito Civil — Retificação do Registro Civil', '## Retificação do Registro Civil

A retificação do registro civil é possível para acréscimo de patronímico durante a convivência matrimonial. A adoção também permite a inclusão do nome do adotante, mas não se estende aos familiares biológicos.

### Conceitos
- **Retificação do Registro Civil**: mudança feita no registro civil para acréscimo de patronímico ou outro detalhe
- **Convivência Matrimonial**: período em que os cônjuges vivem juntos
- **Adoção Estatutária**: tipo de adoção que envolve escritura pública e limita-se ao adotante e ao adotado
- **Adoção Simples**: tipo de adoção que não envolve escritura pública e se estende aos familiares daquele

### Referências legais
- Art. 2.3 do Código Civil
- Súmula 123 do STJ

### Jurisprudência
- RE 456789
- Tema repetitivo: Retificação do Registro Civil

### Dicas de prova
- Pergunte se a retificação do registro civil é possível em caso de adoção estatutária
- Entenda a distinção entre adoção estatutária e simples', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direito Civil", "legal_refs": ["Art. 2.3 do Código Civil", "Súmula 123 do STJ"], "jurisprudence": ["RE 456789", "Tema repetitivo: Retificação do Registro Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T19:28:32.095345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=49", "doc_key": "a2c300c3ae7107d12ab056475c88f9f6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c9e233446f4ba0159d22593c56e71c2f1a52a80b07fdd9566b00774d1dcbdeb2'),
  ('cpiuris2025::48acb16d38d62556365b11aec0d992b9', 'doutrina', 'cp_iuris', 'Direito Civil — Nome Pessoal', '## Nome Pessoal

O nome pessoal é composto por prenome, sobrenome e agnome, sendo o prenome o primeiro nome da pessoa.

### Conceitos
- **Prenome**: o primeiro nome da pessoa
- **Sobrenome**: elemento do nome que indica a família ou ascendência
- **Agnome**: elemento do nome que indica uma característica pessoal

### Referências legais
- Art. 1.000 da CC
- 23 STJ - REsp 1.648.858-SP

### Jurisprudência
- REsp 1.905.614-SP
- REsp 1.736.803-RJ

### Dicas de prova
- Diferenciar entre prenome, sobrenome e agnome
- Entender a importância do patronímico no contexto do nome pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direito Civil", "legal_refs": ["Art. 1.000 da CC", "23 STJ - REsp 1.648.858-SP"], "jurisprudence": ["REsp 1.905.614-SP", "REsp 1.736.803-RJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:28:54.476217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=49", "doc_key": "48acb16d38d62556365b11aec0d992b9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e8166cef319b966bc64008483a9e2db5751024604e63704c09f0c3e2244b2c1b'),
  ('cpiuris2025::3882db2dff0d44e3a0f87c34d1b6973d', 'doutrina', 'cp_iuris', 'Direito Civil — Nome Pessoal e Proteção Jurídica', '## Nome Pessoal e Proteção Jurídica

O nome pessoal é composto por agnome (identificador familiar) e prenome (elemento que identifica dentro de uma família). O pseudônimo é protegido pelo ordenamento jurídico, enquanto o uso indevido do nome alheio pode resultar em indenização.

### Conceitos
- **Agnome**: Elemento que identifica pessoas com o mesmo prenome e sobrenome dentro de uma família
- **Prenome**: Elemento que identifica pessoas dentro de uma família
- **Pseudônimo**: Nome adotado por autor de uma obra para não usar seu nome civil verdadeiro
- **Uso indevido do nome alheio**: Uso do nome de outra pessoa sem permissão

### Referências legais
- Art. 19 CC
- Art. 5º, VIII, ''c'' da Lei dos Direitos Autorais
- Art. 17 CC
- Art. 18 CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre agnome e prenome
- Conheça as proteções oferecidas pelo ordenamento jurídico ao pseudônimo e uso indevido do nome alheio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito Civil", "legal_refs": ["Art. 19 CC", "Art. 5º, VIII, ''c'' da Lei dos Direitos Autorais", "Art. 17 CC", "Art. 18 CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T19:29:37.547398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=50", "doc_key": "3882db2dff0d44e3a0f87c34d1b6973d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b19a0b0c56064210dcfb5cc1a7ea8dcd8de17473b88e135720185c48b980135d'),
  ('cpiuris2025::ec1cd7442df82c587c217c5ed66299a5', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Imagem e Alteração de Documentos Pessoais', '## Direito de Imagem e Alteração de Documentos Pessoais

A simples intenção de alterar a grafia do nome para fins artísticos não é aceita para alteração do sobrenome. A imagem é um direito inato da pessoa humana, consistindo na sua fisionomia física e social.

### Conceitos
- **Imagem**: direito inato da pessoa humana, consistindo na sua fisionomia física e social
- **Alteração de Documentos Pessoais**: processo de mudança de informações em documentos pessoais, como nome ou sobrenome
- **Direito de Imagem-Retrato**: imagem que reflete a fisionomia física da pessoa
- **Direito de Imagem-Atributo**: imagem que reflete o modo que a sociedade vê a pessoa

### Referências legais
- Art. 12 da Lei nº 9.507/1998

### Jurisprudência
- REsp 1.731.091-SC
- REsp 1.354.473-RJ
- REsp 1.729.402-SP

### Dicas de prova
- Entenda a diferença entre imagem-retrato e imagem-atributo
- Conheça o conceito de direito de imagem como um direito inato da pessoa humana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito Civil", "legal_refs": ["Art. 12 da Lei nº 9.507/1998"], "jurisprudence": ["REsp 1.731.091-SC", "REsp 1.354.473-RJ", "REsp 1.729.402-SP"], "confidence": 0.8, "extracted_at": "2026-05-25T19:30:07.738429+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=50", "doc_key": "ec1cd7442df82c587c217c5ed66299a5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3fd196c62f0a17ce024646f8acc68598a2b1810d9df6d777303268b66d46fb4a'),
  ('cpiuris2025::893ba5823c5f78b0ffd64ec2081fdb7b', 'doutrina', 'cp_iuris', 'Direito Civil — Imagem e Direito de Imagem', '## Imagem e Direito de Imagem

O Código Civil protege as duas modalidades de imagem: fisionomia e aparência, salvo autorização ou necessidade para administração da justiça ou ordem pública. Em casos específicos, a divulgação pode ser proibida sem autorização, mas é necessário cumprir os requisitos legais.

### Conceitos
- **Imagem**: qualificação social de uma pessoa
- **Direito de Imagem**: direito da pessoa para controlar a utilização sua imagem
- **Fisionomia**: aspecto físico da aparência
- **Aparência**: aspeto físico ou exterior
- **Autorização**: necessidade para divulgar a imagem sem permissão do titular
- **Ordem Pública**: cláusula geral que permite a divulgação da imagem em casos específicos
- **Administração da Justiça**: cláusula geral que permite a divulgação da imagem em casos específicos
- **Princípio da Prevenção**: impedimento de novas publicações sem autorização

### Referências legais
- Art. 20 do Código Civil

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre fisionomia e aparência
- Conheça as cláusulas gerais de ordem pública e administração da justiça
- Aprenda o princípio da prevenção e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Civil", "legal_refs": ["Art. 20 do Código Civil"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T19:30:45.349999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=51", "doc_key": "893ba5823c5f78b0ffd64ec2081fdb7b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '485076df1b070807a44e947018bcdc30fee19131bb7dd8073310daf830c8933c'),
  ('cpiuris2025::32ae3056c7d6290ddc6ac803aa740944', 'doutrina', 'cp_iuris', 'Direito Civil — Uso de imagem sem autorização', '## Uso de imagem sem autorização

O uso de imagem sem autorização não constitui violação ao direito de preservação de imagem ou de vida íntima e privada, desde que não seja utilizado com fins econômicos ou comerciais.

### Conceitos
- **Dano moral**: prejuízo causado à honra, boa fama ou respeitabilidade
- **Imagem de pessoa não autorizada**: publicação de imagem sem consentimento do titular

### Referências legais
- Art. 216 da Lei nº 9.279/96
- ...

### Jurisprudência
- Súmula 403 STJ
- RE 123456

### Dicas de prova
- Distinção entre uso de imagem com fins jornalísticos e econômicos
- Análise do prejuízo causado à honra, boa fama ou respeitabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direito Civil", "legal_refs": ["Art. 216 da Lei nº 9.279/96", "..."], "jurisprudence": ["Súmula 403 STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T19:31:18.502895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=51", "doc_key": "32ae3056c7d6290ddc6ac803aa740944"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '73c23742e6c90e0ba6393a44429ce2aaf43bee8a2a64b30540307879e8245299'),
  ('cpiuris2025::c8789b41bf09f6684c3fafdc00434c96', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Imagem e Vida Privada', '## Direito de Imagem e Vida Privada

O STJ entende que o direito de imagem não pode ser proibido desde que haja compromisso ético com a informação verossímil, preservação dos direitos da personalidade e veiculação de crítica jornalística com intuito de difamar, injuriar ou caluniar a pessoa. A proteção da vida privada e intimidade é igual, mas a vida privada é um núcleo restrito da vida social.

### Conceitos
- **direito de imagem**: direito exclusivo sobre a representação ou reprodução de uma pessoa
- **vida privada**: núcleo restrito da vida social aberto apenas para um grupo seleto de pessoas
- **intimidade**: núcleo mais restrito ainda da vida privada, referente ao momento íntimo da pessoa
- **proteção jurídica**: proteção legal oferecida pela lei para garantir os direitos de uma pessoa

### Referências legais
- Art. 21 do Código Civil

### Jurisprudência
- Súmula 123 do STJ

### Dicas de prova
- Foco na distinção entre vida privada e intimidade
- Análise da proteção jurídica oferecida pela lei para garantir os direitos de uma pessoa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direito Civil", "legal_refs": ["Art. 21 do Código Civil"], "jurisprudence": ["Súmula 123 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:31:51.363013+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=52", "doc_key": "c8789b41bf09f6684c3fafdc00434c96"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '49251b191efb34f55709827889d19feec364242f24a1a5d60866c6c768b5ef1e'),
  ('cpiuris2025::e69ea57438a8a0d62dc933b7efa83236', 'doutrina', 'cp_iuris', 'Direito Civil — Intimidade e Vida Privada', '## Intimidade e Vida Privada

A intimidade e a vida privada não são absolutas, mas sim sujeitas a ponderação. O direito à segurança pode se sobrepôr ao direito à privacidade em certos casos.

### Conceitos
- **Ponderação**: A necessidade de equilibrar o direito à vida privada com outros direitos, como a segurança.
- **Intimidade**: O direito à privacidade e à intimidade não são absolutos, mas sim sujeitas a ponderação.

### Referências legais
- Art. 19 do Código Civil
- Art. 20 do Código Civil

### Jurisprudência
