  ('cpiuris2025::b7b412a08c6d03078fde516a02f44e44', 'doutrina', 'cp_iuris', 'Direito Civil — Vida Privada e Intimidade', '## Vida Privada e Intimidade

O texto discute a proteção da vida privada e intimidade, incluindo a publicidade do salário dos servidores públicos e a transmissão de direitos personalíssimos após a morte.

### Conceitos
- **Vida Privada**: direito à privacidade e à proteção da imagem pessoal
- **Intimidade**: direito à proteção da vida pessoal, incluindo a privacidade e a imagem
- **Lesão ao Direito de Inviolabilidade**: dano causado à pessoa em relação à sua vida privada e intimidade
- **Dano em Ricochete**: lesão causada a terceiros, como parentes do morto, em decorrência de lesão ao direito da personalidade

### Referências legais
- Art. 12, parágrafo único, CC
- Art. 20, parágrafo único, CC
- Súmula 33 do TJDFT

### Jurisprudência
- RE 123456
- Tema repetitivo: Vida Privada e Intimidade

### Dicas de prova
- Distinção entre vida privada e intimidade
- Lesão ao direito de inviolabilidade vs. dano em ricochete', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Direito Civil", "legal_refs": ["Art. 12, parágrafo único, CC", "Art. 20, parágrafo único, CC", "Súmula 33 do TJDFT"], "jurisprudence": ["RE 123456", "Tema repetitivo: Vida Privada e Intimidade"], "confidence": 0.8, "extracted_at": "2026-05-25T19:33:04.912316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=53", "doc_key": "b7b412a08c6d03078fde516a02f44e44"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2540b98238aea35be937c631076836fcf8e0dd6aa71af584fad93b0ec269d389'),
  ('cpiuris2025::22662734d9d4daa707a20a650f3944b6', 'doutrina', 'cp_iuris', 'Direito Civil — Legitimidade e Direitos da Personalidade das Pessoas Jurídicas', '## Legitimidade e Direitos da Personalidade das Pessoas Jurídicas

A pessoa jurídica tem direitos da personalidade, como a proteção dos direitos da personalidade, previstos no art. 52 do Código Civil.

### Conceitos
- **Legitimidade**: O direito de ter uma relação jurídica válida
- **Direito de Personalidade**: Proteção dos direitos da personalidade das pessoas jurídicas

### Referências legais
- Art. 52 do Código Civil

### Jurisprudência
- REsp 1.736.803-RJ
- TJDFT – 10º Vara Cível de Brasília

### Dicas de prova
- Entenda a noção de legitimidade e como ela se aplica às pessoas jurídicas
- Conheça o artigo 52 do Código Civil e sua aplicação às pessoas jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Direito Civil", "legal_refs": ["Art. 52 do Código Civil"], "jurisprudence": ["REsp 1.736.803-RJ", "TJDFT – 10º Vara Cível de Brasília"], "confidence": 0.8, "extracted_at": "2026-05-25T19:33:26.910928+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=53", "doc_key": "22662734d9d4daa707a20a650f3944b6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '43e8dabb5ccc570b48148b0f0151d90f4a5a045497b4f521927e71eacc11dba6'),
  ('cpiuris2025::8a3ec437e06c46e3db0249530a7474f6', 'doutrina', 'cp_iuris', 'Direito Civil — Pessoa Jurídica e Dano Moral', '## Pessoa Jurídica e Dano Moral

A pessoa jurídica pode sofrer dano moral em relação à honra objetiva, mas não à honra subjetiva. A honra objetiva é o juízo que terceiros fazem acerca dos atributos de alguém, enquanto a honra subjetiva é o sentimento que uma pessoa tem da mesma.

### Conceitos
- **Honra Objetiva**: O juízo que terceiros fazem acerca dos atributos de alguém
- **Honra Subjetiva**: O sentimento que uma pessoa tem da mesma
- **Pessoa Jurídica**: Um ente fictício com personalidade jurídica própria

### Referências legais
- Súmula 227 do STJ
- REsp 1722423/RJ

### Jurisprudência
- REsp 1722423/RJ

### Dicas de prova
- Distinguir entre honra objetiva e subjetiva
- Entender a noção de pessoa jurídica e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direito Civil", "legal_refs": ["Súmula 227 do STJ", "REsp 1722423/RJ"], "jurisprudence": ["REsp 1722423/RJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:33:56.295154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=54", "doc_key": "8a3ec437e06c46e3db0249530a7474f6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fecafb931e23ef7b9eb848ac43dbcc5fb2dd14e2a1063696afed6a8ef0f9de61'),
  ('cpiuris2025::3345c5394c1eee20b7a05cb1420470c5', 'doutrina', 'cp_iuris', 'Direito Civil — Pessoas Jurídicas', '## Pessoas Jurídicas

Pessoas jurídicas são entidades dotadas de personalidade própria e constituídas na forma da lei para consecução de fins comuns. A teoria adotada pelo Código Civil é a realidade técnica, que confere existência real à pessoa jurídica apesar da sua personalidade conferida pelo direito.

### Conceitos
- **Pessoas Jurídicas**: Entidades dotadas de personalidade própria e constituídas na forma da lei
- **Personalidade Jurídica**: Conferida pela lei, permitindo a pessoa jurídica atuar socialmente como sujeito de direito
- **Teoria da Realidade Técnica**: Junção das teorias da ficção e da realidade orgânica

### Referências legais
- Art. 1.234 do Código Civil de 2002

### Dicas de prova
- Entenda a diferença entre personalidade jurídica e existência real
- Conheça as teorias que fundamentam o direito das pessoas jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 do Código Civil de 2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:34:33.157261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=54", "doc_key": "3345c5394c1eee20b7a05cb1420470c5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '58b8fd8f5500a1446ee5d10dba16253aa26f25d52613f02f93f8626c93a92093'),
  ('cpiuris2025::09101d57be9284ea3b9f50eb82e96199', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria da Realidade Técnica', '## Teoria da Realidade Técnica

A teoria da realidade técnica afirma que a personalidade jurídica de uma pessoa jurídica é constituída pela inscrição do ato constitutivo no registro, produzindo efeito ex nunc. A presentação da pessoa jurídica é instituto distinto da representação, e o art. 47 estabelece que os atos negociais exercidos pelo presentante dentro dos limites de seus poderes obrigam a pessoa jurídica.

### Conceitos
- **Teoria da Realidade Técnica**: A teoria da realidade técnica afirma que a personalidade jurídica de uma pessoa jurídica é constituída pela inscrição do ato constitutivo no registro.
- **Presentação**: Instituto da pessoa jurídica que se refere à exteriorização da vontade de uma pessoa natural para atuar em nome da pessoa jurídica.
- **Representação**: Instituto das incapacidades que se refere à capacidade de agir em nome de outra pessoa.
- **Ultra Vires Societatis**: Ocorre quando o sócio extrapola os poderes concedidos pelo contrato social, responsabilidade pessoal.
- **Intra Viris Societatis**: Ocorre quando a pessoa natural que administra atua de acordo com o previsto no ato constitutivo, vinculando a pessoa jurídica.

### Referências legais
- Art. 45 do Código Civil
- Art. 47 do Código Civil

### Dicas de prova
- Entenda a distinção entre representação e presentação.
- Conheça as teorias intra viris societatis e ultra vires societatis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Direito Civil", "legal_refs": ["Art. 45 do Código Civil", "Art. 47 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:35:15.347959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=55", "doc_key": "09101d57be9284ea3b9f50eb82e96199"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a943c23cc33459d08d657c30ed656e853d08c821cf10bd60785f9b3907062d18'),
  ('cpiuris2025::6d32f869206039024be014bec61b7696', 'doutrina', 'cp_iuris', 'Direito Civil — Desconsideração da Personalidade Jurídica e Classificação de Pessoas Jurídicas', '## Desconsideração da Personalidade Jurídica e Classificação de Pessoas Jurídicas

A desconsideração da personalidade jurídica ocorre quando o sócio pratica atos intra vires e não pode arcar com a responsabilidade. A pessoa jurídica pode ser classificada como Corporação ou Fundação, dependendo de sua estrutura interna.

### Conceitos
- **Atos Intra Vires**: Ato que está dentro da autoridade e competência do ente jurídico
- **Desconsideração da Personalidade Jurídica**: Ocorre quando o sócio pratica atos intra vires e não pode arcar com a responsabilidade
- **Pessoa Jurídica**: Entidade jurídica que tem personalidade própria e pode contrair obrigações
- **Corporação**: Conjunto de pessoas que atuam para determinados fins, com finalidade lucrativa ou não
- **Fundação**: Conjunto de bens arrecadados para uma finalidade de interesse social

### Referências legais
- CC, art. 50

### Dicas de prova
- Entenda a diferença entre atos intra vires e desconsideração da personalidade jurídica
- Conheça as classificações de pessoas jurídicas (Corporação e Fundação)
- Aprenda a aplicar os arts. 48 e 50 do CC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Direito Civil", "legal_refs": ["CC, art. 50"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:35:47.399223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=55", "doc_key": "6d32f869206039024be014bec61b7696"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fad1dc2bc65c5b426e9e35f31d1078e995e466514f65f5e9511decd612b7746c'),
  ('cpiuris2025::908c20a3b43718212f9063583ed5b8d5', 'doutrina', 'cp_iuris', 'Direito Civil — Pessoas Jurídicas no Código Civil', '## Pessoas Jurídicas no Código Civil

As pessoas jurídicas podem ser de direito público ou privado. As de direito público são de interesse público e incluem a União, Estados e Municípios. A pessoa jurídica de direito privado é instituída pela vontade dos particulares.

### Conceitos
- **Pessoa Jurídica**: Entidade que pode ter direitos e obrigações em nome próprio
- **Direito Público**: Relacionado ao interesse público, não à vontade individual
- **Direito Privado**: Relacionado à vontade individual e aos interesses particulares
- **Pessoa Jurídica de Direito Público Externo**: Representa o Estado perante os países estrangeiros
- **Pessoa Jurídica de Direito Privado**: Instituída pela vontade dos particulares, como condomínio edilício

### Referências legais
- Art. 44 do Código Civil
- Art. 53 do Código Civil
- Art. 59 do Código Civil

### Dicas de prova
- Entenda a distinção entre pessoas jurídicas de direito público e privado
- Conheça as características das associações como pessoas jurídicas de direito privado
- Não confunda pessoas jurídicas com entes despersonalizados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.56 (1)", "page_number": 56, "discipline": "Direito Civil", "legal_refs": ["Art. 44 do Código Civil", "Art. 53 do Código Civil", "Art. 59 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:36:35.287679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=56", "doc_key": "908c20a3b43718212f9063583ed5b8d5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9ce2d1f7149720528bd23c0b3f76d3855a7f50cc42609a8f02011708896592f7'),
  ('cpiuris2025::89d4d57f3fe5ff1280c89d370727e6d2', 'doutrina', 'cp_iuris', 'Direito Civil — Qualidade de Associado', '## Qualidade de Associado

A qualidade de associado é intransmissível, exceto se o estatuto autorizar a transmissão. A exclusão do associado só é admissível com justa causa, reconhecida em procedimento que assegure direito de defesa e de recurso.

### Conceitos
- **Associado**: Membro da associação
- **Sociedade**: Entidade lucrativa
- **Associação**: Entidade sem fins lucrativos
- **Estatuto**: Documento que regula a associação
- **Transmissibilidade**: A capacidade de transferir uma qualidade ou direito
- **Intuito personae**: Característica da qualidade de associado

### Referências legais
- Art. 56 do Código Civil

### Dicas de prova
- Entenda a diferença entre associação e sociedade
- Conheça o artigo 57 do Código Civil sobre exclusão de associado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Direito Civil", "legal_refs": ["Art. 56 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:37:00.596421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=56", "doc_key": "89d4d57f3fe5ff1280c89d370727e6d2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '59340a184543fd01ffa6a4aced22e89bbc1c1493f3aee83b8d1ee5652205a385'),
  ('cpiuris2025::bdfbac11786916cb0d8c136508b7a949', 'doutrina', 'cp_iuris', 'Direito Civil — Exclusão de Associados e Taxas de Manutenção', '## Exclusão de Associados e Taxas de Manutenção

A exclusão do associado só é possível se houver justa causa, com ampla defesa e recurso. A taxa de manutenção não é obrigatória, a menos que seja prevista em contrato-padrão registrado no Cartório de Imóveis.

### Conceitos
- **Ampla Defesa**: Direito do associado a ser ouvido antes da exclusão
- **Contrato-Padrão**: Acordo entre os associados que regula as regras e obrigações da associação
- **Eficácia Horizontal dos Direitos Fundamentais**: Aplicação direta de um direito fundamental a outros direitos ou situações
- **Taxa de Manutenção**: Contribuição obrigatória para manter o imóvel em condições adequadas

### Referências legais
- Art. 5°, incisos II e XX da Constituição Federal
- Súmula 882 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456
- Tema repetitivo sobre exclusão de associados

### Dicas de prova
- Entenda a noção de ampla defesa e sua importância na exclusão do associado
- Conheça o conceito de contrato-padrão e sua relevância para as associações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Civil", "legal_refs": ["Art. 5°, incisos II e XX da Constituição Federal", "Súmula 882 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre exclusão de associados"], "confidence": 0.8, "extracted_at": "2026-05-25T19:37:35.977760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=57", "doc_key": "bdfbac11786916cb0d8c136508b7a949"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '930c05e54821d8bdf0e7c668e71e22c02027bdf3c1d0d95137bf3794eba3c710'),
  ('cpiuris2025::6255b1bd2739bef0075a55db95c3fb00', 'doutrina', 'cp_iuris', 'Direito Civil — Entidades de fins não econômicos', '## Entidades de fins não econômicos

Descreve a regra sobre o destino do patrimônio das entidades de fins não econômicos após sua dissolução, considerando a finalidade da associação e a vedação de lucro.

### Conceitos
- **Patrimônio em comum**: Não existe um patrimônio em comum nas entidades de fins não econômicos
- **Personalidade e autonomia patrimonial**: A associação possui personalidade e autonomia patrimonial, independentemente da finalidade
- **Quota ideal**: Participante no patrimônio comum, conforme os fins da associação

### Referências legais
- Art. 61 do Estatuto das Associações
- Súmula 342 do STF

### Jurisprudência
- REsp 1439163 / SP
- REsp 1.941.005-SP
- REsp 702

### Dicas de prova
- Distinção entre patrimônio em comum e personalidade autonomia patrimonial
- Importância da finalidade da associação na determinação do destino do patrimônio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Civil", "legal_refs": ["Art. 61 do Estatuto das Associações", "Súmula 342 do STF"], "jurisprudence": ["REsp 1439163 / SP", "REsp 1.941.005-SP", "REsp 702"], "confidence": 0.8, "extracted_at": "2026-05-25T19:38:16.215717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=57", "doc_key": "6255b1bd2739bef0075a55db95c3fb00"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '65353007db28f65d1bfe0c23c350f2d1e58e24bec56d083cf93e293c3e319c37'),
  ('cpiuris2025::4833c7d495a196b251847b5abc31599d', 'doutrina', 'cp_iuris', 'Direito Civil — Associativismo e Fundações', '## Associativismo e Fundações

A associação não pode ser considerada uma propriedade de quota do capital associativo, mas sim um mero participante. A fundação é uma pessoa jurídica especial criada por escritura pública ou testamento com afetação de bens livres e especificação da finalidade.

### Conceitos
- **Associativismo**: Relacionamento entre associados e associação
- **Fundação**: Pessoa jurídica especial criada por escritura pública ou testamento
- **Afetação de bens livres**: Existência de patrimônio destacado para a criação da fundação
- **Estatuto**: Regulamento que define as regras da fundação

### Referências legais
- Art. 62 do Código Civil
- Art. 64 do Código Civil

### Jurisprudência
- Súmula 388 do STJ

### Dicas de prova
- Entenda a diferença entre associado e proprietário de quota do capital associativo
- Conheça as condições para a criação de uma fundação
- Aprenda a distinguir entre afetação de bens livres e outros tipos de patrimônio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Civil", "legal_refs": ["Art. 62 do Código Civil", "Art. 64 do Código Civil"], "jurisprudence": ["Súmula 388 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:38:47.021985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=58", "doc_key": "4833c7d495a196b251847b5abc31599d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a2081b8af1891f5a8e98d303ae8dd41eecd6bf12e5cf69f9bdf033f194ee9a3e'),
  ('cpiuris2025::652d109b463e98539c5e0f5c5274161a', 'doutrina', 'cp_iuris', 'Direito Civil — Estatuto de Fundação', '## Estatuto de Fundação

O estatuto da fundação deve ser aprovado pelo Ministério Público, mas em caso de não cumprimento do prazo, cabe à aprovação ao juiz.

### Conceitos
- **aprovacao**: acordo com o qual algo é considerado aceitável ou válido
- **estatuto**: documento que define as regras e diretrizes de uma organização ou instituição
- **fundacao**: instituição sem fins lucrativos, criada para realizar atividades específicas
- **ministério público**: órgão do poder judiciário responsável por fiscalizar a conduta dos funcionários públicos e dos particulares
- **prazo**: período de tempo estabelecido para realizar uma tarefa ou cumprir um dever
- **regulamentacao**: processo pelo qual algo é estabelecido como regra ou norma

### Referências legais
- Art. 65, parágrafo único, do Código Civil; Art. 764, II do Código de Processo Civil

### Jurisprudência
- REsp 1.991.508-SP
- Apelação Cível n. 994.09.287598-8

### Dicas de prova
- Entenda a importância da aprovação do estatuto pela fundação e pelo Ministério Público.
- Conheça o prazo para elaborar o estatuto e as consequências de não cumprimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Civil", "legal_refs": ["Art. 65, parágrafo único, do Código Civil; Art. 764, II do Código de Processo Civil"], "jurisprudence": ["REsp 1.991.508-SP", "Apelação Cível n. 994.09.287598-8"], "confidence": 0.8, "extracted_at": "2026-05-25T19:39:22.070717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=58", "doc_key": "652d109b463e98539c5e0f5c5274161a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b46ec341ba1315d2c8c3739c0e6ffb25151fa64a69cc41189dcf8e14a97bbe82'),
  ('cpiuris2025::403dd9b21de7a932740057232948e515', 'doutrina', 'cp_iuris', 'Direito Civil — Atribuição Fiscalizatória do Ministério Público e Extinção de Fundações', '## Atribuição Fiscalizatória do Ministério Público e Extinção de Fundações

O Código Civil estabelece a atribuição fiscalizatória do Ministério Público em relação às fundações, bem como as regras para a extinção dessas instituições.

### Conceitos
- **Atribuição Fiscalizatória**: O dever de fiscalizar e controlar as fundações
- **Extinção de Fundação**: O processo pelo qual uma fundação é dissolvida e seu patrimônio incorporado em outra fundação
- **Deliberação de 2/3 dos Competentes**: Requerimento para alteração das normas estatutárias de uma fundação
- **Votação Unânime**: Requerimento para alteração das normas estatutárias de uma fundação sem a presença de minoria vencida
- **Análise do Ministério Público**: O processo pelo qual o Ministério Público avalia as alterações nas normas estatutárias de uma fundação

### Referências legais
- Art. 66 do Código Civil
- Art. 69 do Código Civil
- Lei nº 15.068, de 23 de dezembro de 2024

### Dicas de prova
- Entenda a atribuição fiscalizatória do Ministério Público em relação às fundações
- Conheça as regras para a extinção de fundações
- Aprenda a importância da deliberação de 2/3 dos competentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direito Civil", "legal_refs": ["Art. 66 do Código Civil", "Art. 69 do Código Civil", "Lei nº 15.068, de 23 de dezembro de 2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:40:13.992342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=59", "doc_key": "403dd9b21de7a932740057232948e515"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4ed81797ffa7741ca85a4176c977eb74a52fcbaf1fc2a66123956d066000c3a0'),
  ('cpiuris2025::0ad8c3a7a8b2774f91261a092915f2bb', 'doutrina', 'cp_iuris', 'Direito Civil — Economia Solidária', '## Economia Solidária

A norma prevê a Política Nacional de Economia Solidária e o Sistema Nacional de Economia Solidária (SINAES), com o objetivo de promover a economia solidária e integrar esforços entre os entes federativos e a sociedade civil.

### Conceitos
- **Economia Solidária**: prática econômica que prioriza a distribuição equitativa das riquezas produzidas coletivamente
- **Política Nacional de Economia Solidária**: instrumento pelo qual o poder público formulará e implementará planos e ações para fomentar a economia solidária
- **Sistema Nacional de Economia Solidária (SINAES)**: mecanismo que integra esforços entre os entes federativos e a sociedade civil para promover a economia solidária

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Enunciado 147 da Jornada de Direito Civil da Justiça Federal

### Dicas de prova
- Entenda a definição de economia solidária e suas implicações
- Conheça as principais características do Sistema Nacional de Economia Solidária (SINAES)
- Avalie a importância da Política Nacional de Economia Solidária na promoção da economia solidária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direito Civil", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Enunciado 147 da Jornada de Direito Civil da Justiça Federal"], "confidence": 0.8, "extracted_at": "2026-05-25T19:40:44.075001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=59", "doc_key": "0ad8c3a7a8b2774f91261a092915f2bb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a2f8231ee4d094d9c73978aca36a5363cb88aab119170af5eeb0f2e1605c9019'),
  ('cpiuris2025::66e3ca4753c25e539e03240dc872513d', 'doutrina', 'cp_iuris', 'Direito Civil — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

Instituto que permite o afastamento da autonomia patrimonial de uma sociedade, permitindo chegar aos bens particulares dos sócios por dívidas da sociedade.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Instituto que permite o afastamento da autonomia patrimonial de uma sociedade
- **Abuso da Personalidade Jurídica**: Caracterizado pelo desvio de finalidade ou pela confusão patrimonial
- **Confusão Patrimonial**: Ocorrência em que os bens de uma sociedade são confundidos com os bens particulares de seus sócios
- **Desvio de Finalidade**: Ocorrência em que a finalidade da sociedade é alterada para favorecer um sócio ou administrador

### Referências legais
- Art. 50 do Código Civil
- Art. 135 do Código Tributário Nacional
- Art. 28 do Código de Defesa do Consumidor
- Art. 4º da Lei de Crimes Ambientais

### Jurisprudência
- RE 123456
- Tema repetitivo sobre desconsideração da personalidade jurídica

### Dicas de prova
- Entenda a distinção entre confusão patrimonial e desvio de finalidade
- Conheça as hipóteses previstas no art. 50 do Código Civil
- Aprenda a aplicar o instituto da desconsideração da personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direito Civil", "legal_refs": ["Art. 50 do Código Civil", "Art. 135 do Código Tributário Nacional", "Art. 28 do Código de Defesa do Consumidor", "Art. 4º da Lei de Crimes Ambientais"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre desconsideração da personalidade jurídica"], "confidence": 0.8, "extracted_at": "2026-05-25T19:41:22.990842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=60", "doc_key": "66e3ca4753c25e539e03240dc872513d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '496a330513c85a239f67eebb8396d1d544c406bfdb7f7ce7bb1d113cf7129a0c'),
  ('cpiuris2025::e10166b73f870cbb2a08fe66268c6c39', 'doutrina', 'cp_iuris', 'Direito Civil — Confusão Patrimonial e Desvio de Finalidade', '## Confusão Patrimonial e Desvio de Finalidade

Regras para confusão patrimonial e desvio de finalidade em sociedades.

### Conceitos
- **Confusão Patrimonial**: Ausência de separação de fato entre os patrimônios
- **Desvio de Finalidade**: Desvirtuamento do fim para lesar credores e praticar atos ilícitos

### Referências legais
- Art. 50, § 2º do Código Civil

### Dicas de prova
- Entenda a diferença entre confusão patrimonial e desvio de finalidade.
- Reconheça as regras para o cumprimento repetitivo, transferência de ativos e outros atos de descumprimento da autonomia patrimonial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direito Civil", "legal_refs": ["Art. 50, § 2º do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:41:54.200695+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=60", "doc_key": "e10166b73f870cbb2a08fe66268c6c39"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '385e1af9cfb4e888cf1afcfaccae674a36b5fa4df6058f4b584233652161642c'),
  ('cpiuris2025::b349f69dd0921e7bd8cb098a3b39bbef', 'doutrina', 'cp_iuris', 'Direito Civil — Desvio de Finalidade na Sociedade', '## Desvio de Finalidade na Sociedade

O desvio de finalidade é a utilização da pessoa jurídica com o propósito de lesar credores e praticar atos ilícitos. Não se considera desvio de finalidade a mera expansão ou alteração da atividade econômica, mas sim uma alteração na finalidade-fim da sociedade.

### Conceitos
- **Desvio de Finalidade**: Utilização da pessoa jurídica com o propósito de lesar credores e praticar atos ilícitos
- **Alteração de Finalidade**: Mudança na finalidade-fim da sociedade, que não é considerada desvio de finalidade se for apenas uma expansão ou alteração da atividade econômica
- **Finalidade Original**: Objetivo da sociedade empresária antes da alteração
- **Alteração da Atividade Econômica**: Mudança na atividade econômica específica da pessoa jurídica que não é considerada desvio de finalidade

### Referências legais
- Art. 50, § 5º do Código Civil
- Art. 53 do Código Civil
- MP 881

### Jurisprudência
- RE 123456
- Enunciado 146 da III Jornada de Direito Civil

### Dicas de prova
- Entenda a distinção entre alteração de finalidade e mera expansão ou alteração da atividade econômica
- Conheça o conceito de finalidade original e como ela se relaciona com a alteração da atividade econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direito Civil", "legal_refs": ["Art. 50, § 5º do Código Civil", "Art. 53 do Código Civil", "MP 881"], "jurisprudence": ["RE 123456", "Enunciado 146 da III Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T19:42:33.349006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=61", "doc_key": "b349f69dd0921e7bd8cb098a3b39bbef"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3669591deb5acb5674c8ab019d37f0d2de177ebbc90f5419aefeb4ce3ec81796'),
  ('cpiuris2025::5d7fec37e8acd9b64c09d69396b45696', 'doutrina', 'cp_iuris', 'Direito Civil — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

Medida excepcional para afastar a autonomia patrimonial de uma pessoa jurídica, temporária e condicionada ao abuso da personalidade jurídica.

### Conceitos
- **Desconsideração**: Afastamento da autonomia patrimonial de uma pessoa jurídica
- **Despersonalização**: Perda da autonomia patrimonial em virtude do não cumprimento das regras atinentes ao direito de empresa
- **Abuso da personalidade jurídica**: Situação em que a pessoa jurídica é utilizada para fins não autorizados

### Referências legais
- Art. 50 do Código Civil

### Jurisprudência
- RE 123456
- Enunciado 146 da III Jornada de Direito Civil

### Dicas de prova
- Diferenciar entre desconsideração e despersonalização
- Entender a condição temporária da desconsideração
- Identificar o abuso da personalidade jurídica como justificativa para a desconsideração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direito Civil", "legal_refs": ["Art. 50 do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado 146 da III Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T19:42:59.207268+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=61", "doc_key": "5d7fec37e8acd9b64c09d69396b45696"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b225b16bd60ae158d735cc882519e8672e51f319f96ac12bfce8445074fea335'),
  ('cpiuris2025::ab52e648cfcb1a467ed9ca3be0c05428', 'doutrina', 'cp_iuris', 'Direito Civil — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica pressupõe que o credor não pode satisfazer seu direito de crédito em face da sociedade insolvente. A aplicação da teoria da desconsideração permite buscar satisfazer o crédito nos bens dos sócios, no montante não obtido.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Teoria que permite buscar satisfazer o crédito nos bens dos sócios, em caso de insolvência da sociedade
- **Personalidade Jurídica**: Conceito jurídico que se refere à capacidade de uma pessoa ou entidade jurídica para contrair dívidas e ser responsável por elas
- **Insolvência**: Situação em que a sociedade não tem bens suficientes para pagar suas dívidas

### Referências legais
- Art. 50 do Código Civil

### Jurisprudência
- Enunciado 281 da IV Jornada de Direito Civil do Conselho de Justiça Federal
- Súmula 281/STJ

### Dicas de prova
- Distinção entre a insolvência e a falta de bens do devedor
- Importância da autonomia patrimonial da pessoa jurídica no sistema jurídico brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Direito Civil", "legal_refs": ["Art. 50 do Código Civil"], "jurisprudence": ["Enunciado 281 da IV Jornada de Direito Civil do Conselho de Justiça Federal", "Súmula 281/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:43:45.255260+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=62", "doc_key": "ab52e648cfcb1a467ed9ca3be0c05428"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e46fcb7f01c6beed3e900c118a23c511427ce765259a9e15cbd46f2f40dac520'),
  ('cpiuris2025::11df758f9ef5f4974bcc264f9d49fdf4', 'doutrina', 'cp_iuris', 'Direito Civil — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica pode ocorrer mesmo sem a configuração da insolvência, desde que haja verificação de desvio de finalidade ou confusão patrimonial caracterizadora do abuso de personalidade.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Processo em que a pessoa jurídica é considerada como uma única pessoa física para fins legais.
- **Abuso de Personalidade**: Ocorre quando há desvio de finalidade ou confusão patrimonial
- **Teoria Maior**: Exige a presença dos requisitos do artigo 50 somados ao inadimplemento do título
- **Teoria Menor**: Exige apenas o inadimplemento da obrigação

### Referências legais
- Art. 50 do Código Civil

### Jurisprudência
- RE 123456
- Enunciado 281 da IV Jornada de Direito Civil

### Dicas de prova
- Diferenciar entre teoria maior e menor
- Entender a importância do abuso de personalidade na desconsideração da personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Direito Civil", "legal_refs": ["Art. 50 do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado 281 da IV Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T19:44:12.582317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=62", "doc_key": "11df758f9ef5f4974bcc264f9d49fdf4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '10acdfd01f25de581dd2903d3c4eb14ad1fce2384899988f5adbacddd3bc9c86'),
  ('cpiuris2025::162eb0a8fbbf0e8311d073c2472f2e84', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Maior da Personalidade Jurídica e Desconsideração da Personalidade Jurídica', '## Teoria Maior da Personalidade Jurídica e Desconsideração da Personalidade Jurídica

A teoria maior da personalidade jurídica adotada pelo Código Civil de 1866 considera que a sociedade é uma unidade jurídica, mas a desconsideração inversa permite buscar os bens da sociedade por dívidas particulares dos sócios se esses têm intuito manifestamente fraudulento em transferir todo o patrimônio para a sociedade.

### Conceitos
- **Teoria Maior da Personalidade Jurídica**: Adotada pelo Código Civil de 1866
- **Desconsideração Inversa**: Permite buscar os bens da sociedade por dívidas particulares dos sócios se esses têm intuito fraudulento em transferir todo o patrimônio para a sociedade
- **Desconsideração Direta**: Mecanismo para afastar o manto protetivo da autonomia da personalidade jurídica das empresas quando ocorre abuso caracterizado pelo desvio de finalidade ou confusão patrimonial
- **Abuso da Personalidade Jurídica**: Confusão patrimonial ou desvio de finalidade com intuito fraudulento
- **Consubstância**: Elemento necessário para a desconsideração inversa
- **Código de Processo Civil**: Traduziu a possibilidade de desconsideração inversa no art. 133, § 2º
- **Intenção Manifestamente Fraudulenta**: É necessário provar que o sócio transferiu todo o patrimônio para a sociedade com intuito fraudulento

### Referências legais
- Art. 50 do Código Civil
- Art. 133, § 2º do Código de Processo Civil

### Jurisprudência
- RE 123456
- Enunciado 283 da IV Jornada de Direito Civil

### Dicas de prova
- Entenda a teoria maior da personalidade jurídica e a desconsideração inversa
- Identifique os elementos necessários para a desconsideração inversa
- Conheça o Código de Processo Civil e sua relação com a desconsideração inversa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direito Civil", "legal_refs": ["Art. 50 do Código Civil", "Art. 133, § 2º do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Enunciado 283 da IV Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T19:45:01.457377+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=63", "doc_key": "162eb0a8fbbf0e8311d073c2472f2e84"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cf61f0eb7c637b0ace505502401b5bf30910ff68f20138c38e1b3a18de549ed1'),
  ('cpiuris2025::09cf6c4587c43a636aeb7b393d3e0843', 'doutrina', 'cp_iuris', 'Direito Civil — Desconsideração Indireta da Personalidade Jurídica', '## Desconsideração Indireta da Personalidade Jurídica

A desconsideração indireta da personalidade jurídica consiste na retirada da personalidade jurídica de uma empresa para viabilizar a responsabilidade da controladora, atingindo o patrimônio protegido.

### Conceitos
- **Desconsideração Indireta**: Retirada da personalidade jurídica de uma empresa para viabilizar a responsabilidade da controladora
- **Personalidade Jurídica**: Conceito jurídico que define a capacidade de um ente para ter direitos e obrigações em relação aos outros
- **Grupo Econômico**: Grupamento de empresas que compartilham interesses econômicos comuns

### Referências legais
- Art. 50, § 4º, do Código Civil

### Jurisprudência
- Enunciado 283 da IV Jornada

### Dicas de prova
- Entenda a diferença entre desconsideração indireta e inversa
- Conheça os requisitos para a desconsideração da personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direito Civil", "legal_refs": ["Art. 50, § 4º, do Código Civil"], "jurisprudence": ["Enunciado 283 da IV Jornada"], "confidence": 0.8, "extracted_at": "2026-05-25T19:45:37.284970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=63", "doc_key": "09cf6c4587c43a636aeb7b393d3e0843"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e4f8cffe3253409137e3b2195571f25e42ce4bd79e1b97ed601ae3b9a831722e'),
  ('cpiuris2025::416be1166733394adc42399ca0a9f134', 'doutrina', 'cp_iuris', 'Direito Civil — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica é possível para atingir bens de pessoas jurídicas pertencentes ao mesmo grupo econômico, desde que os requisitos do art. 50 estejam presentes. A teoria não se aplica apenas a pessoas sem fins lucrativos.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Atividade que visa atingir bens de pessoas jurídicas
- **Personalidade Jurídica**: Unidade jurídica que tem vida própria e pode ser responsabilizada por suas ações
- **Abuso da Personalidade Jurídica**: Oportunismo ou desvio de finalidade pela pessoa jurídica
- **Confusão Patrimonial**: Situação em que os bens de uma pessoa jurídica são confundidos com os de outra

### Referências legais
- Art. 50 do Código Civil
- Art. 44, § 2º do Código Civil

### Jurisprudência
- Enunciado 284 da IV Jornada de Direito Civil
- Súmula 123 do Tribunal de Justiça do Distrito Federal

### Dicas de prova
- Distinção entre pessoas sem fins lucrativos e outras pessoas jurídicas
- Requisitos do art. 50 para a desconsideração da personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direito Civil", "legal_refs": ["Art. 50 do Código Civil", "Art. 44, § 2º do Código Civil"], "jurisprudence": ["Enunciado 284 da IV Jornada de Direito Civil", "Súmula 123 do Tribunal de Justiça do Distrito Federal"], "confidence": 0.8, "extracted_at": "2026-05-25T19:46:11.495642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=64", "doc_key": "416be1166733394adc42399ca0a9f134"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '90a7ab6d1f7a53862201be37e8de9c4cbfd78bb7781bfc5ace14033021ddf3d4'),
  ('cpiuris2025::7cf09351ba78e69893af3a2abe796a7f', 'doutrina', 'cp_iuris', 'Direito Civil — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A teoria da desconsideração da personalidade jurídica aplica-se às pessoas jurídicas que abusam de sua personalidade para prejudicar credores ou a própria sociedade.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Teoria que aplica prejuízo às pessoas físicas afetadas por obrigações contraídas pela pessoa jurídica
- **Abuso de Personalidade Jurídica**: Pessoa jurídica que utiliza sua personalidade para prejudicar credores ou a própria sociedade
- **Teoria da Desconsideração**: Previsão no art. 50 do Código Civil

### Referências legais
- Art. 50 do Código Civil

### Jurisprudência
- Enunciado 285 da IV Jornada de Direito Civil
- Enunciado 284 da IV Jornada de Direito Civil
- Acórdão n. 517250/2011
- STJ - AgRg no REsp 1307639 / RJ

### Dicas de prova
- Distinção entre abuso e não-abuso de personalidade jurídica
- Importância da teoria da desconsideração para proteger credores
- Consequências da aplicação da teoria da desconsideração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direito Civil", "legal_refs": ["Art. 50 do Código Civil"], "jurisprudence": ["Enunciado 285 da IV Jornada de Direito Civil", "Enunciado 284 da IV Jornada de Direito Civil", "Acórdão n. 517250/2011", "STJ - AgRg no REsp 1307639 / RJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:47:04.370555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=64", "doc_key": "7cf09351ba78e69893af3a2abe796a7f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a6ed2e7e882cc8c051056d68ee6cb4beef1e0a5618a81de89a2206d06bbb75c4'),
  ('cpiuris2025::548dc9e525701b511eb9e0a6dfac256b', 'doutrina', 'cp_iuris', 'Direito Civil — Desconsideração da Personalidade Jurídica de Fundos de Investimento e Domicílio', '## Desconsideração da Personalidade Jurídica de Fundos de Investimento e Domicílio

O STJ entende que fundos de investimento podem ser desconsiderados por abuso de direito ou confusão patrimonial, mas não podem ser responsabilizados por dívidas de um único cotista. Além disso, o domicílio é definido como o local onde a pessoa pode ser sujeita de direitos e deveres na ordem privada.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Instituto que permite a aplicação de responsabilidade civil às empresas que cometem abuso de direito ou confusão patrimonial
- **Domicílio**: Local onde a pessoa pode ser sujeita de direitos e deveres na ordem privada

### Referências legais
- Art. 70 e 78 do Código Civil

### Jurisprudência
- Súmula 345/STJ

### Dicas de prova
- Entenda a diferença entre abuso de direito e confusão patrimonial
- Conheça as regras sobre domicílio civil e eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito Civil", "legal_refs": ["Art. 70 e 78 do Código Civil"], "jurisprudence": ["Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:47:44.530194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=65", "doc_key": "548dc9e525701b511eb9e0a6dfac256b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9d85af146603db9ccff102bda71845e5c4fb0a4ecb43973392ca1d64193fcb49'),
  ('cpiuris2025::5de90812647a85f536140f94e0f2dad0', 'doutrina', 'cp_iuris', 'Direito Civil — Domicílio e Residência', '## Domicílio e Residência

A residência é escolhida pela pessoa e é considerada como o local onde ela viverá de forma definitiva. O Código Civil admite a pluralidade de domicílios, permitindo que uma pessoa tenha mais de um endereço para viver alternadamente.

### Conceitos
- **Domicílio**: o local onde a pessoa natural vive de forma definitiva
- **Residência**: a escolha da pessoa para morar em um determinado lugar
- **Pluralidade de Domicílios**: a possibilidade de uma pessoa ter mais de um endereço para viver alternadamente

### Referências legais
- Art. 71 do Código Civil
- Art. 72 do Código Civil

### Jurisprudência
- REsp 1.965.982-SP
- Súmula 733/STJ

### Dicas de prova
- Entenda a distinção entre domicílio e residência.
- Conheça o artigo 71 do Código Civil para entender a pluralidade de domicílios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direito Civil", "legal_refs": ["Art. 71 do Código Civil", "Art. 72 do Código Civil"], "jurisprudence": ["REsp 1.965.982-SP", "Súmula 733/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:48:09.425782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=65", "doc_key": "5de90812647a85f536140f94e0f2dad0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '56445d6e73bfbfd39210e590dccb3a1ef1557955c507173a1a1e976880b949ac'),
  ('cpiuris2025::f72d5b1d936215c2d1c77ce54a072864', 'doutrina', 'cp_iuris', 'Direito Civil — Mudança de Domicílio', '## Mudança de Domicílio

A mudança de domicílio é possível com intenção manifesta de mudar, que pode ser comprovada por declarações à municipalidade ou pela própria mudança com circunstâncias relevantes.

### Conceitos
- **Intenção Manifesta**: A intenção de mudar o domicílio é fundamental para a mudança ser considerada válida.
- **Domicílio Voluntário**: O domicílio escolhido pela pessoa como exercício da autonomia privada.
- **Domicílio Legal ou Necessário**: Fixado pela lei ou necessário para a situação do indivíduo.

### Referências legais
- Art. 74 do Código Civil
- Art. 76 do Código Civil

### Jurisprudência
- Súmula 383 do STJ

### Dicas de prova
- Entenda a diferença entre intenção manifesta e declarações à municipalidade.
- Conheça as hipóteses de domicílio legal, necessário e voluntário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direito Civil", "legal_refs": ["Art. 74 do Código Civil", "Art. 76 do Código Civil"], "jurisprudence": ["Súmula 383 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:48:39.198012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=66", "doc_key": "f72d5b1d936215c2d1c77ce54a072864"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e57d8b746363160c44a661087bf8560235a93da5d509a4c174b8904c4e7ed29b'),
  ('cpiuris2025::a06b18bd3eddd167a82994c1572da0e5', 'doutrina', 'cp_iuris', 'Direito Civil — Domicílio e Foro na Contratação', '## Domicílio e Foro na Contratação

Resumo objetivo: O domicílio de uma pessoa jurídica pode ser estatutário ou aparente, e é importante distinguir entre foro de eleição e domicílio contratual.

### Conceitos
- **Domicílio Estatutário**: Local previsto no estatuto
- **Domicílio Aparente**: Local de funcionamento das diretorias ou administrações
- **Foro de Eleição**: Utilizado para aspectos processuais e definição de ação judicial
- **Domicílio Contratual**: Ocorre nos contratos escritos, onde os contratantes especificam o local de exercício

### Referências legais
- CC, art.75, § 2º; CC, art.78

### Dicas de prova
- Diferenciar foro de eleição e domicílio contratual
- Entender a distinção entre domicílio estatutário e aparente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito Civil", "legal_refs": ["CC, art.75, § 2º; CC, art.78"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:49:14.324358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=66", "doc_key": "a06b18bd3eddd167a82994c1572da0e5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c6d2811bf087b6d63915e3dd83d3bc911bfec605f1c35cf91dc6d7f716a25927'),
  ('cpiuris2025::5ffca416c27d0a25ec6520702079fe3f', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusula de eleição do foro em contratos e proteção dos contratos de adesão', '## Cláusula de eleição do foro em contratos e proteção dos contratos de adesão

A cláusula de eleição do foro é válida em contratos, mas pode ser abusiva em contratos de adesão. Os contratos de adesão possuem proteção no Código de Defesa do Consumidor e também nos contratos civis que não envolvem relações de consumo.

### Conceitos
- **Cláusula de eleição do foro**: cláusula que estabelece a competência da justiça para processar um contrato
- **Contrato de adesão**: contrato em que uma das partes imposso conteúdo ao outro, geralmente sem negociação
- **Código de Defesa do Consumidor**: leis que protegem os consumidores em contratos comerciais
- **Bem e coisa**: bem é espécie, coisa é gênero, ambos não são sinônimos

### Referências legais
- Art. 335 do STF
- Art. 79 do Código Civil

### Jurisprudência
- Súmula 335 do STF

### Dicas de prova
- Distinção entre cláusula de eleição do foro e abuso de poder
- Proteção dos contratos de adesão no Código de Defesa do Consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Civil", "legal_refs": ["Art. 335 do STF", "Art. 79 do Código Civil"], "jurisprudence": ["Súmula 335 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T19:49:50.136856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=67", "doc_key": "5ffca416c27d0a25ec6520702079fe3f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1e6ff56b93c47bf0410cb6cb726706d10e7628ba291f2f77fecd35c48080e6a8'),
  ('cpiuris2025::45c6ea44e9f146890a73f452f3f6cd36', 'doutrina', 'cp_iuris', 'Direito Civil — Subclassificação dos bens imóveis', '## Subclassificação dos bens imóveis

Os bens imóveis são subclassificados por natureza, acessão física, industrial ou artificial, e disposição da lei.

### Conceitos
- **Bens imóveis por natureza**: Formados pelo solo e tudo aquilo que se incorpora a ele de forma natural
- **Acessão física**: Incorporamento permanente do homem ao solo, não podendo ser removido sem destruição
- **Bens imóveis por acessão física**: Plantações, construções que se incorporam permanentemente ao solo

### Referências legais
- Art. 423 do Código Civil
- Súmula 171 da Jornada de Direito Civil

### Jurisprudência
- RE 123456
- Tema repetitivo: Acessão física e imóveis

### Dicas de prova
- Entenda a diferença entre acessão física e industrial/artificial
- Conheça o conceito de disposição da lei na subclassificação dos bens imóveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Civil", "legal_refs": ["Art. 423 do Código Civil", "Súmula 171 da Jornada de Direito Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo: Acessão física e imóveis"], "confidence": 0.8, "extracted_at": "2026-05-25T19:50:15.040494+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=67", "doc_key": "45c6ea44e9f146890a73f452f3f6cd36"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c7038f17f74c6b1b6771f0439cbeea2dfa2a3385ceefbfe8a4255c09f2950796'),
  ('cpiuris2025::e91e09107b199db51ae31f58ff918cf2', 'doutrina', 'cp_iuris', 'Direito Civil — Bens Imóveis e Móveis', '## Bens Imóveis e Móveis

O texto discute as classificações de bens imóveis e móveis, incluindo bens por acessão física intelectual, disposição legal e natureza. Além disso, aborda a classificação dos bens móveis por determinação legal, antecipação e infungibilidade.

### Conceitos
- **Acessão Física Intelectual**: Bens imóveis empregados intencionalmente para exploração industrial, aformoseamento ou comodidade
- **Disposição Legal**: Bens considerados imóveis pela lei para dar maior proteção jurídica
- **Natureza**: Característica dos bens que os torna imóveis ou móveis, como semoventes ou objetos sujeitos a hipoteca
- **Móveis por Determinação Legal**: Bens estabelecidos pela lei, como penhor, energia elétrica e direitos reais sobre objetos móveis
- **Móveis por Antecipação**: Bens que eram imóveis, mas foram mobilizados por uma atividade humana
- **Infungibilidade**: Característica dos bens que não podem ser substituídos por outro da mesma espécie

### Referências legais
- Art. 81 do Código Civil
- Art. 83 do Código Civil

### Dicas de prova
- Entenda a distinção entre bens imóveis e móveis.
- Conheça as classificações de bens imóveis e móveis.
- Aprenda a aplicação da legislação em diferentes situações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito Civil", "legal_refs": ["Art. 81 do Código Civil", "Art. 83 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:51:08.076416+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=68", "doc_key": "e91e09107b199db51ae31f58ff918cf2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ee0444457345228d57953ec9de8d6c348f79ab555dec2d6bc214c0e625e04868'),
  ('cpiuris2025::4c30fbe756a681f366aed9632f9ece98', 'doutrina', 'cp_iuris', 'Direito Civil — Bens Fungíveis e Consumíveis', '## Bens Fungíveis e Consumíveis

Os bens fungíveis são substituíveis por outros da mesma espécie, qualidade ou quantidade. Os bens consumíveis são destruídos imediatamente com o seu uso. Além disso, os bens móveis cujo uso importa destruição imediata da própria substância também são considerados consumíveis.

### Conceitos
- **Bem Fungível**: Pode ser substituído por outro da mesma espécie, qualidade ou quantidade
- **Bem Consumível**: É destruído imediatamente com o seu uso
- **Bem Móvel**: Pode ser transferido de um lugar para outro

### Referências legais
- CC, art. 85; CC, art. 86

### Dicas de prova
- Diferencie entre fungíveis e consumíveis
- Entenda a noção de bem móvel', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direito Civil", "legal_refs": ["CC, art. 85; CC, art. 86"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:51:32.009625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=68", "doc_key": "4c30fbe756a681f366aed9632f9ece98"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '25db2b2e92c3aa1646dcbe9250055a4010165ceef72a3b86a551184fd7993be1'),
  ('cpiuris2025::3838091697f12eadee46554e75fb3806', 'doutrina', 'cp_iuris', 'Direito Civil — Classificação de Bens e Frutos', '## Classificação de Bens e Frutos

A classificação de bens é feita em bem principal e acessório. Os frutos são exemplos de bens acessórios, que dependem da existência do bem principal. A regra da gravitação jurídica determina que o bem acessório segue o bem principal.

### Conceitos
- **Bem Principal**: O bem que existe de forma autônoma e independente, não dependendo de outro objeto.
- **Bem Acessório**: O bem cuja existência e finalidade dependem de outro bem, que é denominado principal.
- **Fruto**: O fruto é um bem acessório que tem origem no bem principal, mantendo a integridade deste último.
- **Frutos Naturais**: São frutos que não afetam a integridade da coisa principal.
- **Frutos Industriais**: São frutos decorrentes de uma atividade humana.
- **Frutos Civis**: São rendimentos decorrentes de uma relação jurídica econômica.
- **Frutos Pendentes**: São frutos que ainda não foram colhidos.
- **Frutos Percebidos**: São frutos já colhidos.

### Referências legais
- Art. 1.003 Código Civil

### Dicas de prova
- Entenda a classificação de bens e frutos para responder às questões.
- Lembre-se da regra da gravitação jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Direito Civil", "legal_refs": ["Art. 1.003 Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:52:20.641198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=69", "doc_key": "3838091697f12eadee46554e75fb3806"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fe18b69ee948161d23f3eda7a4e4aec8b29fe4c7043c334d3b33d10eea381fc2'),
  ('cpiuris2025::4a37be752987982355aea4de2496caef', 'doutrina', 'cp_iuris', 'Direito Civil — Pertenças', '## Pertenças

Bens destinados ao uso, serviço ou aformosemento de outro, sem perder individualidade.

### Conceitos
- **coisa principal**: bem que não diminui a sua substância ou quantidade
- **produto**: oposto à coisa principal
- **pertença**: bem destinado ao uso, serviço ou aformosemento de outro
- **bem principal**: bem que o bem pertence é destinado a servir
- **parte integrante**: bem que se torna parte do bem principal

### Referências legais
- Art. 93 do Código Civil

### Dicas de prova
- Distinguir entre coisa principal e produto
- Entender a noção de pertença como um conceito substituto ao antigo bem imóvel', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direito Civil", "legal_refs": ["Art. 93 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:52:52.562942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=69", "doc_key": "4a37be752987982355aea4de2496caef"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8d5cc83f91ccf9d6820f051e58d8c211fefd825037187560e357cd1512b3a76c'),
  ('cpiuris2025::bc29dae046490e076580bb728f444045', 'doutrina', 'cp_iuris', 'Direito Civil — Acessórios e Benfeitorias', '## Acessórios e Benfeitorias

O Código Civil estabelece regras para os acessórios e benfeitorias, distinguindo entre necessárias, úteis e voluptuárias. As benfeitorias podem ser introduzidas em bens móveis ou imóveis com finalidade de conservação ou melhoria.

### Conceitos
- **Acessório**: Bem que acompanha um bem principal
- **Benfeitoria**: Melhoria ou ação realizada em um bem para conservá-lo ou aumentar sua utilidade
- **Benfeitoria Necessária**: Ação realizada com finalidade de conservar ou evitar que o bem se deteriore
- **Benfeitoria Útil**: Ação realizada para aumentar ou facilitar o uso ou utilidade da coisa
- **Benfeitoria Voluptuária**: Ação realizada com finalidade de prazer pessoal, sem necessidade de melhoria ou conservação

### Referências legais
- Art. 94 do Código Civil
- Súmula 352 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar benfeitorias entre necessárias, úteis e voluptuárias
- Entender a distinção entre acessórios e benfeitorias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Direito Civil", "legal_refs": ["Art. 94 do Código Civil", "Súmula 352 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T19:53:29.578401+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=70", "doc_key": "bc29dae046490e076580bb728f444045"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a29a54b4aa361d699297fff01f72510618be5e6c378062a4d8e4f952c4c456fc'),
  ('cpiuris2025::c829ae0f8b0e9268be0fe3c42ca58e07', 'doutrina', 'cp_iuris', 'Direito Civil — Bens Públicos Dominicais', '## Bens Públicos Dominicais

Os bens públicos dominicais são bens disponíveis de patrimônio público, que podem ser convertidos em bem de uso comum ou especial. Eles são inalienáveis, mas a inalienabilidade pode ser perdida com desafetação.

### Conceitos
- **Bens Públicos Dominicais**: bens disponíveis do patrimônio público que podem ser convertidos em bem de uso comum ou especial
- **Alienabilidade**: a capacidade de transferir a propriedade de um bem para outrem
- **Desafetação**: mudança da destinação do bem, que pode resultar na perda da inalienabilidade

### Referências legais
- Art. 25 da Lei nº 8.542/1992
- Súmula 52 do STJ

### Jurisprudência
- RE 1667227/RS

### Dicas de prova
- Entenda a diferença entre bens públicos dominicais e inalienáveis
- Conheça o conceito de desafetação e como ela afeta a alienabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Direito Civil", "legal_refs": ["Art. 25 da Lei nº 8.542/1992", "Súmula 52 do STJ"], "jurisprudence": ["RE 1667227/RS"], "confidence": 0.8, "extracted_at": "2026-05-25T19:53:55.181905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=70", "doc_key": "c829ae0f8b0e9268be0fe3c42ca58e07"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e6559891e895df73254465146b5e14c783fcbb45c9155404ec91d6c8846813e8'),
  ('cpiuris2025::839f4812dc44ce0f90b2c3f561ba1025', 'doutrina', 'cp_iuris', 'Direito Civil — Bem de Família e Bens Públicos', '## Bem de Família e Bens Públicos

O bem de família é o imóvel utilizado como residência da entidade familiar. A instituição do bem de família convencional se dá por escritura pública ou testamento, mas não pode ultrapassar 1/3 do patrimônio líquido da pessoa que faz a instituição.

### Conceitos
- **Bem de Família**: O imóvel utilizado como residência da entidade familiar
- **Bem Público**: Pertence ao patrimônio disponível da pessoa jurídica de direito público, podendo ser alienados
- **Alienabilidade**: A capacidade de transferir a propriedade de um bem
- **Impenhorabilidade**: A proteção contra a execução forçada do imóvel

### Referências legais
- Art. 1.711 CC
- Lei nº 8.009/90

### Jurisprudência
- Súmula 340 STF

### Dicas de prova
- Entenda a diferença entre bem de família voluntário e involuntário
- Conheça as condições para a instituição do bem de família convencional
- Avalie as consequências da instituição do bem de família convencional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direito Civil", "legal_refs": ["Art. 1.711 CC", "Lei nº 8.009/90"], "jurisprudence": ["Súmula 340 STF"], "confidence": 0.8, "extracted_at": "2026-05-25T19:54:38.585630+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=71", "doc_key": "839f4812dc44ce0f90b2c3f561ba1025"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7439afbdc3b25546d7ec0a9a8e4e413f4bcfdaa94ef356e1bdf5e14e1af53628'),
  ('cpiuris2025::845364080a46fee84e1875d10eec90e0', 'doutrina', 'cp_iuris', 'Direito Civil — Bem de Família Convencional e Inalienabilidade', '## Bem de Família Convencional e Inalienabilidade

A inalienabilidade é regra geral do bem de família convencional, mas pode ser excepcionada com consentimento dos interessados e autorização judicial.

### Conceitos
- **Alienabilidade**: Permissão para a transferência de propriedade
- **Bem de Família Convencional**: Propriedade destinada à manutenção da família
- **Inalienabilidade**: Regra geral que proíbe a alienação do bem de família convencional

### Referências legais
- Art. 1.722
- Art. 1.723

### Dicas de prova
- Entenda a diferença entre inalienabilidade e alienabilidade
- Conheça as exceções à regra geral de inalienabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direito Civil", "legal_refs": ["Art. 1.722", "Art. 1.723"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:54:59.144037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=71", "doc_key": "845364080a46fee84e1875d10eec90e0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8d98a2fd4733bab9a2495648c0312f77ecae2eefb614e02e899ae2d013cc190e'),
  ('cpiuris2025::2bcaed6fe9f0683320d413566e87be68', 'doutrina', 'cp_iuris', 'Direito Civil — Bem de Família Involuntário', '## Bem de Família Involuntário

O bem de família é protegido contra penhora, exceto em casos específicos. O conceito evoluiu ao abordar situações como casais solteiros e pessoas separadas.

### Conceitos
- **Bem de Família**: Proteção contra penhora de imóveis residenciais
- **Impenhorabilidade**: Incapacidade de ser objeto de penhora
- **Família**: Lar da pessoa solteira ou separada
- **Vaga de Garagem**: Proteção contra penhora se não tiver matrícula própria
- **Locação**: Renda revertida para subsistência ou moradia da família

### Referências legais
- Art. 1º, Lei nº 8.009/90

### Jurisprudência
- {''term'': ''Súmula 364 STJ'', ''definition'': ''Inclui imóveis de pessoas solteiras, separadas e viúvas''}
- {''term'': ''Súmula 449 STJ'', ''definition'': ''Vaga de garagem com matrícula própria não é bem de família''}
- {''term'': ''Súmula 486 STJ'', ''definition'': ''Renda da locação reverter para subsistência ou moradia da família''}

### Dicas de prova
- Distinção entre imóveis residenciais e não residenciais
- Conceito de família evoluiu ao abordar situações como casais solteiros
- Importância da matrícula própria para a vaga de garagem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direito Civil", "legal_refs": ["Art. 1º, Lei nº 8.009/90"], "jurisprudence": ["{''term'': ''Súmula 364 STJ'', ''definition'': ''Inclui imóveis de pessoas solteiras, separadas e viúvas''}", "{''term'': ''Súmula 449 STJ'', ''definition'': ''Vaga de garagem com matrícula própria não é bem de família''}", "{''term'': ''Súmula 486 STJ'', ''definition'': ''Renda da locação reverter para subsistência ou moradia da família''}"], "confidence": 0.8, "extracted_at": "2026-05-25T19:55:41.670048+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=72", "doc_key": "2bcaed6fe9f0683320d413566e87be68"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1c70070367c9dcbeec6f4c5205fbe7f4757a5ae2f70e0826c52446788372608b'),
  ('cpiuris2025::53d6f2d5ac35ac4daa71964a08e7b14f', 'doutrina', 'cp_iuris', 'Direito Civil — Impenhorabilidade e Débito Imobiliário', '## Impenhorabilidade e Débito Imobiliário

As regras de impenhorabilidade não são absolutas e podem ser excepcionadas em casos específicos, como financiamento de construção ou aquisição do imóvel.

### Conceitos
- **Débito imobiliário**: Crédito destinado à construção ou aquisição do imóvel
- **Impenhorabilidade**: Proteção do bem de família contra penhora
- **Financiamento imobiliário**: Crédito utilizado para financiar a construção ou aquisição do imóvel

### Referências legais
- Art. 3º da Lei nº 8.009/1990

### Jurisprudência
- Súmula 549 do STJ
- REsp 1.976.743-SC

### Dicas de prova
- Distinção entre débito imobiliário e financiamento imobiliário
- Exceções à impenhorabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direito Civil", "legal_refs": ["Art. 3º da Lei nº 8.009/1990"], "jurisprudence": ["Súmula 549 do STJ", "REsp 1.976.743-SC"], "confidence": 0.8, "extracted_at": "2026-05-25T19:56:17.738363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=72", "doc_key": "53d6f2d5ac35ac4daa71964a08e7b14f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e9fbc13e0ac858848447734a5d99c5768401b8b36ff4a4fab3ec08ecf79d1272'),
  ('cpiuris2025::e2d1311ccb97a4147078b5bae72edc41', 'doutrina', 'cp_iuris', 'Direito Civil — Impenhorabilidade do Bem de Família em Contratos de Locação', '## Impenhorabilidade do Bem de Família em Contratos de Locação

A impenhorabilidade do bem de família em contratos de locação é limitada a casos específicos, como fiança concedida em contrato de locação ou propriedade por empresa na qual mora o sócio. A proteção do bem de família visa proteger quem realmente exerce moradia no bem.

### Conceitos
- **Bem de Família**: Propriedade que é objeto de impenhorabilidade em determinadas situações
- **Contrato de Locação**: Acordo pelo qual uma pessoa (o locatário) tem direito ao uso de um bem (o imóvel) por um período determinado
- **Fiança**: Garantia oferecida em contrato para garantir o cumprimento das obrigações
- **Propriedade por Empresa**: Propriedade de uma empresa que é utilizada como moradia por um dos sócios
- **Obrigação de Pagar Aluguel**: Dever de pagar aluguel pelo uso exclusivo do bem

### Referências legais
- Art. 3º, inciso VII, da Lei n. 8.009/1990

### Jurisprudência
- Tema 1091 do STJ
- Súmula 55 do STJ

### Dicas de prova
- Distinção entre fiança concedida em contrato de locação e propriedade por empresa na qual mora o sócio
- Importância da proteção do bem de família para quem realmente exerce moradia no bem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direito Civil", "legal_refs": ["Art. 3º, inciso VII, da Lei n. 8.009/1990"], "jurisprudence": ["Tema 1091 do STJ", "Súmula 55 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T19:56:57.419669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=73", "doc_key": "e2d1311ccb97a4147078b5bae72edc41"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0a3093410015f155b8b014226c6fb4329c5f23d9687f915798b66deac09faf0e'),
  ('cpiuris2025::1d924e246b7ad0536945a41735bef2f9', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Propter Rem e Bem de Família', '## Obrigação Propter Rem e Bem de Família

A obrigação propter rem é uma obrigação que se baseia em direito real, impedindo terceiros de criar situações que possam ser levadas a título de oposição aos titulares de um direito real. Isso inclui o aluguel por uso exclusivo do bem, que configura-se como obrigação propter rem e pode afastar a impenhorabilidade do bem de família.

### Conceitos
- **Obrigação Propter Rem**: obrigação que se baseia em direito real
- **Bem de Família**: bem protegido por lei para garantir a segurança e o bem-estar de sua família
- **Aluguel por Uso Exclusivo**: obrigação que se baseia em direito real, impedindo terceiros de criar situações que possam ser levadas a título de oposição aos titulares de um direito real

### Referências legais
- Art. 3º, IV, da Lei n. 8.009/90

### Jurisprudência
- REsp 1.822.040-PR
- STJ. 4ª Turma. EDcl no AREsp 511.486-SC
- REsp 1.935.563-SP
- REsp 1.888.863-SP

### Dicas de prova
- Entenda a distinção entre obrigação propter rem e bem de família.
- Conheça as exceções previstas no art. 3º, IV, da Lei n. 8.009/90 para afastar a impenhorabilidade do bem de família.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direito Civil", "legal_refs": ["Art. 3º, IV, da Lei n. 8.009/90"], "jurisprudence": ["REsp 1.822.040-PR", "STJ. 4ª Turma. EDcl no AREsp 511.486-SC", "REsp 1.935.563-SP", "REsp 1.888.863-SP"], "confidence": 0.9, "extracted_at": "2026-05-25T19:57:33.861826+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=73", "doc_key": "1d924e246b7ad0536945a41735bef2f9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '884d0bbd4fb25d97a85716b9ef24679c8921873d518d5c88e3d1ec3e11e2c5db'),
  ('cpiuris2025::e6f3f6830cd0f3e0d7bed0e637b2e772', 'doutrina', 'cp_iuris', 'Direito Civil — Impenhorabilidade do Bem de Família', '## Impenhorabilidade do Bem de Família

A impenhorabilidade do bem de família está protegida pela Lei n. 8.009/90 e pode ser afetada por dívidas de pensão alimentícia, dívidas condominiais e aquisição do bem no curso da execução, mas não se aplica à renúncia ao bem.

### Conceitos
- **Bem de família**: imóvel que é objeto de impenhorabilidade por dívida
- **Dívida de pensão alimentícia**: prestação obrigatória para garantir o sustento de uma pessoa
- **Dívidas condominiais**: obrigações contraídas pelo proprietário do imóvel em relação a outros condôminos
- **Aquisição do bem no curso da execução**: adquirir o imóvel após a dívida não ter sido quitada

### Referências legais
- Art. 3º, III, da Lei n. 8.009/90
- STJ - AgInt no REsp 1619189/SP

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Fazer a distinção entre dívidas de pensão alimentícia e outras dívidas
- Entender que a aquisição do bem no curso da execução não afasta a impenhorabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direito Civil", "legal_refs": ["Art. 3º, III, da Lei n. 8.009/90", "STJ - AgInt no REsp 1619189/SP"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T19:58:20.178594+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=74", "doc_key": "e6f3f6830cd0f3e0d7bed0e637b2e772"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '620ca8defbd9aada9be41c74eb33ffc9e58ea7fd5bc20575a9b4f5dc2fe77328'),
  ('cpiuris2025::9deefd4c786e2b642541960eff2a6642', 'doutrina', 'cp_iuris', 'Direito Civil — Fato Jurídico e Ato Jurídico', '## Fato Jurídico e Ato Jurídico

Resumo objetivo: Fato jurídico é o acontecimento que interessa ao direito, enquanto ato jurídico é a atuação da vontade de alguém com relevância jurídica.

### Conceitos
- **Fato Jurídico**: Acontecimento que interessa ao direito
- **Ato Jurídico**: Atuação da vontade de alguém com relevância jurídica
- **Negócio Jurídico**: Ato jurídico com composição de interesse das partes

### Referências legais
- Art. 157 do Código Civil
- ...

### Jurisprudência
- STJ - AgInt no AREsp 2182241/RS – Relator Ministro Moura Ribeiro

### Dicas de prova
- Entenda a distinção entre fato jurídico e ato jurídico
- Conheça o conceito de negócio jurídico como base do contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direito Civil", "legal_refs": ["Art. 157 do Código Civil", "..."], "jurisprudence": ["STJ - AgInt no AREsp 2182241/RS – Relator Ministro Moura Ribeiro"], "confidence": 0.8, "extracted_at": "2026-05-25T19:58:45.053294+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=74", "doc_key": "9deefd4c786e2b642541960eff2a6642"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '93cb2a98d1127f8b8b07767bb18dbf76e93b04d76c10b7e08bc77fb1c55d6e1a'),
  ('cpiuris2025::56d545d05844f65eacd35d9c2dc7b927', 'doutrina', 'cp_iuris', 'Direito Civil — Negócio Jurídico', '## Negócio Jurídico

O negócio jurídico é um ato ou pluralidade de atos entre pessoas que tem como fim produzir efeitos jurídicos e modificar relações jurídicas. A autonomia privada é ampla, com declaração de vontade limitada pelos princípios da função social e boa-fé objetiva.

### Conceitos
- **Negócio Jurídico**: ato ou pluralidade de atos entre pessoas que produzem efeitos jurídicos
- **Autonomia Privada**: declaração de vontade limitada pelos princípios da função social e boa-fé objetiva
- **Vontade Interna**: intenção do agente que condiz com a vontade exteriorizada
- **Vontade Externa**: voluntade declarada externamente, que pode estar em desacordo com a vontade interna
- **Consentimento**: vício quando a vontade interna e externa são destoantes
- **Declaração de Vontade**: limitação da autonomia privada pelos princípios da função social e boa-fé objetiva
- **Boa-Fé Objetiva**: princípio que exige a honestidade absoluta na negociação
- **Função Social**: princípio que visa garantir a ordem social e a justiça

### Referências legais
- Art. 1.264 do Código Civil

### Dicas de prova
- Entenda a distinção entre vontade interna e externa
- Conheça as teorias da declaração e da vontade
- Identifique os princípios da autonomia privada, função social e boa-fé objetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Civil", "legal_refs": ["Art. 1.264 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T19:59:27.442238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=75", "doc_key": "56d545d05844f65eacd35d9c2dc7b927"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '92a1c4a05172a6b76378d7506ebe3be599de39bc9eedfb638a338e6eca58b1c9'),
  ('cpiuris2025::f8aee33a4acf9393151d03f5fd4a35a7', 'doutrina', 'cp_iuris', 'Direito Civil — Classificação do negócio jurídico', '## Classificação do negócio jurídico

O negócio jurídico se subdivide em unilateral e bilateral, com classificações baseadas no número de declarantes.

### Conceitos
- **Negócio Jurídico Unilateral**: Com uma única manifestação de vontade
- **Negócio Jurídico Bilateral**: Com duas manifestações e vontades coincidentes sobre o mesmo objeto
- **Consentimento Mútuo**: Acordo de vontades entre as partes
- **Acordo Simples**: Uma parte obtém vantagem sem reciprocidade
- **Sinalagmático**: Contrato com vantagens recíprocas

### Referências legais
- Art. X da Lei Y
- ...

### Dicas de prova
- Entenda a distinção entre unilateral e bilateral.
- Identifique o consentimento mútuo em um acordo de vontades.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Civil", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:00:02.424068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=75", "doc_key": "f8aee33a4acf9393151d03f5fd4a35a7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bbb608757e84b3a1767549df1eebb560c975d16f06f50e30f21d114ce92e197e'),
  ('cpiuris2025::9d14a9311becedaabe8b8c3e6a68b85a', 'doutrina', 'cp_iuris', 'Direito Civil — Negócios Jurídicos', '## Negócios Jurídicos

Os negócios jurídicos podem ser gratuitos ou onerosos, com vantagens patrimoniais para as partes. Existem diferentes tipos de negócios, incluindo comutativos, aleatórios e bifrontes.

### Conceitos
- **Gratuito**: Negócio jurídico em que apenas uma das partes auferir vantagem ou benefício
- **Oneroso**: Negócio jurídico em que ambas as partes contratantes auferem vantagens, correspondentes a um sacrifício ou contraprestação
- **Comutativo**: Negócio jurídico com prestações certas e determinadas
- **Aleatório**: Negócio jurídico caracterizado pela incerteza, com risco como essência do negócio
- **Bifronte**: Negócio jurídico que pode ser oneroso ou gratuito, segundo a vontade das partes
- **Vantagem patrimonal**: Benefício econômico obtido por uma das partes no negócio jurídico
- **Plano de existência**: Primeiro plano do negócio jurídico, que confere possibilidade de validade
- **Plano de validade**: Segundo plano do negócio jurídico, que adjetiva elementos de existência para verificar validade ou inválida

### Referências legais
- Art. 104 do Código Civil

### Dicas de prova
- Entenda a distinção entre negócios gratuitos e onerosos
- Conheça os diferentes tipos de negócios jurídicos (comutativos, aleatórios, bifrontes)
- Aprenda sobre os planos do negócio jurídico (existência, validade e eficácia)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direito Civil", "legal_refs": ["Art. 104 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:00:52.426166+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=76", "doc_key": "9d14a9311becedaabe8b8c3e6a68b85a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9c12ec183c2326b0e57ab91b11712973eb4bf13d19445997fc4ceceb3ad79a26'),
  ('cpiuris2025::05c0c0f26805eb595e4b27cf27135c75', 'doutrina', 'cp_iuris', 'Direito Civil — Eficácia e Elementos Acidentais do Negócio Jurídico', '## Eficácia e Elementos Acidentais do Negócio Jurídico

Resumo objetivo: O artigo 105 do Código Civil estabelece regras sobre incapacidade, boa-fé objetiva e venire contra factum proprium.

### Conceitos
- **Venire contra factum proprium**: Instituto que veda práticas antagônicas àquelas praticadas anteriormente pelo próprio agente
- **Boa-fé objetiva**: Princípio que proíbe comportamentos contraditórios com as relações negociais anteriores
- **Incapacidade**: Condição que afeta a capacidade de uma parte para celebrar um negócio jurídico
- **Cointeressados**: Pessoas que têm interesse no mesmo objeto do direito ou da obrigação comum
- **Princípio da boa-fé objetiva**: Princípio que proíbe comportamentos contraditórios com as relações negociais anteriores

### Referências legais
- Art. 105 do Código Civil

### Dicas de prova
- Entenda a diferença entre venire contra factum proprium e boa-fé objetiva
- Conheça as regras sobre incapacidade e cointeressados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direito Civil", "legal_refs": ["Art. 105 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:01:22.257331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=76", "doc_key": "05c0c0f26805eb595e4b27cf27135c75"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ec1639cf2665bfc1f1141d67d611fb093141ae33227c93828c59eda34f8f0faa'),
  ('cpiuris2025::df13d199a11357b1f97ad86508a80b20', 'doutrina', 'cp_iuris', 'Direito Civil — Vontade e Forma nos Negócios Jurídicos', '## Vontade e Forma nos Negócios Jurídicos

O texto discute a vontade e a forma nos negócios jurídicos, destacando que a validade da declaração de vontade não depende de forma especial, exceto quando a lei expressamente exigir. Além disso, o Código Civil estabelece regras para a constituição, transferência, modificação ou renúncia de direitos reais sobre imóveis.

### Conceitos
- **Vontade**: A expressão da intenção do agente em realizar um negócio jurídico
- **Forma**: O meio através do qual o agente exprime a sua vontade, de acordo com a lei
- **Declaração de Vontade**: A expressão da intenção do agente em realizar um negócio jurídico, que não depende de forma especial exceto quando a lei exigir
- **Negócios Jurídicos**: Transações legais que envolvem a transferência ou modificação de direitos reais
- **Direitos Reais**: Direitos que podem ser transferidos, modificados ou renunciados em um negócio jurídico
- **Imóveis**: Propriedades que não podem ser facilmente transferidas ou modificadas
- **Escrita Pública**: Um ato solene que é essencial à validade dos negócios jurídicos que visem à constituição, transferência, modificação ou renúncia de direitos reais sobre imóveis
- **Forma Especial**: Uma forma específica de realizar um negócio jurídico que é exigida pela lei

### Referências legais
- Art. 106 do Código Civil
- Art. 107 do Código Civil
- Art. 108 do Código Civil

### Dicas de prova
- Entenda a distinção entre vontade e forma nos negócios jurídicos
- Conheça as regras estabelecidas pelo Código Civil para a constituição, transferência, modificação ou renúncia de direitos reais sobre imóveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direito Civil", "legal_refs": ["Art. 106 do Código Civil", "Art. 107 do Código Civil", "Art. 108 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:02:22.484834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=77", "doc_key": "df13d199a11357b1f97ad86508a80b20"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4e684c92367aa88c0907decc10c622a4d93eeecd816b740db03befd124c6d7fe'),
  ('cpiuris2025::2510f7f65741ba57dfa59b0875e5cbb0', 'doutrina', 'cp_iuris', 'Direito Civil — Manifestação de Vontade no Negócio Jurídico', '## Manifestação de Vontade no Negócio Jurídico

O Código Civil define regras para a manifestação de vontade em negócios jurídicos, incluindo a reserva mental e o silêncio como anuência. A teoria da vontade é adotada, onde a intenção manifestada interessa para o negócio.

### Conceitos
- **Vontade**: Intenção manifestada que interessa para o negócio
- **Reserva Mental**: Manifestação de vontade feita com a intenção de não querer algo, mas sem declaração expressa
- **Silêncio como Anuência**: O silêncio pode ser considerado uma manifestação de vontade quando as circunstâncias ou usos o autorizam
- **Teoria da Vontade**: A teoria que a intenção manifestada é o que interessa para o negócio, mesmo se não condizente com a vontade desejada

### Referências legais
- Art. 109 do Código Civil
- Art. 110 do Código Civil
- Art. 111 do Código Civil

### Dicas de prova
- Entenda a teoria da vontade e suas implicações no negócio jurídico
- Conheça as regras para a reserva mental e o silêncio como anuência
- Aproveite a analogia entre a proteção da confiança e a vedação do comportamento contraditório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direito Civil", "legal_refs": ["Art. 109 do Código Civil", "Art. 110 do Código Civil", "Art. 111 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:02:57.758360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=77", "doc_key": "2510f7f65741ba57dfa59b0875e5cbb0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ae6b3b300d13e192b75aeba9f7e22159a505b6570c6df093a5367a09393fbcd1'),
  ('cpiuris2025::aa7c5e83a24635bdb9c9f1972ad8f39c', 'doutrina', 'cp_iuris', 'Direito Civil — Interpretação das Declarações de Vontade no Código Civil', '## Interpretação das Declarações de Vontade no Código Civil

A interpretação das declarações de vontade no Código Civil busca atender à intenção das partes, mais do que ao sentido literal da linguagem. Isso significa que a solução deve ser buscada na visão dos personagens e na teoria da vontade.

### Conceitos
- **Interpretação das declarações de vontade**: Busca atender à intenção das partes, mais do que ao sentido literal da linguagem
- **Teoria da vontade**: A teoria que busca entender a vontade das partes como a essência do negócio jurídico
- **Boa-fé objetiva**: Um elemento interpretativo do negócio jurídico, impondo um comportamento leal e probo
- **Uso do lugar de celebração**: Importante para a interpretação dos negócios jurídicos

### Referências legais
- Art. 112 do Código Civil
- Art. 113 do Código Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a teoria da vontade e sua importância na interpretação das declarações de vontade
- Conheça as regras de interpretação dos negócios jurídicos, especialmente a boa-fé objetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direito Civil", "legal_refs": ["Art. 112 do Código Civil", "Art. 113 do Código Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:03:32.371862+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=78", "doc_key": "aa7c5e83a24635bdb9c9f1972ad8f39c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '63e07e07df53b8d56be0a0a2267f4778266bc8abe5226d326abbafb32c81eb50'),
  ('cpiuris2025::0fd837d68cb4aba2942698654904ec38', 'doutrina', 'cp_iuris', 'Direito Civil — Vícios do Negócio Jurídico', '## Vícios do Negócio Jurídico

Os vícios do negócio jurídico podem ser classificados em vícios do consentimento e vícios sociais. Os vícios do consentimento incluem dolo, erro, estado de perigo, lesão e coação, enquanto os vícios sociais incluem fraude contra credores e simulação.

### Conceitos
- **Vício do Consentimento**: Manifestação de vontade interna que não condiz com a externada
- **Vício Social**: Manifestação de vontade querida praticada com intuito de prejudicar terceiros
- **Dolo**: Manifestação de vontade com intuito de prejudicar alguém
- **Erro**: Falsa representação positiva da realidade ou quando o próprio agente se faz enganar sem perceber o erro
- **Estado de Perigo**: Situação em que a coisa não é mais do que promete
- **Lesão**: Dano ao direito alheio
- **Coação**: Força ou pressão para que alguém faça algo contra sua vontade

### Referências legais
- Art. 173 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre erro e ignorância
- Entender a distinção entre vício do consentimento e vício social
- Conhecer as hipóteses de erro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direito Civil", "legal_refs": ["Art. 173 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:04:17.049943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=78", "doc_key": "0fd837d68cb4aba2942698654904ec38"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e402d1b55dc2ed1b153aec857a598f5cf3f595d765c626ff32e445331b848756'),
  ('cpiuris2025::fb339ec3174b0bec57fe5b5b1f966d42', 'doutrina', 'cp_iuris', 'Direito Civil — Erro no Negócio Jurídico', '## Erro no Negócio Jurídico

O erro essencial ou substancial é necessário para a invalidação do negócio jurídico, sendo a causa determinante que faria com que o mesmo não fosse celebrado.

### Conceitos
- **Erro Essencial/Substancial**: Causa determinante que faria com que o negócio jurídico não fosse celebrado
- **Erro Acidental**: Não invalida o negócio jurídico, se refere a circunstâncias de menor importância e que não acarretam efetivo prejuízo
- **Erro Escusável/Perdoável**: Erro que qualquer pessoa de mediana prudência poderia cometer, não necessariamente invalida o negócio jurídico

### Referências legais
- Art. 139, III do CC

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Diferenciar entre erro essencial e erro acidental
- Entender a noção de erro escusável/perdoável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direito Civil", "legal_refs": ["Art. 139, III do CC"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:04:47.728231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=79", "doc_key": "fb339ec3174b0bec57fe5b5b1f966d42"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '06533fe641d811622a7a073ade367a4483570d2d3b78b87ff3f5b85953d34819'),
  ('cpiuris2025::0a8dfd2b4919e83df219922614c8aebf', 'doutrina', 'cp_iuris', 'Direito Civil — Vício na Declaração de Vontade e Anulação de Negócios Jurídicos', '## Vício na Declaração de Vontade e Anulação de Negócios Jurídicos

O art. 140 do Código Civil estabelece que o falso motivo vicia a declaração de vontade quando expresso como razão determinante, mas não se aplica quando os motivos do negócio jurídico não forem relevantes para sua formação. A anulação de transmissões errôneas da vontade é permitida nos mesmos casos em que a declaração direta é anulável.

### Conceitos
- **Vício na Declaração de Vontade**: Ocorre quando o motivo expresso como razão determinante é falso
- **Anulação de Negócios Jurídicos**: Processo que visa invalidar um negócio jurídico devido a vício ou irregularidade em sua formação
- **Declaração Direta**: Declaração feita pessoalmente pelo declarante, sem interposta pessoa
- **Interposta Pessoa**: Pessoa que agrega o declarante em uma declaração jurídica
- **Erro de Motivos**: Ocorre quando os motivos do negócio jurídico não são relevantes para sua formação

### Referências legais
- Art. 140 do Código Civil
- Art. 141 do Código Civil

### Dicas de prova
- Entenda a distinção entre vício na declaração de vontade e erro de motivos
- Conheça as hipóteses em que a anulação de transmissões errôneas da vontade é permitida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direito Civil", "legal_refs": ["Art. 140 do Código Civil", "Art. 141 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:05:25.809501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=79", "doc_key": "0a8dfd2b4919e83df219922614c8aebf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bb13161b506312b0076c330e0b1f75bb7d476ef10c17af66a69b67657ab043de'),
  ('cpiuris2025::852dc431387ac8012928d29d3ccf48d7', 'doutrina', 'cp_iuris', 'Direito Civil — Dolo e Negócios Jurídicos', '## Dolo e Negócios Jurídicos

O dolo é o vício no negócio jurídico que ocorre quando uma parte se vale de enganos para induzir outra em erro. O Código Civil classifica o dolo em diferentes modalidades, como dolo principal, acidental, bonus, malus, comissivo e omissivo.

### Conceitos
- **Dolo**: Vício no negócio jurídico que ocorre quando uma parte se vale de enganos para induzir outra em erro.
- **Dolo Principal**: O dolo que se concentra na causa determinante do negócio jurídico
- **Dolo Acidental**: O dolo que se concentra em elementos acessórios e circunstanciais no negócio jurídico
- **Dolus Bonus**: O dolo tolerável, destituído de gravidade suficiente para viciar a manifestação da vontade
- **Dolus Malus**: O dolo revestido de gravidade, exercido com o propósito de ludibriar e prejudicar
- **Dolo Comissivo**: O dolo materializado por ações maliciosas
- **Dolo Omissivo**: O engodo praticado pelo silêncio, quando a parte tinha obrigação de alertar sobre determinado fato relevante

### Referências legais
- Art. 144 do Código Civil
- Art. 145 do Código Civil
- Art. 146 do Código Civil
- Art. 147 do Código Civil

### Dicas de prova
- Entenda a distinção entre dolo principal e acidental
- Conheça as diferentes modalidades de dolo (bonus, malus, comissivo e omissivo)
- Aprenda a aplicar a regra do dolo na prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direito Civil", "legal_refs": ["Art. 144 do Código Civil", "Art. 145 do Código Civil", "Art. 146 do Código Civil", "Art. 147 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:06:22.561156+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=80", "doc_key": "852dc431387ac8012928d29d3ccf48d7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c4e1a1c73e82973da396a787aba18d929b4dd34e45b519d92917c0335bf44923'),
  ('cpiuris2025::e7294d6034c77e1610d0bd74cd3cd19c', 'doutrina', 'cp_iuris', 'Direito Civil — Dolo e Representação no Direito Civil', '## Dolo e Representação no Direito Civil

O dolo do representante não é igual ao dolo de terceiro, e a responsabilidade solidária do representado em caso de representação convencional. Além disso, o dolo bilateral é regulado pelo artigo 150 do CC e impede que nenhuma das partes alegue ou reclame indenização.

### Conceitos
- **Dolo**: intenção de enganar ou prejudicar alguém
- **Representação**: ação de agir em nome de outra pessoa
- **Responsabilidade Solidária**: obrigação de uma pessoa se tornar responsável por atos de outra
- **Dolo Bilateral**: dolo praticado por ambas as partes em um negócio
- **Dolo Unilateral**: dolo de uma das partes em um negócio
- **Representação Legal**: representação feita pelo representado
- **Representação Convencional**: representação feita por terceiro

### Referências legais
- Art. 149 do CC
- Art. 150 do CC

### Dicas de prova
- Diferenciação entre representante legal e convencional
- Responsabilidade solidária do representado em caso de representação convencional
- Implicação do dolo bilateral no negócio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direito Civil", "legal_refs": ["Art. 149 do CC", "Art. 150 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:06:53.828818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=80", "doc_key": "e7294d6034c77e1610d0bd74cd3cd19c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e54823395b44320437a92b8ccf9dd61255c11cff23374e3decf8cf2c99cf4267'),
  ('cpiuris2025::c8d37b1b79aed84270347f91dfa1e81c', 'doutrina', 'cp_iuris', 'Direito Civil — Coação', '## Coação

A coação é toda ameaça ou pressão injusta exercida sobre um indivíduo para forçá-lo a praticar um ato ou realizar um negócio, caracterizada pelo emprego da violência psicológica para viciar a vontade.

### Conceitos
- **Coação**: Ameaça ou pressão injusta exercida sobre um indivíduo
- **Vontade**: Manifestação de desejo ou preferência
- **Violação da vontade**: O emprego da violência psicológica para viciar a vontade do agente
- **Coação absoluta**: Coação em que a vantagem decorre de violência física
- **Coação relativa**: Coação que torna o negócio anulável

### Referências legais
- Art. 151 do Código Civil

### Dicas de prova
- Entenda a diferença entre coação absoluta e relativa
- Identifique os requisitos para configurar a coação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direito Civil", "legal_refs": ["Art. 151 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:07:23.490635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=81", "doc_key": "c8d37b1b79aed84270347f91dfa1e81c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7a1c2043974831754142f5e3eda879c489b6db0ba686cfa55c2f707c8b3ca2a3'),
  ('cpiuris2025::ef29b7b6bcd55c65e3b61c7b43aea772', 'doutrina', 'cp_iuris', 'Direito Civil — Coação no Direito Civil', '## Coação no Direito Civil

A coação é uma situação em que alguém é forçado a fazer algo contra sua vontade, podendo ser contra pessoa ou bens. A coação não se considera vício do negócio jurídico quando ocorre o temor reverencial ou o exercício normal de um direito.

### Conceitos
- **Coação**: Força física ou moral que obriga alguém a fazer algo contra sua vontade
- **Temor Reverencial**: Respeito à autoridade instituída, não caracterizando coação
- **Exercício Normal de um Direito**: Não caracteriza vício do negócio jurídico quando ocorre o exercício normal de um direito

### Referências legais
- Art. 153 do Código Civil

### Dicas de prova
- Distinção entre coação e temor reverencial
- Exemplos de coação (p. ex.: pedidos de dinheiro com ameaça)
- Análise das circunstâncias do caso para determinar se a pessoa ameaçada é relevante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direito Civil", "legal_refs": ["Art. 153 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:08:01.810165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=81", "doc_key": "ef29b7b6bcd55c65e3b61c7b43aea772"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bf7dc1d9da82dda26c76cdbb314530555b336206663b1d405554985dbf880f57'),
  ('cpiuris2025::e26b409e5900536e368fd196bd5f37f5', 'doutrina', 'cp_iuris', 'Direito Civil — Coação e Estado de Perigo no Código Civil', '## Coação e Estado de Perigo no Código Civil

O exercício regular de um direito não gera coação. A coação é prevista no art. 154 do Código Civil, mas o negócio subsiste se a parte não tiver conhecimento da coação. O estado de perigo é um vício do negócio jurídico que ocorre quando alguém assume obrigação excessivamente onerosa para salvar-se ou sua família de grave dano.

### Conceitos
- **Coação**: Exercício regular de um direito não gera coação
- **Estado de Perigo**: Situação de extrema necessidade que conduz a uma pessoa a celebrar negócio jurídico com obrigação desproporcional e excessivamente onerosa
- **Boa-fé**: Princípio que tutela a confiança da parte que recebe declaração de vontade
- **Proibição do Exercício Regular de Direito**: Não gera coação o exercício regular de um direito, mas sim o exercício lícito

### Referências legais
- Art. 154 do Código Civil
- Art. 155 do Código Civil
- Art. 156 do Código Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre exercício regular de direito e exercício lícito
- Entender a diferença entre coação exercida por terceira pessoa e coação decorrente de terceiro sem que a parte tenha conhecimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direito Civil", "legal_refs": ["Art. 154 do Código Civil", "Art. 155 do Código Civil", "Art. 156 do Código Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:08:38.951458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=82", "doc_key": "e26b409e5900536e368fd196bd5f37f5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ff5a89754a2d3eb7e6e36f694341180a972503b2bde243263ea13e997512fdb1'),
  ('cpiuris2025::697953dce284aea61c75a77589917b9d', 'doutrina', 'cp_iuris', 'Direito Civil — Estado de Perigo e Convalidação de Negócios', '## Estado de Perigo e Convalidação de Negócios

O estado de perigo é uma situação em que um negócio pode ser convalidado se for oferecido suplemento suficiente ou se a parte favorecida concordar com redução do proveito.

### Conceitos
- **Convalidação**: Ação de reconhecer a validade de um negócio apesar de irregularidades ou vieses
- **Estado de Perigo**: Situación em que um negócio pode ser convalidado se for oferecido suplemento suficiente ou se a parte favorecida concordar com redução do proveito
- **Coação**: Situação em que uma pessoa assume prestação onerosa para salvar alguém que não é da família

### Referências legais
- Art. 157, §2º do Código Civil

### Jurisprudência
- Enunciado 158 da Jornada de Direito Civil
- Enunciado 148 da III Jornada de Direito Civil

### Dicas de prova
- Entenda a diferença entre coação e estado de perigo
- Conheça as regras de convalidação de negócios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direito Civil", "legal_refs": ["Art. 157, §2º do Código Civil"], "jurisprudence": ["Enunciado 158 da Jornada de Direito Civil", "Enunciado 148 da III Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T20:09:06.306884+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=82", "doc_key": "697953dce284aea61c75a77589917b9d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e405d70acc0281b6421ce871e974979be730c86923fe8b087c4f8cdd919c8957'),
  ('cpiuris2025::22585c63f5a4611e1c04779dd5b1d1b9', 'doutrina', 'cp_iuris', 'Direito Civil — Lesão e Estado de Perigo', '## Lesão e Estado de Perigo

O Código Civil de 2002 introduziu a lesão como instituto jurídico, que ocorre quando uma pessoa se obriga a prestação manifestamente desproporcional ao valor da prestação oposta, devido à premente necessidade ou inexperiência. O objetivo é proteger o lesado e não punir o sujeito.

### Conceitos
- **Lesão**: Ocorre quando uma pessoa se obriga a prestação manifestamente desproporcional ao valor da prestação oposta, devido à premente necessidade ou inexperiência.
- **Estado de Perigo**: Ocorre quando uma pessoa se aproveita da outra para levar vantagem, enquanto a outra experimenta prejuízo.
- **Dolo de Aproveitamento**: Fato de uma das partes se aproveitar da outra para levar vantagem, enquanto a outra experimenta prejuízo.

### Referências legais
- Art. 156 do Código Civil

### Jurisprudência
- RE 123456
- Enunciado 150 da Jornada de Direito Civil

### Dicas de prova
- Diferenciar entre lesão e estado de perigo
- Entender a importância do dolo de aproveitamento no estado de perigo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direito Civil", "legal_refs": ["Art. 156 do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado 150 da Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T20:09:50.352980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=83", "doc_key": "22585c63f5a4611e1c04779dd5b1d1b9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '251ac910b02d694a078e5094f0dde686db7ba26fd5b807d1adc86d37833b735f'),
  ('cpiuris2025::ac6e43f0d233ae51cbdd05103ce94d8a', 'doutrina', 'cp_iuris', 'Direito Civil — Lesão e Onerosidade Excessiva', '## Lesão e Onerosidade Excessiva

A lesão é uma causa de nulidade absoluta do negócio jurídico, enquanto a onerosidade excessiva pode ser resolvida por meio de revisão ou extinção do contrato.

### Conceitos
- **Lesão**: causa de nulidade absoluta do negócio jurídico
- **Onerosidade Excessiva**: prestação excessivamente onerosa para uma das partes
- **Teoria da Imprevisão**: contrato válido, mas com prestação excessivamente onerosa devido a fato imprevisível e inevitável

### Referências legais
- Art. 157 do Código Civil
- Art. 478 do Código Civil

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre lesão e onerosidade excessiva
- Entender a teoria da imprevisão e sua relação com os contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direito Civil", "legal_refs": ["Art. 157 do Código Civil", "Art. 478 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T20:10:15.686860+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=83", "doc_key": "ac6e43f0d233ae51cbdd05103ce94d8a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f9f08095fce9742dd161c95d75d3a665212749caf93a37ddf315045725588bc3'),
  ('cpiuris2025::f1f59cae8f29fc2998b93191067c966f', 'doutrina', 'cp_iuris', 'Direito Civil — Fraude contra Credores', '## Fraude contra Credores

A fraude contra credores é um vício social do negócio jurídico, passível de anulabilidade. É uma ação própria denominada Ação Pauliana, que tem o mesmo sentido de uma ação anulatória, mas não pode ser suscitada por via incidental.

### Conceitos
- **Vício social**: Ocorre quando há um defeito no negócio jurídico
- **Ação Pauliana**: Ação própria para anular o contrato devido à fraude contra credores
- **Anulabilidade**: O negócio jurídico pode ser anulado
- **Obrigação**: Relação estática do direito civil, onde quem detém o débito é o devedor
- **Haftung**: Responsabilidade patrimonial, relação dinâmica do direito processual civil

### Referências legais
- Art. 158 do CC
- Art. 165 do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre anulabilidade e fraude contra credores
- Conheça o conceito de Ação Pauliana e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Direito Civil", "legal_refs": ["Art. 158 do CC", "Art. 165 do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:10:47.562446+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=84", "doc_key": "f1f59cae8f29fc2998b93191067c966f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '24407ec0a97c1a65b99bb36d637892e86f810d760ce2722ab5705afeab50625f'),
  ('cpiuris2025::897c4f2c72079fae9a119a1327a91fac', 'doutrina', 'cp_iuris', 'Direito Civil — Fraude contra Credores', '## Fraude contra Credores

A fraude contra credores é um negócio jurídico que pode ser anulado, mas não necessariamente gera a ineficácia do negócio. A recente decisão do STJ 66 (REsp nº 1294462/GO) entendeu que não é mais necessária prova do elemento subjetivo (consilium fraudis), basta comprovar os elementos de anterioridade, prejuízo, redução da insolvência e conhecimento do terceiro.

### Conceitos
- **Fraude contra Credores**: Negócio jurídico que pode ser anulado
- **Ineficácia**: Efeitos negados ao negócio jurídico em relação a um credor específico
- **Anulação**: Ato judicial que declara o negócio jurídico nulo
- **Simulação**: Negócio jurídico nulo por não ter sido feito com a intenção de criar um direito real
- **Consilium fraudis**: Intenção maliciosa do devedor de causar dano

### Referências legais
- Art. 184 da CC/2002
- Súmula 346 STJ

### Jurisprudência
- REsp nº 1294462/GO (STJ 66)

### Dicas de prova
- Entenda a diferença entre anulação e ineficácia
- Conheça os elementos necessários para comprovar a fraude contra credores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Direito Civil", "legal_refs": ["Art. 184 da CC/2002", "Súmula 346 STJ"], "jurisprudence": ["REsp nº 1294462/GO (STJ 66)"], "confidence": 0.8, "extracted_at": "2026-05-25T20:11:32.814665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=84", "doc_key": "897c4f2c72079fae9a119a1327a91fac"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7f9c8b172b95e7192407b5e8daa3d0fce27f120502a175d07139579ed36ea8fc'),
  ('cpiuris2025::8c1a86ca1c4a52d0033b67a83f327e4a', 'doutrina', 'cp_iuris', 'Direito Civil — Fraude contra Credores', '## Fraude contra Credores

Descreve a fraude à execução como diminuição patrimonial propositada do devedor para reduzir-se à insolvência, prejudicando o credor e considerada ato atentatório à dignidade da justiça.

### Conceitos
- **Fraude à execução**: Diminuição patrimonial propositada do devedor para reduzir-se à insolvência
- **Legitimidade passiva**: Quem responde na ação pauliana: devedor insolvente, pessoa que com ele contratou e terceiro de má-fé
- **Litisconsórcio passivo**: Necessário entre os legitimados passivos
- **Simulação**: Vício social que visa prejudicar uma terceira pessoa, não definida

### Referências legais
- Art. 792 do Código de Processo Civil

### Jurisprudência
- REsp. 242.151, MG; Súmula 195 do STJ

### Dicas de prova
- Pegar a diferença entre fraude contra credores e simulação
- Entender o conceito de legitimidade passiva na ação pauliana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direito Civil", "legal_refs": ["Art. 792 do Código de Processo Civil"], "jurisprudence": ["REsp. 242.151, MG; Súmula 195 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T20:12:05.127406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=85", "doc_key": "8c1a86ca1c4a52d0033b67a83f327e4a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1e4d02c3c7eec6fe4b3abae8945fb7818bb9b2ee340683112d7043246b30f9ac'),
  ('cpiuris2025::c3b7ffe3162aee759cc7aa3f417128e8', 'doutrina', 'cp_iuris', 'Direito Civil — Simulação em Direito Civil', '## Simulação em Direito Civil

A simulação absoluta é quando as partes fingem a criação de um negócio que não existe, enquanto a simulação relativa é quando as partes pretendem realizar um negócio prejudicial a terceiro ou com intuito de fraudar a lei, mas realizam um ato diverso para ocultar o ato verdadeiramente desejado.

### Conceitos
- **Simulação Absoluta**: Fingimento da criação de um negócio que não existe
- **Simulação Relativa**: Realização de um ato diverso para ocultar o ato verdadeiramente desejado
- **Dissimulado**: O ato verdadeiramente desejado, mas ocultado

### Referências legais
- Art. 195 do STJ
- Súmula 195 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre simulação absoluta e relativa
- Entender o conceito de dissimulado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direito Civil", "legal_refs": ["Art. 195 do STJ", "Súmula 195 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:12:31.274283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=85", "doc_key": "c3b7ffe3162aee759cc7aa3f417128e8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bcea2e143531842862b2e22d4601b1f57fa2e2567d0a1612b903e26c909e3c1b'),
  ('cpiuris2025::e9cc27aeecea68111933abe12a8c1824', 'doutrina', 'cp_iuris', 'Direito Civil — Simulação Relativa', '## Simulação Relativa

A simulação relativa é uma modalidade de simulação que não envolve intenção de prejudicar terceiros ou violar a lei, sendo nula de acordo com o código civil de 1916.

### Conceitos
- **Simulação Relativa**: Modalidade de simulação que não envolve intenção de prejudicar terceiros ou violar a lei
- **Simulação Inocente**: Modalidade prevista no código civil de 1916, abarcando uma simulação desprovida de intenção de prejudicar terceiros ou violar a lei
- **Fraude contra Credores**: Vício social que envolve a prática de atos jurídicos com o intuito de prejudicar credores

### Referências legais
- Art. 123 do Código Civil
- Súmula 195 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre simulação

### Dicas de prova
- Distinção entre simulação relativa e inocente
- Conhecimento da fraude contra credores como vício social
- Interpretação literal do STJ em relação à simulação em embargos de terceiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Direito Civil", "legal_refs": ["Art. 123 do Código Civil", "Súmula 195 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre simulação"], "confidence": 0.8, "extracted_at": "2026-05-25T20:13:14.856759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=86", "doc_key": "e9cc27aeecea68111933abe12a8c1824"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd9aa905df586e816b9df1983b1198ad8f3b719f1793f31befa127ce40ebbed61'),
  ('cpiuris2025::2b5da6b2c21b9a71f5c2c40efe2d90cf', 'doutrina', 'cp_iuris', 'Direito Civil — Nulidade', '## Nulidade

A nulidade pode ser absoluta ou relativa, ofendendo normas de ordem pública e interesse particular, respectivamente.

### Conceitos
- **nulidade absoluta**: ofende as normas de ordem pública
- **nulidade relativa**: ofende norma de interesse particular
- **convalidação**: pode ser feita por vontade das partes

### Referências legais
- Art. 234 do CC/2016
- ...

### Jurisprudência
- RE 123456
- Súmula 153 da III Jornada de Direito Civil

### Dicas de prova
- Diferenciar entre nulidade absoluta e relativa
- Entender a natureza da ação declaratória de nulidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Direito Civil", "legal_refs": ["Art. 234 do CC/2016", "..."], "jurisprudence": ["RE 123456", "Súmula 153 da III Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T20:13:35.219142+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=86", "doc_key": "2b5da6b2c21b9a71f5c2c40efe2d90cf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5e08641146172c0a2521f574cdba78f6e64dabb079e48c3dd3e9dff11194ad96'),
  ('cpiuris2025::66c9ff493ca110516afc6d4821760877', 'doutrina', 'cp_iuris', 'Direito Civil — Ação Anulatória e Nulidade do Negócio Jurídico', '## Ação Anulatória e Nulidade do Negócio Jurídico

Resumo objetivo: A ação anulatória é reconhecida por meio de sentença declaratória com efeitos ex tunc, retroativos. A ação pode ser ajuizada pelo interessado ou pelo Ministério Público. O prazo para ajuizar a ação anulatória é de 2 anos ou 4 anos, dependendo do defeito. O negócio jurídico é nulo se for celebrado por pessoa absolutamente incapaz, ilícito, impossível ou indeterminável o seu objeto, etc.

### Conceitos
- **Ação Anulatória**: Procedimento para anular um negócio jurídico
- **Efeitos Ex Tunc e Retroativos**: Sentença declaratória produz efeitos ex tunc, retroativos
- **Prazo para Ajuizar a Ação Anulatória**: 2 anos ou 4 anos, dependendo do defeito
- **Negócio Jurídico Nulo**: Celebrado por pessoa absolutamente incapaz, ilícito, impossível ou indeterminável o seu objeto, etc.

### Referências legais
- Art. 179 do Código Civil
- CC, art. 178

### Jurisprudência
- RE 123456
- Tema repetitivo da ação anulatória

### Dicas de prova
- Diferenciar entre ação anulatória e sentença declaratória
- Entender o prazo para ajuizar a ação anulatória
- Conhecer as hipóteses de negócio jurídico nulo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direito Civil", "legal_refs": ["Art. 179 do Código Civil", "CC, art. 178"], "jurisprudence": ["RE 123456", "Tema repetitivo da ação anulatória"], "confidence": 0.8, "extracted_at": "2026-05-25T20:14:17.097570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=87", "doc_key": "66c9ff493ca110516afc6d4821760877"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '067d118088313aff9bbbbd2f9f9b59d0d5f639921e70c6aacb6c0bafc308d134'),
  ('cpiuris2025::b8367a69631bb034399006450a310304', 'doutrina', 'cp_iuris', 'Direito Civil — Representação e Autocontratos', '## Representação e Autocontratos

O Código Civil estabelece regras para a representação e autocontratos, destacando a importância dos poderes de representação conferidos por lei ou pelo interessado.

### Conceitos
- **Anulabilidade**: Negócio jurídico que pode ser anulado
- **Convalidação**: Ação de reconhecer a validade de um negócio jurídico anulável
- **Poderes de representação**: Autorização legal ou do interessado para agir em nome de outrem
- **Representante**: Pessoa autorizada a agir em nome de outrem
- **Representado**: Pessoa cuja vontade é representada por outro
- **Autocontrato**: Contrato feito pelo próprio indivíduo, sem a intervenção de terceiros

### Referências legais
- Art. 170 do Código Civil
- Art. 172 do Código Civil
- Art. 116 do Código Civil
- Art. 117 do Código Civil

### Dicas de prova
- Entenda a diferença entre anulabilidade e convalidação
- Conheça os poderes de representação e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direito Civil", "legal_refs": ["Art. 170 do Código Civil", "Art. 172 do Código Civil", "Art. 116 do Código Civil", "Art. 117 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:14:57.052916+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=87", "doc_key": "b8367a69631bb034399006450a310304"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5d65adc03a61988d6f0de11db1ae18ad29214d17419f81748b2e1bc8b6063670'),
  ('cpiuris2025::7decc057996601adca80b1d195004d5e', 'doutrina', 'cp_iuris', 'Direito Civil — Autocontrato', '## Autocontrato

O autocontrato é um contrato celebrado por uma pessoa representada, onde o representante só pode fazer contrato consigo mesmo quando a lei ou o próprio representado der poderes específicos para tanto. A validade do autocontrato é questionada, com alguns entendendo que não tem validade devido à falta de acordo de vontades, enquanto outros defendem sua validade desde que não haja conflito de interesses.

### Conceitos
- **Autocontrato**: Contrato celebrado por uma pessoa representada
- **Conflito de interesses**: Situação em que os interesses do representante e do representado são opostos
- **Poderes específicos**: Autorização do representado para o representante celebrar contratos em seu nome

### Referências legais
- Art. 117, parágrafo único, do Código Civil
- Súmula 242 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456
- Autocontrato: tema repetitivo

### Dicas de prova
- Distinção entre autocontrato e contrato com terceira pessoa
- Importância da ausência de conflito de interesses no autocontrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direito Civil", "legal_refs": ["Art. 117, parágrafo único, do Código Civil", "Súmula 242 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456", "Autocontrato: tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-25T20:15:29.917567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=88", "doc_key": "7decc057996601adca80b1d195004d5e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ee04576fc281cd59c9377ee6d8da129c04870bc664c02c5fc3df519bbccbfef8'),
  ('cpiuris2025::21e0601cdbca8adfe5fcc062100302d0', 'doutrina', 'cp_iuris', 'Direito Civil — Condição no Código Civil', '## Condição no Código Civil

A condição é uma cláusula que subordina o efeito do negócio jurídico a um evento futuro e incerto, derivado exclusivamente da vontade das partes.

### Conceitos
- **Condição**: Cláusula que subordina o efeito do negócio jurídico a um evento futuro e incerto
- **Vontade das partes**: Elemento fundamental da condição, que permite que as partes instituam a cláusula e não a lei
- **Futuridade**: O objeto da condição deve ser futuro, não podendo versar sobre fatos passados ou presentes
- **Incerteza**: Elemento necessário para que a condição seja válida

### Referências legais
- Art. 121 do Código Civil

### Dicas de prova
- Entenda a noção de vontade das partes e sua importância na condição
- Futuridade é um elemento fundamental para que a condição seja válida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direito Civil", "legal_refs": ["Art. 121 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:15:56.259647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=88", "doc_key": "21e0601cdbca8adfe5fcc062100302d0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7d62688429bee0e1c6872993208a6566f6d37d2c7f8c90784259761eada9f01e'),
  ('cpiuris2025::e9d063ea8a067097df6ead1407d907a8', 'doutrina', 'cp_iuris', 'Direito Civil — Condições no Código Civil', '## Condições no Código Civil

As condições são cláusulas que podem ser lícitas ou ilícitas, e podem ser causais, potestativas ou mistas. As condições lícitas não contrariam a lei, a ordem pública ou os bons costumes. As condições ilícitas invalidam o negócio jurídico de forma integral.

### Conceitos
- **Condição**: cláusula que pode ser lícita ou ilícita
- **Licitude**: não contraria a lei, a ordem pública ou os bons costumes
- **Ilicitude**: invalida o negócio jurídico de forma integral
- **Causalidade**: decorre de fato alheio à vontade das partes
- **Potestatividade**: sujeta os efeitos do negócio jurídico ao puro arbítrio de uma das partes
- **Mistura**: depende da vontade das partes e de um terceiro ao mesmo tempo

### Referências legais
- Art. 122 do Código Civil

### Jurisprudência
- Súmula 72 do STJ

### Dicas de prova
- Entenda a diferença entre condições lícitas e ilícitas
- Conheça as diferentes formas de condição (causal, potestativa, mista)
- Avalie se uma condição é válida ou não', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Direito Civil", "legal_refs": ["Art. 122 do Código Civil"], "jurisprudence": ["Súmula 72 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T20:16:42.704670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=89", "doc_key": "e9d063ea8a067097df6ead1407d907a8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8981aed89b2d50a2784b1488ad572c1453210fdfabf8dac67f71ba449d568d38'),
  ('cpiuris2025::2f239dedfda5a0088a22605d8e824787', 'doutrina', 'cp_iuris', 'Direito Civil — Condições no Direito Civil', '## Condições no Direito Civil

Resumo objetivo: Condição de meramente potestativa é válida se subordina a vontade do credor a um interesse juridicamente relevante. Existe vedação ao tipo de condição conhecido como contraditória, prevista no art. 122 do Código Civil, que priva todo o efeito do negócio jurídico.

### Conceitos
- **Condição de meramente potestativa**: Válida se subordina a vontade do credor a um interesse juridicamente relevante
- **Condição contraditória**: Privam todo o efeito do negócio jurídico, prevista no art. 122 do Código Civil
- **Possibilidade**: Pode ser física ou juridicamente impossível
- **Condição possível**: Física ou juridicamente impossível
- **Condição impossível**: Não pode ser cumprida fisicamente nem juridicamente

### Referências legais
- Art. 122 do Código Civil

### Jurisprudência
- REsp 1.990.221-SC
- Súmula 735 STJ

### Dicas de prova
- Entenda a diferença entre condição de meramente potestativa e contraditória
- Conheça as possibilidades e impossibilidades das condições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.89 (2)", "page_number": 89, "discipline": "Direito Civil", "legal_refs": ["Art. 122 do Código Civil"], "jurisprudence": ["REsp 1.990.221-SC", "Súmula 735 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T20:17:14.022966+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=89", "doc_key": "2f239dedfda5a0088a22605d8e824787"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6c48189aeed06357419b21f5a61fd931db858f8651da9da845e62f75ce02fff7'),
  ('cpiuris2025::a696bd29a79e822249943cf64298846f', 'doutrina', 'cp_iuris', 'Direito Civil — Condições Suspensivas e Resolutivas no Código Civil', '## Condições Suspensivas e Resolutivas no Código Civil

Explica as condições suspensivas e resolutivas em negócios jurídicos, destacando a diferença entre elas e a retroatividade da condição resolutiva.

### Conceitos
- **Condição Suspensiva**: Impede a aquisição e o exercício do direito até que ocorra um evento futuro e incerto.
- **Condição Resolutiva**: Não suspende a aquisição ou o exercício do direito, mas extingue-o após o ocorrer de um evento futuro e certo.
- **Retroatividade da Condição Resolutiva**: Extinção do direito para todos os efeitos, salvo disposição em contrário.
- **Termo Convencional**: Cláusula que subordina a eficácia do negócio a um evento futuro e certo.

### Referências legais
- Art. 128 do Código Civil

### Dicas de prova
- Diferenciar entre condições suspensivas e resolutivas
- Entender a retroatividade da condição resolutiva
- Identificar o termo convencional em um negócio jurídico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito Civil", "legal_refs": ["Art. 128 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:17:51.329176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=90", "doc_key": "a696bd29a79e822249943cf64298846f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2eb2d83065cb3c30bbce50943b6054e11a994d5f3e199d67be2db450c80a5f6c'),
  ('cpiuris2025::1077f9b62143e3862e6b514cd85e6458', 'doutrina', 'cp_iuris', 'Direito Civil — Conceito de termo e condição em contratos', '## Conceito de termo e condição em contratos

Resumo objetivo: O texto destaca a distinção entre termo e condição em contratos, destacando que a morte no contrato de seguro de vida é um termo, enquanto a doação de dinheiro a um filho é uma condição. Além disso, são apresentados os tipos de termos ( inicial, final, convencional, etc.) e sua relação com as condições resolutivas.

### Conceitos
- **Termo**: Elemento que marca o início ou fim de um contrato
- **Condição**: Pressuposição de incerteza em um contrato
- **Termo inicial**: Márca o início do contrato
- **Termo final**: Põe fim ao elemento acidental
- **Condição resolutiva**: Pressupõe incerteza e resolve o contrato

### Referências legais
- Art. 157 do CC/2016

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a distinção entre termo e condição em contratos
- Entenda os tipos de termos (inicial, final, convencional) e sua relação com as condições resolutivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito Civil", "legal_refs": ["Art. 157 do CC/2016"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T20:18:30.430304+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=90", "doc_key": "1077f9b62143e3862e6b514cd85e6458"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0cb66aeb2424722af73bfcbd7cc88dadbb53fc5e0efd2594da508d625e44bdd8'),
  ('cpiuris2025::12d5f2e4a0ee8f344c0dd220925fb67f', 'doutrina', 'cp_iuris', 'Direito Civil — Encargos ou Modo', '## Encargos ou Modo

O encargo é uma determinação que obriga o beneficiário, imposta pelo autor por liberalidade, e não pode ser aposta em negócio oneroso. O art. 136 do Código Civil estabelece que o encargo não suspende a aquisição ou exercício do direito.

### Conceitos
- **Encargo**: determinação que obriga o beneficiário
- **Beneficiário**: parte que recebe a determinação
- **Liberalidade**: ação de instituir um encargo sem contraprestação
- **Negócio oneroso**: transação em que uma parte cede algo em troca de outra coisa
- **Condição suspensiva**: subordinação do negócio a um evento ou ato

### Referências legais
- Art. 136 do Código Civil

### Dicas de prova
- Prestar atenção aos elementos do negócio para determinar se é encargo ou condição suspensiva
- Não confundir o encargo com a liberalidade
- Entender que o terceiro beneficiário não está legitimado a propor ação revocatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direito Civil", "legal_refs": ["Art. 136 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:19:02.073775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=91", "doc_key": "12d5f2e4a0ee8f344c0dd220925fb67f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '729012f07d8b62d72f8cbc5c92aa0a475836d9d6f2ec62fef1428db8fed4431b'),
  ('cpiuris2025::c7139f7fac97a8d86e9058777883b274', 'doutrina', 'cp_iuris', 'Direito Civil — Ilícito Civil', '## Ilícito Civil

O ato ilícito é conduta humana que ofende o ordenamento jurídico, podendo ser civil, penal ou administrativo. O ilícito civil pode ser extracontratual (responsabilidade aquiliana) ou contratual.

### Conceitos
- **Ilícito Civil**: conduta humana que ofende o ordenamento jurídico
- **Responsabilidade Aquiliana**: ofensa a um dever jurídico de não lesar outrem
- **Dever Jurídico**: obrigação de não causar dano a outrem

### Referências legais
- Art. 186 do Código Civil

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre ilícito civil e contratual.
- Conheça a responsabilidade aquiliana e seus princípios básicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T20:19:25.586396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=91", "doc_key": "c7139f7fac97a8d86e9058777883b274"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bd321a3bac39752afa47dee06e55e433a75aa5a8c4e4389a66c999591eb67243'),
  ('cpiuris2025::696f274aaa5c8ff0cd4b2ad5b5a2d5ec', 'doutrina', 'cp_iuris', 'Direito Civil — Atos Ilícitos e Abuso do Direito', '## Atos Ilícitos e Abuso do Direito

O ato ilícito é o ato que dá surgimento à responsabilidade civil extracontratual, gerando o dever de indenizar. O abuso do direito é o exercício de forma abusiva ou irregular do direito.

### Conceitos
- **Ato Ilícito**: ato que dá surgimento à responsabilidade civil extracontratual
- **Abuso do Direito**: exercício de forma abusiva ou irregular do direito
- **Responsabilidade Civil Extracontratual**: responsabilidade por ato ilícito que não está relacionado a um contrato
- **Dever de Indenizar**: obrigação de pagar indenização ao lesado

### Referências legais
- Art. 187 do Código Civil
- Art. 188 do Código Civil

### Dicas de prova
- Fins econômicos, fins sociais, boa-fé e bons costumes são conceitos jurídicos indeterminados que ajudam a definir o abuso do direito.
- A responsabilidade objetiva não se discute a presença ou não de culpa no ato ilícito.
- O abuso do direito é causa de responsabilidade civil extracontratual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direito Civil", "legal_refs": ["Art. 187 do Código Civil", "Art. 188 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:20:08.207856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=92", "doc_key": "696f274aaa5c8ff0cd4b2ad5b5a2d5ec"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd0cbe70a174d0e398a41ad422564061a1754d87b95d6a258d56f4741d4d9368f'),
  ('cpiuris2025::7640f71493453be09f1c4e1dfbba6740', 'doutrina', 'cp_iuris', 'Direito Civil — Legítima Defesa, Estado de Necessidade e Exercício Regular de Direito', '## Legítima Defesa, Estado de Necessidade e Exercício Regular de Direito

Atos lícitos: legítima defesa, estado de necessidade e exercício regular de direito. Legítima defesa é ato para se defender de agressão injusta; estado de necessidade é lesão a bem ou pessoa para remover perigo iminente; exercício regular de direito é atuação amparada pelo ordenamento jurídico.

### Conceitos
- **Legítima Defesa**: Ato para se defender de agressão injusta
- **Estado de Necessidade**: Lesão a bem ou pessoa para remover perigo iminente
- **Exercício Regular de Direito**: Atuação amparada pelo ordenamento jurídico

### Referências legais
- Art. 186 do Código Civil

### Jurisprudência
- Enunciado 37 da I Jornada de Direito Civil

### Dicas de prova
- Distinção entre legítima defesa e estado de necessidade
- Entendimento do critério objetivo-finalístico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil"], "jurisprudence": ["Enunciado 37 da I Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T20:20:33.002823+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=92", "doc_key": "7640f71493453be09f1c4e1dfbba6740"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ebed86c82e193cbd8478ab3eb3aee3773cbe07289ceb4b4c7976801001d843c6'),
  ('cpiuris2025::cd3bd8098050e6aa5ce33d9aced7b804', 'doutrina', 'cp_iuris', 'Direito Civil — Atos lícitos e dever de indenizar', '## Atos lícitos e dever de indenizar

A prática de ato lícito não gera obrigação de indenizar, mas existe exceção quando a pessoa agressa terceiro para remover perigo iminente.

### Conceitos
- **Atos lícitos**: Práticas legais e éticas
- **Dever de indenizar**: Obrigação de compensar o dano causado
- **Estado de necessidade agressivo**: Situção em que a pessoa agressa terceiro para remover perigo iminente
- **Estado de necessidade defensivo**: Situação em que a pessoa não é obrigada a indenizar por causa própria
- **Direito de regresso**: O direito do causador do dano para se indenizar

### Referências legais
- Art. 929 do Código Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre estado de necessidade agressivo e defensivo
- Análise da exceção ao dever de indenizar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direito Civil", "legal_refs": ["Art. 929 do Código Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:21:03.497149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=93", "doc_key": "cd3bd8098050e6aa5ce33d9aced7b804"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1a05ca391a86a27cb2ee19df096c8f2b38f5aff49d9115e002ef2dff8ac7d9df'),
  ('cpiuris2025::d29cf614078dac2771714818ef8b99ba', 'doutrina', 'cp_iuris', 'Direito Civil — Prescrição e Princípio da Segurança Jurídica', '## Prescrição e Princípio da Segurança Jurídica

A prescrição não comete o erro do Código revogado, pois não há confusão entre direito de ação e prescrição. A pretensão nasce quando o direito subjetivo é violado e deve ser exercida dentro de um lapso temporal para evitar a prescrição.

### Conceitos
- **Princípio da Segurança Jurídica**: Não permitir que o credor se eternize em um crédito
- **Prescrição**: Ocorre quando não é exercida a pretensão dentro de um lapso temporal
- **Direito de Ação**: Direito subjetivo que surge quando o direito é violado
- **Coisa Julgada**: Instituto jurídico que protege a segurança jurídica
- **Direito Adquirido**: Direito que se adquire por meio de uma relação jurídica
- **Lapso Temporal**: Prazo dentro do qual deve ser exercida a pretensão
- **Eternização de Crédito**: O credor pode exercer o direito infinitamente em face do devedor

### Referências legais
- Art. 185 do Código Civil de 2002

### Dicas de prova
- Entenda a dualidade conceitual da prescrição
- Identifique o princípio da segurança jurídica como base para a prescrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direito Civil", "legal_refs": ["Art. 185 do Código Civil de 2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:21:47.668612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=93", "doc_key": "d29cf614078dac2771714818ef8b99ba"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '75339eb9f6c9542c0138bed6025cb928c55176e07f4c6945acfac450f8a9845d'),
  ('cpiuris2025::786136dca488662aa111e012b9fcadf4', 'doutrina', 'cp_iuris', 'Direito Civil — Prescrição Extintiva e Usucapião', '## Prescrição Extintiva e Usucapião

A prescrição extintiva libera o devedor da dívida, enquanto a usucapião é a prescrição aquisitiva que permite a aquisição de direitos. A prescrição extintiva também é conhecida como prescrição liberatória.

### Conceitos
- **Prescrição Extintiva**: Modo pelo qual o devedor é libertado da dívida
- **Usucapião**: Prescrição aquisitiva que permite a aquisição de direitos
- **Prescrição Liberatória**: Outro nome para a prescrição extintiva

### Referências legais
- Art. 190 do Código Civil
- Art. 191 do Código Civil
- Súmula 76 STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre prescrição extintiva e usucapião
- Entender a importância da renúncia da prescrição
- Conhecer as hipóteses de suspensão e interrupção do prazo prescricional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito Civil", "legal_refs": ["Art. 190 do Código Civil", "Art. 191 do Código Civil", "Súmula 76 STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T20:22:19.936395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=94", "doc_key": "786136dca488662aa111e012b9fcadf4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1cb8547b92597b07ced40c294af24ad70e8086638c7cba5ec4dfd4badffe3cb8'),
  ('cpiuris2025::6a720af45a59e65d64971a4c442c52fe', 'doutrina', 'cp_iuris', 'Direito Civil — Renúncia à Prescrição', '## Renúncia à Prescrição

A renúncia à prescrição é feita após a consumação do prazo e não prejudica terceiros, sendo expressa ou tácita. A renúncia tácita se presume em razão de comportamentos incompatíveis com a vontade de alegar a prescrição.

### Conceitos
- **Renúncia à Prescrição**: Ato pelo qual uma parte renuncia ao direito de alegar a prescrição
- **Consumação do Prazo**: Prazo prescricional se consumado, tornando impossível a renúncia
- **Credor do Devedor**: Existência de um credor do devedor impede a renúncia à prescrição
- **Renúncia Tácita**: Renúncia se presume em razão de comportamentos incompatíveis com a vontade de alegar a prescrição

### Referências legais
- Art. 185 do Código Civil

### Jurisprudência
- RE 123456
- STJ - REsp nº 149.186/RS
- STJ - REsp 1.250.583

### Dicas de prova
- Distinguir entre renúncia expressa e tácita
- Entender a importância da consumação do prazo e da existência de credores do devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito Civil", "legal_refs": ["Art. 185 do Código Civil"], "jurisprudence": ["RE 123456", "STJ - REsp nº 149.186/RS", "STJ - REsp 1.250.583"], "confidence": 0.8, "extracted_at": "2026-05-25T20:22:52.253577+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=94", "doc_key": "6a720af45a59e65d64971a4c442c52fe"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cc5ae3c53ef9b573dcc0d487f07ec71ccd42c5f09963425757b3dce754b76594'),
  ('cpiuris2025::dcfacc9f73905047e7de2b6e854647cf', 'doutrina', 'cp_iuris', 'Direito Civil — Renúncia e Prescrição', '## Renúncia e Prescrição

A renúncia prévia da prescrição não é admitida pelo Código Civil, pois a prescrição é matéria de ordem pública. O juiz pode reconhecer de ofício a prescrição, mas é necessário consultar as partes antes para promover o contraditório efetivo.

### Conceitos
- **Renúncia**: Ação pelo qual uma parte renuncia a um direito ou obrigação
- **Prescrição**: Processo pelo qual um direito é extinto pela falta de ação do devedor
- **Ordem Pública**: Materia que se refere a questões de interesse público, não sujeitas à vontade das partes
- **Contraditório**: O direito do devedor de se manifestar sobre uma questão antes da decisão do juiz
- **Decadência Legal**: A extinção automática de um direito por falta de ação do devedor, sem necessidade de prescrição

### Referências legais
- Art. 192 CC
- Art. 487, parágrafo único, CC
- Súmula 332 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre renúncia e prescrição
- Entender a importância do contraditório no processo
- Conhecer as regras de decadência legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito Civil", "legal_refs": ["Art. 192 CC", "Art. 487, parágrafo único, CC", "Súmula 332 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T20:23:40.381162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=95", "doc_key": "dcfacc9f73905047e7de2b6e854647cf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd394f9674672f8593ff7eb4ce34056bfec7cbdd2c0e1311fe240bc39f1344a51'),
  ('cpiuris2025::ed77180cc0ffe072c61d1bed3543adb0', 'doutrina', 'cp_iuris', 'Direito Civil — Prescrição e Preclusão', '## Prescrição e Preclusão

A prescrição não se curva à preclusão, podendo ser alegada em qualquer grau de jurisdição pela parte que a aprova. A regra do Código de Processo Civil de 1973 sobre honorários advocatícios foi abolida no novo Código.

### Conceitos
- **Prescrição**: Processo pelo qual um direito é perdido devido à passagem do tempo.
- **Preclusão**: Incapacidade de uma parte de defender seu direito em um processo.
- **Grau de Jurisdição**: Nível do tribunal que tem jurisdictividade sobre um caso.
- **Instâncias Ordinárias**: Tribunal de primeiro grau.
- **Prequestionamento**: Obrigação de uma parte de questionar todos os aspectos de um processo antes de apresentar sua defesa.

### Referências legais
- Art. 193 do Código Civil
- Art. 22 do Código de Processo Civil de 1973

### Dicas de prova
- Entenda a diferença entre prescrição e preclusão.
- Conheça as regras sobre alegação da prescrição em qualquer grau de jurisdição.
- Aprenda com a abolição do artigo que regulamentava os honorários advocatícios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito Civil", "legal_refs": ["Art. 193 do Código Civil", "Art. 22 do Código de Processo Civil de 1973"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:24:12.927564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=95", "doc_key": "ed77180cc0ffe072c61d1bed3543adb0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '985efdcfe492e5ae27d8a1292281bf7da0b9cebd30baf2f294311fe82c55f2d1'),
  ('cpiuris2025::f612c48bb8adc9c2625fd8a6a49d4e13', 'doutrina', 'cp_iuris', 'Direito Civil — Prescrição e Sucessão', '## Prescrição e Sucessão

A prescrição contra uma pessoa continua a correr contra o seu sucessor, de acordo com o art. 196 do Código Civil. A sucessão não interfere na prescrição, que flui independentemente dos sujeitos envolvidos.

### Conceitos
- **Prescrição**: Processo pelo qual um direito é perdido devido à passagem do tempo
- **Sucessão**: Transferência de propriedade ou direitos de uma pessoa para outra
- **Prazo prescricional**: Período durante o qual a prescrição pode ocorrer
- **Causa de impedimento**: Fato que impede a prescrição, como a morte ou a incapacidade do devedor
- **Suspensão da prescrição**: Prazo durante o qual a prescrição é suspensa, geralmente por motivo de impedimento ou suspensão
- **Interrupção da prescrição**: Fato que interrompe a prescrição, como a morte do devedor ou a resolução do litígio

### Referências legais
- Art. 196 do Código Civil
- Art. 921 do Código de Processo Civil
- Lei nº 14.382/2022, art. 206-A

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre prescrição e sucessão
- Conheça as causas de impedimento, suspensão e interrupção da prescrição
- Aprenda a aplicar o princípio da indiferença das vias em sede de prescrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direito Civil", "legal_refs": ["Art. 196 do Código Civil", "Art. 921 do Código de Processo Civil", "Lei nº 14.382/2022, art. 206-A"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:24:55.671670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=96", "doc_key": "f612c48bb8adc9c2625fd8a6a49d4e13"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8caadb55a3edb14a834239d1b9b15d4210260704e08a2cf3fa1d61ffc4258df6'),
  ('cpiuris2025::ec0639c04da09c3a8d21e729010faf9b', 'doutrina', 'cp_iuris', 'Direito Civil — Eficácia da Prescrição', '## Eficácia da Prescrição

A prescrição atinge a pretensão, não o direito subjetivo, e acarreta a cobrança extrajudicial.

### Conceitos
- **Direito Subjetivo**: direito que lhe é próprio ao indivíduo
- **Pretensão**: instituto de direito material, nascido com a violação do direito subjetivo da pessoa

### Referências legais
- Art. 185 do Código Civil de 1916
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre direito subjetivo e pretensão é fundamental
- A prescrição atinge a pretensão, não o direito subjetivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direito Civil", "legal_refs": ["Art. 185 do Código Civil de 1916", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:25:25.393073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=96", "doc_key": "ec0639c04da09c3a8d21e729010faf9b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0a3a9a04843cb7e759f372544ae097ac3df8151ba8f99f7b3da4d79d23058802'),
  ('cpiuris2025::90b1c27253a44e5af512d4ec09c6d8fb', 'doutrina', 'cp_iuris', 'Direito Civil — Cobrança Extrajudicial e Prescrição', '## Cobrança Extrajudicial e Prescrição

A decisão do STJ sobre a cobrança extrajudicial prescrita impede tanto a cobrança judicial quanto a cobrança extrajudicial do débito, tornando-a um abuso passível de reparação civil.

### Conceitos
- **Prescrição**: O processo pelo qual o direito é perdido devido à falta de ação ou inércia.
- **Cobrança Extrajudicial**: A ação de cobrar um débito sem recorrer ao sistema judicial.
- **Abuso do Direito**: Uso indevido ou excessivo de um direito, resultando em prejuízo para outrem.

### Referências legais
- Art. 198, I, do Código Civil
- STJ - REsp 2.088.100-SP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre cobrança judicial e extrajudicial.
- Conheça as hipóteses que impedem ou suspensam a prescrição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direito Civil", "legal_refs": ["Art. 198, I, do Código Civil", "STJ - REsp 2.088.100-SP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T20:25:56.276035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=97", "doc_key": "90b1c27253a44e5af512d4ec09c6d8fb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '17489bd253ba0348defda9ff30d32ffd1165f7418d0707e8fb57afa33055215b'),
  ('cpiuris2025::341b73ce2686055ead2f953b4dc06f2b', 'doutrina', 'cp_iuris', 'Direito Civil — Prescrição no contrato de prestação de serviços advocatícios', '## Prescrição no contrato de prestação de serviços advocatícios

A prescrição não corre em contrato de prestação de serviços advocatícios pendente condição suspensiva, de acordo com o inciso 199, I do Código Civil.

### Conceitos
- **Prescrição**: O período durante o qual uma ação pode ser iniciada contra um devedor
- **Condição suspensiva**: Um evento futuro e incerto que impede a aquisição e o exercício do direito
- **Código Civil**: A legislação civil brasileira

### Referências legais
- Art. 199, I, Código Civil
- Art. 125, Código Civil

### Jurisprudência
- STJ. REsp 1.605.604/MG
- Súmula 693

### Dicas de prova
- Distinção entre prescrição e condição suspensiva
- Importância da cláusula quota litis no contrato de prestação de serviços advocatícios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direito Civil", "legal_refs": ["Art. 199, I, Código Civil", "Art. 125, Código Civil"], "jurisprudence": ["STJ. REsp 1.605.604/MG", "Súmula 693"], "confidence": 0.8, "extracted_at": "2026-05-25T20:26:22.058743+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=97", "doc_key": "341b73ce2686055ead2f953b4dc06f2b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '66e9c01597765b78ceea4d48f0bcf1144a460ff91e8558e43f80b2cd343c9b6f'),
  ('cpiuris2025::414341e07177d3c26ab60d80314263bf', 'doutrina', 'cp_iuris', 'Direito Civil — Prazo Prescricional', '## Prazo Prescricional

O prazo prescricional só passa a fluir após a condição suspensiva, que é a liberação dos valores pelo Poder Judiciário. A prescrição pode ser suspenso ou interrompida por causas específicas.

### Conceitos
- **Suspensão da Prescrição**: O prazo prescricional só passa a fluir após a condição suspensiva
- **Interrupção da Prescrição**: O prazo prescricional volta a correr desde o início, sem possibilidade de reanidicação
- **Causas Suspensivas**: Causes que suspendem o prazo prescricional, como a responsabilidade criminal definida
- **Causas Interruptivas**: Causes que interrompem o prazo prescricional, como a sentença penal transitada em julgado

### Referências legais
- Art. 200 do Código Civil
- Art. 201 do Código Civil
- Art. 202 do Código Civil
- Art. 203 do Código Civil
- Art. 204 do Código Civil

### Dicas de prova
- Diferencie entre suspensão e interrupção da prescrição
