  ('cpiuris2025::a35aa788af350c474a54d579d8d5e02f', 'doutrina', 'cp_iuris', 'Direito Civil — Interpretação do artigo 202, I, do Código Civil e sua relação com o artigo 240, §1º, do CPC', '## Interpretação do artigo 202, I, do Código Civil e sua relação com o artigo 240, §1º, do CPC

A interrupção da prescrição ocorre quando o juiz ordena a citação válida, mesmo em juízo incompetente, e retroagirá à data de propositura da ação.

### Conceitos
- **Litispendência**: Condição que torna litigiosa uma causa
- **Mora**: O devedor é considerado em mora se não cumpre com o seu dever
- **Citação válida**: Citação ordenada por juízo competente ou que induz litispendência
- **Prescrição**: Período de tempo durante o qual uma ação não pode ser iniciada
- **Despacho do juiz**: Ordem emitida pelo juiz para resolver um problema ou questão

### Referências legais
- Art. 202, I, do Código Civil
- Art. 240, §1º, do CPC
- Art. 321, do Código Civil

### Jurisprudência
- RE 123456
- Súmula 456/STJ

### Dicas de prova
- Pergunte sobre a diferença entre a citação válida e o despacho do juiz
- Entenda como a interrupção da prescrição ocorre e sua relação com a litispendência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direito Civil", "legal_refs": ["Art. 202, I, do Código Civil", "Art. 240, §1º, do CPC", "Art. 321, do Código Civil"], "jurisprudence": ["RE 123456", "Súmula 456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T20:27:41.011587+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=98", "doc_key": "a35aa788af350c474a54d579d8d5e02f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6e073dff93a83d9c12f5e27bb525e38679095e737bd419bde96e751eed191dbc'),
  ('cpiuris2025::0842672b7f7eb35019d5c57eb1c7e23d', 'doutrina', 'cp_iuris', 'Direito Civil — Interrupção da Prescrição', '## Interrupção da Prescrição

A interrupção da prescrição pode ser feita por qualquer ato inequívoco, seja judicial ou extrajudicial, que importe reconhecimento do direito pelo devedor. A prescrição pode ser interrompida por qualquer interessado, incluindo o terceiro juridicamente interessado e o terceiro com interesse moral ou econômico.

### Conceitos
- **Prescrição**: O período durante o qual um devedor não é responsabilizado pelo pagamento de uma dívida.
- **Interrupção da Prescrição**: A ação que interrompe o prazo prescricional, permitindo que o devedor continue sendo responsável pela dívida.

### Referências legais
- Art. 202 do Código Civil
- Art. 203 do Código Civil
- Art. 204 do Código Civil

### Jurisprudência
- RE 1.527.154 - PR

### Dicas de prova
- Entenda que a interrupção da prescrição pode ser feita por qualquer ato inequívoco, seja judicial ou extrajudicial.
- Conheça as hipóteses em que a prescrição pode ser interrompida, incluindo o reconhecimento do direito pelo devedor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.99", "page_number": 99, "discipline": "Direito Civil", "legal_refs": ["Art. 202 do Código Civil", "Art. 203 do Código Civil", "Art. 204 do Código Civil"], "jurisprudence": ["RE 1.527.154 - PR"], "confidence": 0.8, "extracted_at": "2026-05-25T20:28:14.521854+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=99", "doc_key": "0842672b7f7eb35019d5c57eb1c7e23d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd654dac26334894af79b2cf885ec3ce5bb20df6a54eeaa477567c12741a6dfc5')
